/* (P5) the boot splash. s_boot is the first frame — an engraved
 * violet star, the NOCSIF wordmark, and an honest bring-up log that reveals
 * line by line before fading out to the watchface. s_booting swallows
 * button and palm actions until that fade starts, so nothing yanks the
 * splash away mid-boot. The psram/pmu/display/touch/rtc lines are already
 * known by the time nocsif_ui_init runs; the storage and usb lines instead
 * resolve from app_main's real init results, reported afterward via
 * nocsif_ui_boot_report_* and published across tasks through the volatile
 * *_rep flags plus preformatted detail buffers. All LVGL-object state
 * (s_boot*, the timer) is only ever touched on the LVGL task. NULL/0 until
 * nocsif_ui_init runs. */
static lv_obj_t   *s_boot;            /* the splash screen; NULL once the fade to the watchface starts */
static lv_obj_t   *s_boot_log;        /* the bring-up log column, with labels appended one by one */
static lv_obj_t   *s_boot_sd_lbl;     /* the 'storage' line, rewritten in place once SD reports in */
static lv_obj_t   *s_boot_usb_lbl;    /* the 'usb' line, rewritten in place once USB reports in */
static lv_timer_t *s_boot_timer;      /* the per-line reveal cadence timer; self-deletes once it reaches the gate */
static char        s_boot_txt[6][40]; /* a snapshot of lines [0..5], known at UI-up; [6..8] are live */
static uint8_t     s_boot_i;          /* the next log line index to reveal (0..8) */
static uint16_t    s_boot_wait;       /* reveal ticks spent holding at the gate, waiting on storage and usb */
static uint16_t    s_boot_gate_max;   /* the hold cap in ticks, roughly the time budget divided by the period; then it fails on */
static bool        s_booting;         /* true until the fade to the watchface starts */
static volatile bool s_boot_sd_rep;   /* whether app_main published the storage result yet; read on the LVGL task */
static volatile bool s_boot_usb_rep;  /* whether app_main published the usb result yet */
static char        s_boot_sd_detail[28];  /* the published storage detail ("ready" / "no card") */
static char        s_boot_usb_detail[28]; /* the published usb detail ("detached" / etc) */

/* (P4.5.3b) the HID keyboard "latched armed" flag. Tapping the HID row
 * on the USB picker connects HID transiently — it detaches again on leaving
 * the submenu — while long-pressing it latches HID on, so it persists
 * across navigation until the user switches to Detached (via Disconnect or
 * another mode) or long-presses again. LVGL-task state, only read/written
 * from row callbacks and the submenu's delete handler. */
static bool        s_hid_latched;

/* (P4.5.3b) the DuckyScript macro folder browsed by the Run Macro file picker; created by the user on the card, and the picker lists and runs whichever file is tapped (nocsif_ducky_request_run) */
#define UI_MACRO_DIR "/sd/ducky"

/* (M7 HID) the transport the shared Run Macro picker plays over; set by whichever screen drilled into it — the USB HID submenu sets USB (the M4 default), the BLE Keyboard screen sets BLE */
static nocsif_ducky_sink_t s_macro_sink = NOCSIF_DUCKY_SINK_USB;

/* Palm-to-sleep (design #34, a deliberate cover gesture): covering the
 * panel with a hand sleeps the watch, the same net effect as backing out to
 * Home and pressing PWR for screen-off. Two signals feed it: the CST9217's
 * own cover-screen gesture (nocsif_touch_cover(), the reliable one) and, as
 * a fallback, PALM_MIN_POINTS or more simultaneous contacts. The cover must
 * persist for PALM_HOLD_US before triggering sleep, rejecting an accidental
 * brush. Since the controller may only report the cover intermittently (or
 * just once), a brief gap with no real finger down is bridged
 * (PALM_GRACE_US, kept longer than HOLD so a one-shot gesture still reaches
 * the threshold) rather than resetting the timer. The cover itself is
 * swallowed — reported as RELEASED to LVGL — so it never registers as a tap
 * or gesture. This is time-based, so it's independent of the indev's poll
 * rate. */
#define PALM_MIN_POINTS  3                /* this many simultaneous contacts or more means a hand, not a finger */
#define PALM_HOLD_US     (400 * 1000)     /* how long the cover must persist before sleeping, roughly 0.4s */
#define PALM_GRACE_US    (600 * 1000)     /* bridges gaps in intermittent cover reports; kept longer than HOLD */

static int64_t s_palm_since;   /* esp_timer microseconds when the cover began; 0 means not covering */
static int64_t s_palm_last;    /* esp_timer microseconds of the last real covering frame, for the gap bridge */
static bool    s_palm_fired;   /* one sleep per cover episode; cleared when the cover lifts or the watch wakes */

static void palm_sleep_async(void *unused);   /* defined further down, with the lock/peek state machine */

/* The pointer indev's read callback: just reuses the CST9217 driver.
 * Coordinates are already in native form, so they pass through untransformed.
 * This is the sole reader of nocsif_touch_read now that main.c's separate
 * polling task is gone. Blocking I2C here is safe, since the port calls
 * this from the LVGL task with its mutex already held. It also runs the
 * palm-to-sleep detector. */
/* (P8 v2.6) double-tap-to-wake: while the panel sleeps, the touch
 * indev stays enabled (screen_sleep no longer disables it), so this read
 * callback keeps polling, but every touch is swallowed — reported as
 * RELEASED — so nothing navigates under the dark panel. Two quick taps
 * within WAKE_DTAP_US wake the watch. */
static void screen_wake(void);                 /* defined below, alongside the lock/sleep helpers */
#define WAKE_DTAP_US    420000                  /* the maximum gap allowed between the two taps, 0.42s */
#define WAKE_TAP_MAX_US 320000                  /* a tap's maximum press duration; a long hold doesn't count as a tap */
static bool    s_wake_down;                     /* the last polled finger-down state, for edge detection */
static int64_t s_wake_press_t0;                 /* the current press's start time */
static int64_t s_wake_tap1;                     /* the release time of the first tap; 0 means none is armed */

static void wake_from_touch_async(void *u) { (void)u; screen_wake(); lv_display_trigger_activity(NULL); }

static void wake_tap_detect(bool down, int64_t now)
{
    if (down && !s_wake_down) s_wake_press_t0 = now;              /* a press edge */
    if (!down && s_wake_down) {                                   /* a release edge: a tap just completed */
        bool quick = (now - s_wake_press_t0) < WAKE_TAP_MAX_US;
        if (quick && s_wake_tap1 != 0 && (now - s_wake_tap1) < WAKE_DTAP_US) {
            s_wake_tap1 = 0;
            lv_async_call(wake_from_touch_async, NULL);           /* a second quick tap arrived in time: wake */
        } else {
            s_wake_tap1 = quick ? now : 0;                        /* arms the first tap; reset on a long press */
        }
    }
    s_wake_down = down;
}

static void touch_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    nocsif_touch_point_t pts[NOCSIF_TOUCH_MAX_POINTS];
    int n = 0;
    esp_err_t r = nocsif_touch_read(pts, NOCSIF_TOUCH_MAX_POINTS, &n);
    int64_t now = esp_timer_get_time();

    /* While asleep: swallow every touch, never navigating under a black panel, but still watch for a double-tap wake. */
    if (nocsif_display_is_asleep()) {
        wake_tap_detect(r == ESP_OK && n > 0, now);
        s_pressed = false;
        data->state = LV_INDEV_STATE_RELEASED;
        data->point.x = s_last_x;
        data->point.y = s_last_y;
        return;
    }

    bool cover = nocsif_touch_cover();                          /* the hardware's cover-screen gesture */
    bool real_cover = cover || (r == ESP_OK && n >= PALM_MIN_POINTS);

    /* Bridges a brief gap in intermittent cover reports: still recently covering, just no real finger right now. */
    bool covering = real_cover ||
        (s_palm_since != 0 && n == 0 && (now - s_palm_last) < PALM_GRACE_US);

    if (covering) {
        if (s_palm_since == 0) {
            s_palm_since = now;
            ESP_LOGI(TAG, "palm: cover start (gesture=%d n=%d)", (int)cover, n);
        }
        if (real_cover) {
            s_palm_last = now;                                 /* only real frames refresh the bridge */
        }
        if (!s_palm_fired && (now - s_palm_since) >= PALM_HOLD_US) {
            s_palm_fired = true;
            ESP_LOGI(TAG, "palm: cover held -> sleep");
            lv_async_call(palm_sleep_async, NULL);             /* off the read callback: the watchface and panel are off */
        }
        s_pressed = false;                                     /* swallowed: a cover is never treated as a tap or swipe */
        data->state = LV_INDEV_STATE_RELEASED;
        data->point.x = s_last_x;
        data->point.y = s_last_y;
        return;
    }
    s_palm_since = 0;
    s_palm_fired = false;

    if (r == ESP_OK && n > 0) {
        s_last_x = pts[0].x;
        s_last_y = pts[0].y;
        s_pressed = true;
        data->state = LV_INDEV_STATE_PRESSED;
    } else {
        s_pressed = false;
        data->state = LV_INDEV_STATE_RELEASED;
    }
    data->point.x = s_last_x;
    data->point.y = s_last_y;
}

/* ===== section 4.8a companion: remote pointer, letting the phone
 * drive the UI ===== * A second LVGL pointer indev, fed by the companion
 * WS uplink. The phone sends watch-space touch points; nocsif_companion_touch
 * packs {x,y,pressed} into a single 32-bit word — an aligned store is
 * atomic on Xtensa, so no lock is needed across the httpd/LVGL tasks — and
 * remote_read_cb reports it, so taps, swipes, and dial drags from the phone
 * drive the shell exactly like the touchscreen would. The physical touch
 * keeps its own separate indev; whichever one produces events wins.
 * s_remote_last_us lets the mirror tick keep the watch awake while it's
 * being driven remotely. */
#define RPT_PACK(x, y, p) (((uint32_t)((p) & 1) << 30) | ((uint32_t)((y) & 0x7FFF) << 15) | ((uint32_t)((x) & 0x7FFF)))
static volatile uint32_t s_remote_pt;       /* packed as pressed<<30 | y<<15 | x */
static volatile int64_t  s_remote_last_us;   /* the last remote-touch time, gating the idle-reset */

/* Registered with wifi.c; called on the httpd task from the WS uplink. */
static void nocsif_companion_touch(int x, int y, int pressed)
{
    if (x < 0) x = 0; if (x >= NOCSIF_DISP_W) x = NOCSIF_DISP_W - 1;
    if (y < 0) y = 0; if (y >= NOCSIF_DISP_H) y = NOCSIF_DISP_H - 1;
    s_remote_pt = RPT_PACK(x, y, pressed ? 1 : 0);
    s_remote_last_us = esp_timer_get_time();
}
static void remote_read_cb(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    uint32_t v = s_remote_pt;
    data->point.x = (int32_t)(v & 0x7FFF);
    data->point.y = (int32_t)((v >> 15) & 0x7FFF);
    data->state   = (v & (1u << 30)) ? LV_INDEV_STATE_PRESSED : LV_INDEV_STATE_RELEASED;
}

/* Snaps every invalidated (redraw) area to a 2-pixel grid. The CO5300
 * addresses its RAM in 2px column/row units, so a partial flush on an odd
 * column or width gets written with a per-row offset, which shears the
 * content diagonally. Rounding the start down to even and the end up to
 * odd makes both the origin and the size even. This is safe at the edges,
 * since the panel's max coordinates (409, 501) are both odd, so a +-1
 * adjustment never exceeds the bounds. */
static void ui_rounder_cb(lv_area_t *area)
{
    area->x1 &= ~1;
    area->y1 &= ~1;
    area->x2 |= 1;
    area->y2 |= 1;
}

#if NOCSIF_UI_FLUSH_AUDIT
/* --- P2 render-once flush audit (debug, NOCSIF_UI_FLUSH_AUDIT) --- *
 * Counts genuine widget invalidations and tracks the largest dirty
 * rectangle; a 5s timer logs the tally. LVGL emits a synthetic
 * LV_EVENT_INVALIDATE_AREA from get_max_row during rendering itself — a
 * draw-buffer sizing probe — so the render pass is bracketed with
 * RENDER_START/READY and those synthetic events are skipped. All callbacks
 * run on the LVGL task. */
static volatile uint32_t s_inval_count;
static int32_t s_inval_max_px, s_inval_max_w, s_inval_max_h, s_inval_max_x, s_inval_max_y;
static volatile bool s_rendering;

static void render_start_cb(lv_event_t *e) { (void)e; s_rendering = true;  }
static void render_ready_cb(lv_event_t *e) { (void)e; s_rendering = false; }

static void inval_area_cb(lv_event_t *e)
{
    if (s_rendering) return;
    lv_area_t *a = lv_event_get_invalidated_area(e);
    int32_t w = a->x2 - a->x1 + 1;
    int32_t h = a->y2 - a->y1 + 1;
    s_inval_count++;
    if (w * h > s_inval_max_px) {
        s_inval_max_px = w * h;
        s_inval_max_w = w;  s_inval_max_h = h;
        s_inval_max_x = a->x1;  s_inval_max_y = a->y1;
    }
}

static void inval_report_timer_cb(lv_timer_t *t)
{
    (void)t;
    ESP_LOGI(TAG, "flush-audit: %u invalidations/5s; largest %ldx%ld @ (%ld,%ld) "
                  "[whole-screen 410x502 would mean a background repaint]",
             (unsigned)s_inval_count,
             (long)s_inval_max_w, (long)s_inval_max_h,
             (long)s_inval_max_x, (long)s_inval_max_y);
    s_inval_count = 0;
    s_inval_max_px = 0; s_inval_max_w = 0; s_inval_max_h = 0;
    s_inval_max_x = 0;  s_inval_max_y = 0;
}
#endif /* NOCSIF_UI_FLUSH_AUDIT */

#if NOCSIF_UI_FRAME_TIMING
/* --- Per-frame render pacing timing (debug, NOCSIF_UI_FRAME_TIMING)
 * --- * All callbacks and the report timer run on the LVGL task, so the
 * accumulators need no locking. period is the gap between consecutive
 * RENDER_START events, i.e. the visible frame cadence (composite time plus
 * waiting for the previous flush to free a buffer). A gap longer than
 * FT_IDLE_GAP_US means animation had actually stopped, so that
 * first-after-idle sample is dropped rather than counted as one enormous
 * frame. composite is START to READY, the CPU-side compositor cost of the
 * frame (this is where the orrery re-blit lives). */
#define FT_REPORT_MS    2000
#define FT_IDLE_GAP_US  200000   /* longer than this counts as an idle gap between motion bursts, not a frame */

static int64_t s_ft_prev_start;      /* microseconds; 0 means no previous START yet */
static int64_t s_ft_render_start;    /* microseconds; the START timestamp of the in-flight composite */
static uint32_t s_ft_n;              /* periods counted in this window */
static int64_t s_ft_sum, s_ft_min, s_ft_max;   /* period statistics, in microseconds */
static uint32_t s_ft_nr;             /* composites counted in this window */
static int64_t s_ft_rsum, s_ft_rmax;           /* composite statistics, in microseconds */

static void ft_render_start_cb(lv_event_t *e)
{
    (void)e;
    int64_t now = esp_timer_get_time();
    s_ft_render_start = now;
    if (s_ft_prev_start != 0) {
        int64_t period = now - s_ft_prev_start;
        if (period <= FT_IDLE_GAP_US) {
            s_ft_n++;
            s_ft_sum += period;
            if (s_ft_min == 0 || period < s_ft_min) s_ft_min = period;
            if (period > s_ft_max) s_ft_max = period;
        }
    }
    s_ft_prev_start = now;
}

static void ft_render_ready_cb(lv_event_t *e)
{
    (void)e;
    if (s_ft_render_start == 0) return;
    int64_t comp = esp_timer_get_time() - s_ft_render_start;
    s_ft_nr++;
    s_ft_rsum += comp;
    if (comp > s_ft_rmax) s_ft_rmax = comp;
}

static void ft_report_timer_cb(lv_timer_t *t)
{
    (void)t;
    if (s_ft_n == 0) return;   /* an idle window: say nothing */
    int64_t mean   = s_ft_sum / s_ft_n;
    int64_t spread = s_ft_max - s_ft_min;
    long    jit    = mean > 0 ? (long)(spread * 100 / mean) : 0;
    long    fps    = mean > 0 ? (long)(1000000 / mean) : 0;
    int64_t rmean  = s_ft_nr ? s_ft_rsum / s_ft_nr : 0;
    ESP_LOGI(TAG, "frame-timing: %u frames ~%ldfps | period mean=%ld min=%ld max=%ld us "
                  "spread=%ld (jit=%ld%%) | composite mean=%ld max=%ld us",
             (unsigned)s_ft_n, fps,
             (long)mean, (long)s_ft_min, (long)s_ft_max, (long)spread, jit,
             (long)rmean, (long)s_ft_rmax);
    s_ft_n = 0; s_ft_sum = 0; s_ft_min = 0; s_ft_max = 0;
    s_ft_nr = 0; s_ft_rsum = 0; s_ft_rmax = 0;
}
#endif /* NOCSIF_UI_FRAME_TIMING */

/* ---- USB mode picker (P4.5.3) ---- *
 * The #usb screen: a connection line, a mode band, and a hid-keyboard
 * band, per the mockup. Rows only signal the worker task — non-blocking,
 * LVGL-safe — since the USB mode server re-enumerates off the LVGL thread
 * by rewriting the active descriptor and calling
 * tud_disconnect()/tud_connect() (installed once, never uninstalled). Each
 * mode row shows a right-aligned status: its idle descriptor, "active"
 * (violet) when it's the current mode, or ".." while a switch toward it is
 * in flight. Tapping a mode row requests that mode; tapping the active row
 * (or the Disconnect row) returns to Detached (design #3). Per-row poll
 * timers are torn down along with their row, so they can never fire
 * against a freed label. */

typedef struct {
    nocsif_usb_mode_t mode;
    lv_obj_t         *status;   /* the right-aligned status label */
    const char       *desc;     /* the idle descriptor, a static string */
    lv_timer_t       *timer;    /* this row's status poll timer */
} usb_mode_ctx_t;

/* Frees a mode row's context, and deletes its timer, when the row is deleted — its screen is freed on back. */
static void usb_mode_row_deleted_cb(lv_event_t *e)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)lv_event_get_user_data(e);
    if (c->timer) {
        lv_timer_delete(c->timer);
    }
    free(c);
}

static void usb_mode_row_click_cb(lv_event_t *e)
{
    const usb_mode_ctx_t *c = (const usb_mode_ctx_t *)lv_event_get_user_data(e);
    /* These rows are File Share / Console — HID moved to its own drill
     * row — so picking either ends any latched HID session, matching the
     * design that HID stays armed "until switched detached," including to
     * another mode. */
    s_hid_latched = false;
    /* Tapping the currently live mode turns it off, back to Detached; otherwise it switches to it. */
    bool active = nocsif_usb_gadget_mode() == c->mode &&
                  nocsif_usb_gadget_state() == NOCSIF_USB_GADGET_ON;
    nocsif_usb_gadget_request_mode(active ? NOCSIF_USB_MODE_DETACHED : c->mode);
}

static void usb_mode_row_timer_cb(lv_timer_t *t)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)lv_timer_get_user_data(t);
    nocsif_usb_gadget_state_t st = nocsif_usb_gadget_state();
    const char *txt;
    lv_color_t col;
    if (st == NOCSIF_USB_GADGET_STARTING && nocsif_usb_gadget_target_mode() == c->mode) {
        txt = "..";     col = NOCSIF_STEEL;              /* switching toward this mode */
    } else if (nocsif_usb_gadget_mode() == c->mode && st == NOCSIF_USB_GADGET_ON) {
        txt = "active"; col = NOCSIF_VIOLET;             /* the live mode */
    } else {
        txt = c->desc;  col = NOCSIF_ASH;                /* the idle descriptor */
    }
    /* only touches the label on an actual change: under full_refresh, any label write repaints the whole frame */
    if (strcmp(lv_label_get_text(c->status), txt) != 0) {
        lv_label_set_text(c->status, txt);
        lv_obj_set_style_text_color(c->status, col, 0);
    }
}

/* The connection status line, also doubling as the switching indicator (P4.5.4 will persist it through the host's drive-mount). One label, one poll timer, both freed together via control_timer_deleted_cb. */
static void usb_conn_timer_cb(lv_timer_t *t)
{
    lv_obj_t *label = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *txt;
    switch (nocsif_usb_gadget_state()) {
    case NOCSIF_USB_GADGET_STARTING: txt = "switching\xE2\x80\xA6"; break;   /* an ellipsis */
    case NOCSIF_USB_GADGET_FAILED:                                   /* (A3) explains why, not just that something happened */
        txt = (nocsif_usb_gadget_fail_reason()[0] != '\0') ? nocsif_usb_gadget_fail_reason() : "switch failed";
        break;
    default:
        switch (nocsif_usb_gadget_mode()) {
        case NOCSIF_USB_MODE_CDC: txt = "CDC serial " NOCSIF_DOT " linked";       break;
        case NOCSIF_USB_MODE_HID: txt = "HID keyboard " NOCSIF_DOT " linked";     break;
        case NOCSIF_USB_MODE_MSC:
            /* (P4.5.4) holds the switching indicator until the host has actually
             * taken the drive. The host's filesystem mount is invisible to the
             * device (see nocsif_usb_gadget_msc_host), so this is really enumerate
             * plus a roughly 5s settle: waiting-for-host, then preparing, then
             * mounted. */
            switch (nocsif_usb_gadget_msc_host()) {
            case NOCSIF_USB_MSC_HOST_NONE:     txt = "File Share " NOCSIF_DOT " waiting for host";  break;
            case NOCSIF_USB_MSC_HOST_SETTLING: txt = "File Share " NOCSIF_DOT " preparing\xE2\x80\xA6"; break;
            case NOCSIF_USB_MSC_HOST_READY:
            default:                           txt = "File Share " NOCSIF_DOT " /sd on host";      break;
            }
            break;
        case NOCSIF_USB_MODE_DETACHED:
        default:                  txt = "detached " NOCSIF_DOT " pick a mode";    break;
        }
    }
    if (strcmp(lv_label_get_text(label), txt) != 0) {
        lv_label_set_text(label, txt);
    }
}

static void usb_disconnect_click_cb(lv_event_t *e)
{
    (void)e;
    s_hid_latched = false;   /* an explicit Detached tap clears the HID latch */
    nocsif_usb_gadget_request_mode(NOCSIF_USB_MODE_DETACHED);
}

/* (P4.5.3b) "Run Macro" no longer runs a hardcoded default from the USB screen; it drills into the HID submenu's /sd/ducky file picker (build_macro_pick, below), which runs whichever file gets tapped */

static void keymap_click_cb(lv_event_t *e)
{
    (void)e;
    const char *cur = nocsif_hid_kbd_locale();   /* cycles US to GB to DE and back to US */
    const char *next = (strcmp(cur, "US") == 0) ? "GB"
                     : (strcmp(cur, "GB") == 0) ? "DE" : "US";
    nocsif_hid_kbd_set_locale(next);
}

static void keymap_status_timer_cb(lv_timer_t *t)
{
    lv_obj_t *label = (lv_obj_t *)lv_timer_get_user_data(t);
    const char *txt = nocsif_hid_kbd_locale();
    if (strcmp(lv_label_get_text(label), txt) != 0) {
        lv_label_set_text(label, txt);
    }
}

/* Deletes a control button's poll timer when the button itself is
 * deleted — its parent USB screen is freed on nav-back. Runs on the LVGL
 * task before the target label is torn down, so the timer can never fire
 * against a freed widget; without this it would dangle. */
static void control_timer_deleted_cb(lv_event_t *e)
{
    lv_timer_t *t = (lv_timer_t *)lv_event_get_user_data(e);
    if (t) lv_timer_delete(t);
}

/* The header's HID-armed badge (P4.5.4): returns "HID" whenever the
 * HID keyboard is the live USB class (mode()==HID), or "" otherwise, in
 * which case the header hides the badge (see nocsif_nav_header_tick).
 * Since a transient HID connection auto-detaches on leaving the submenu, a
 * badge that persists across screens specifically means HID was latched
 * armed — exactly the "what's armed" safety cue that design #4 calls for.
 * Returns a stable string literal and only reads volatile state, so it's
 * LVGL-task-safe like the other live getters. */
static const char *usb_hid_badge_str(void)
{
    return (nocsif_usb_gadget_mode() == NOCSIF_USB_MODE_HID) ? "HID" : "";
}

/* (P8 v2.4) refreshes the peek's show/hide info elements; defined further down by build_peek, which reads the CC flag statics, and called by the one header tick roughly every 0.5s */
static void peek_info_tick(void);
static void ui_accent_tick(void);   /* (P8 v2.5) list-row connected-state accents */
static int  scr_timeout_secs(void); /* (M11 power) the configured screen-sleep timeout, in seconds; 0 means never */
static void ui_predim_update(uint32_t inactive_ms, int timeout_s); /* (M11 power) dims the display just before sleep */
static void ui_predim_cancel(void);                                /* (M11 power) restores full brightness */
static bool s_saver_active;         /* (M11 power) whether the Battery Saver overlay is currently in effect */
static void batt_saver_refresh(void);  /* recomputes and applies or restores the Battery Saver overlay */
static bool ui_reduce_motion(void);    /* true if either the reduce_motion setting or battery-saver is active */
static void tm_bg_tick(void);       /* (M11 C1.2) background expiry for the countdown timer */
static void alarm_bg_tick(void);    /* (M11 C1.4) the per-minute alarm match */
static void alarms_load(void);      /* (M11 C1.4) loads persisted alarms at UI init */
static void alert_tick(void);       /* (M11 C1) the shared alarm/timer ring pump, called from the header tick */
static bool alert_active(void);     /* (M11 C1) true while an alert is currently ringing */
static void alert_ack(void);        /* (M11 C1) acknowledges/stops the ring (PWR or Stop) */
static void alert_snooze(void);     /* (M11 C1) snoozes the ring for 2 minutes (FN or Snooze) */
static void cc_flashlight_open(void);  /* the Control-Center torch overlay, reused by the Life Flashlight row */
/* The Home carousel style: 0 is ring (the default), 1 is dual dials
 * (peek-style), 2 is bottom arc (a half-ring). The peek watchface shares
 * the same three-style enum, but its own separate setting (PEEK_CAR_KEY);
 * its own default is dual (today's shipped look). */
#define HOME_CAR_KEY   "home.car"
#define PEEK_CAR_KEY   "peek.car"
enum { HOME_CAR_RING = 0, HOME_CAR_DUAL, HOME_CAR_BOTTOM };
static int  home_car_style(void);      /* cached; see its definition in the ring module */
static void home_car_set(int style);   /* updates the cache and persists the carousel style */
static void home_apply_layout(void);   /* rebuilds Home's content in place for the current carousel style */
static int  peek_car_style(void);      /* cached: the peek watchface's carousel style (ring/dual/bottom) */
static void peek_car_set(int style);   /* updates the cache and persists the peek carousel style */
static void peek_apply_layout(void);   /* rebuilds the peek's content in place for the current style */
static void peek_combined_rebuild(void);   /* (carousel v2) rebuilds the peek's combined s_pk; dial_rebuild dispatches here for the non-dual styles */
static const char *home_car_name(int s);   /* "ring"/"dual dials"/"bottom arc", shared by both rows */
static bool ui_dnd_active(void);       /* (section 4.1) DND or Movie mode silences the alarm/timer chime */
static void movie_geofence_tick(void); /* (section 4.1 GeoFence) header-tick geofence check: auto-exits Movie mode on leaving the area */
static void dnd_toggle(void);              /* (section 4.1) toggles Do Not Disturb; the Life row and CC moon icon share the same flag */
