static const char *autom_movie_tag(void);  /* live row tag: Movie off / on / on-via-geo */

/* ==== Unified Alert Center: a shell-wide alert log ==== *
 * One RAM ring that every alert source funnels into, so the Alerts screen
 * (build_alerts) shows phone notifications and on-watch events — an
 * alarm/timer firing, low battery, a radio anomaly, notable weather — as
 * one uniform, swipe-to-dismiss / clear-all feed. All access happens on
 * the LVGL task, pushed from the header tick's poll (alerts_ingest_tick)
 * and directly from the alarm/timer's alert_start, so no lock is needed.
 * Phone notifications are ingested from the existing ANCS mirror — copied
 * in, deduplicated by UID — and the log never mutates ble.c itself, so
 * dismiss/clear operations only ever touch this local copy. Watch-side
 * sources are read through each subsystem's own LVGL-safe cached getter,
 * so no worker-task code needed to change.
 *
 * The section 4.13 two-way sync scope: phone-to-watch dismiss is wired up
 * — ANCS emits Notification-Removed, ble.c drops it from its mirror and
 * bumps its generation counter, and alerts_ingest_tick reconciles this log
 * against the live mirror. Watch-to-phone dismiss isn't possible over
 * ANCS: it only offers Perform-Notification-Action (positive/negative, and
 * only for actionable notifications), never a generic accessory-dismiss,
 * so a swipe on the watch only ever clears the local copy. A true
 * watch-to-phone clear would need an Android companion or the section 4.8
 * Approvals lane — deliberately not faked here. */
typedef enum {
    ALERT_KIND_SYSTEM = 0, ALERT_KIND_PHONE, ALERT_KIND_ALARM, ALERT_KIND_TIMER,
    ALERT_KIND_BATTERY, ALERT_KIND_RADIO, ALERT_KIND_WEATHER, ALERT_KIND_N,
} alert_kind_t;

/* (section 4.13) A verify hook: build with
 * -DNOCSIF_ALERTS_SYNC_DEBUG=1 to log each swipe-dismiss and each
 * phone-to-watch reconcile over COM7, since the swipe and sync logic is
 * otherwise only observable as a rendered, paired-phone outcome and not
 * over serial. Ships off, so the flashed binary stays quiet. */
#ifndef NOCSIF_ALERTS_SYNC_DEBUG
#define NOCSIF_ALERTS_SYNC_DEBUG 0
#endif

#define ALERT_LOG_MAX 6        /* the log depth matches the visible cards; kept conservative for the LVGL pool, since cards are heavy */
typedef struct {
    uint32_t     id;          /* a unique, monotonically increasing dismiss key */
    alert_kind_t kind;
    int64_t      when_us;     /* esp_timer_get_time at push time, for computing age */
    char         title[40];
    char         body[100];
    uint32_t     src_uid;     /* (section 4.13) the ANCS NotificationUID, for phone entries only (0
                               * otherwise) — the key that ties a card back to the live ANCS mirror
                               * for phone-to-watch sync */
} alert_log_t;
static alert_log_t s_alog[ALERT_LOG_MAX];
static int         s_alog_n;
static uint32_t    s_alog_next_id = 1;
static uint32_t    s_alog_gen;         /* bumps on any change, driving the screen's self-refresh */

static const char *alert_kind_icon(alert_kind_t k)
{
    switch (k) {
    case ALERT_KIND_PHONE:   return NOCSIF_ICON_PHONE;
    case ALERT_KIND_ALARM:   return NOCSIF_ICON_BELL;
    case ALERT_KIND_TIMER:   return NOCSIF_ICON_CLOCK;
    case ALERT_KIND_BATTERY: return NOCSIF_ICON_BATT;
    case ALERT_KIND_RADIO:   return NOCSIF_ICON_WIFI;
    case ALERT_KIND_WEATHER: return NOCSIF_ICON_WX;
    default:                 return NOCSIF_ICON_SYS;
    }
}
static const char *alert_kind_name(alert_kind_t k)
{
    static const char *const n[ALERT_KIND_N] = { "System", "Phone", "Alarm", "Timer", "Battery", "Radio", "Weather" };
    return ((unsigned)k < ALERT_KIND_N) ? n[k] : "System";
}

/* Inserts newest-first at [0], shifting the rest down and evicting the oldest once the cap is hit. LVGL task only. */
static void alert_log_push(alert_kind_t kind, const char *title, const char *body)
{
    if (s_alog_n < ALERT_LOG_MAX) s_alog_n++;
    for (int i = s_alog_n - 1; i > 0; i--) s_alog[i] = s_alog[i - 1];
    alert_log_t *e = &s_alog[0];
    e->id      = s_alog_next_id++;
    e->kind    = kind;
    e->when_us = esp_timer_get_time();
    e->src_uid = 0;    /* (section 4.13) the default; the ANCS ingest step sets this on phone entries after this call returns */
    snprintf(e->title, sizeof e->title, "%s", (title && title[0]) ? title : alert_kind_name(kind));
    snprintf(e->body,  sizeof e->body,  "%s", body ? body : "");
    s_alog_gen++;
}
static void alert_log_dismiss(uint32_t id)
{
    for (int i = 0; i < s_alog_n; i++) if (s_alog[i].id == id) {
        for (int j = i; j < s_alog_n - 1; j++) s_alog[j] = s_alog[j + 1];
        s_alog_n--; s_alog_gen++; return;
    }
}
static void alert_log_clear(void) { if (s_alog_n) { s_alog_n = 0; s_alog_gen++; } }

/* Formats a relative age string from a push timestamp: "now", "5m", "3h", "2d". */
static void alert_age_str(int64_t when_us, char *out, size_t n)
{
    int64_t s = (esp_timer_get_time() - when_us) / 1000000;
    if      (s < 45)    snprintf(out, n, "now");
    else if (s < 3600)  snprintf(out, n, "%dm", (int)((s + 30) / 60));
    else if (s < 86400) snprintf(out, n, "%dh", (int)(s / 3600));
    else                snprintf(out, n, "%dd", (int)(s / 86400));
}

/* a dedup ring for ingested ANCS UIDs, handling attributes that arrive out of order across ticks */
#define ALERT_UID_RING 32
static uint32_t s_ing_uid[ALERT_UID_RING];
static int      s_ing_head;
static bool alert_uid_seen(uint32_t uid)
{
    for (int i = 0; i < ALERT_UID_RING; i++) if (s_ing_uid[i] == uid) return true;
    return false;
}
static void alert_uid_mark(uint32_t uid)
{
    s_ing_uid[s_ing_head] = uid;
    s_ing_head = (s_ing_head + 1) % ALERT_UID_RING;
}
/* (section 4.13, phone-to-watch sync) forgets a UID, so if the phone
 * re-posts the same notification later it gets ingested fresh — a removed
 * notification that comes back is treated as a new event for the operator. */
static void alert_uid_unmark(uint32_t uid)
{
    for (int i = 0; i < ALERT_UID_RING; i++) if (s_ing_uid[i] == uid) s_ing_uid[i] = 0;
}

/* Polls every alert source into the log, driven by the header tick on
 * the LVGL task. Only reads cached, LVGL-safe getters; the alarm/timer
 * pushes directly from alert_start instead. Gated by a tick counter, so
 * each source runs at its own cadence, with the header tick itself running
 * roughly every 0.5s. */
static void alerts_ingest_tick(void)
{
    static uint32_t t;
    t++;

    /* Phone (ANCS), roughly every 1s: ingests notifications not yet logged, deduplicated by UID, oldest to newest. */
    if ((t & 1) == 0) {
        int n = nocsif_ble_ancs_count();
        for (int i = n - 1; i >= 0; i--) {
            nocsif_ble_ancs_notif_t nt;
            if (!nocsif_ble_ancs_get(i, &nt)) continue;
            if (alert_uid_seen(nt.uid)) continue;
            if (!nt.have_attrs && nt.age_ms < 2000) continue;   /* gives the attribute fetch a moment to complete */
            const char *cat = nocsif_ble_ancs_category_str(nt.category);
            char title[40], body[100];
            snprintf(title, sizeof title, "%s", nt.title[0] ? nt.title : (nt.app[0] ? nt.app : cat));
            snprintf(body,  sizeof body,  "%s", nt.message[0] ? nt.message : cat);
            alert_log_push(ALERT_KIND_PHONE, title, body);
            s_alog[0].src_uid = nt.uid;   /* (section 4.13) ties this card to its ANCS UID for phone-to-watch sync */
            alert_uid_mark(nt.uid);
        }

        /* (section 4.13, phone-to-watch) reconciles removals. When the ANCS
         * mirror changes — a notification was cleared on the phone — any PHONE
         * card whose UID is no longer live is dropped and forgotten from the
         * seen-ring. Gated on the generation counter, so this only runs when the
         * mirror actually changed. */
        static uint32_t seen_ancs_gen;
        uint32_t g = nocsif_ble_ancs_gen();
        if (g != seen_ancs_gen) {
            seen_ancs_gen = g;
            int live = nocsif_ble_ancs_count();
            for (int i = 0; i < s_alog_n; ) {
                if (s_alog[i].kind != ALERT_KIND_PHONE || s_alog[i].src_uid == 0) { i++; continue; }
                bool present = false;
                for (int j = 0; j < live; j++) {
                    nocsif_ble_ancs_notif_t lt;
                    if (nocsif_ble_ancs_get(j, &lt) && lt.uid == s_alog[i].src_uid) { present = true; break; }
                }
                if (present) { i++; continue; }
#if NOCSIF_ALERTS_SYNC_DEBUG
                ESP_LOGI(TAG, "alerts: phone-removed uid=%u -> dismiss id=%u",
                         (unsigned)s_alog[i].src_uid, (unsigned)s_alog[i].id);
#endif
                alert_uid_unmark(s_alog[i].src_uid);
                alert_log_dismiss(s_alog[i].id);   /* compacts the array in place; deliberately does not advance i */
            }
        }
    }

    /* Battery, roughly every 4s: a two-stage low warning with hysteresis, reset while charging or once recovered. */
    if ((t % 8) == 0) {
        static int warned;   /* 0 means none, 1 means low at 15%, 2 means critical at 5% */
        int  pct = nocsif_power_batt_pct();
        bool chg = (nocsif_power_charging() == NOCSIF_CHG_CHARGING);
        if (chg || pct < 0) {
            warned = 0;
        } else if (pct <= 5 && warned < 2) {
            char b[48]; snprintf(b, sizeof b, "%d%% " NOCSIF_NDASH " charge now", pct);
            alert_log_push(ALERT_KIND_BATTERY, "Battery critical", b); warned = 2;
        } else if (pct <= 15 && warned < 1) {
            char b[48]; snprintf(b, sizeof b, "%d%% " NOCSIF_NDASH " consider charging", pct);
            alert_log_push(ALERT_KIND_BATTERY, "Battery low", b); warned = 1;
        } else if (pct > 20) {
            warned = 0;   /* re-arms once it recovers */
        }
    }

    /* Radio, roughly every 4s: a deauth/disassoc burst, which only accrues while the WiFi monitor/parser is running; a 30s cooldown means a flood posts one alert, not dozens. */
    if ((t % 8) == 4) {
        static uint32_t last_cnt; static bool init; static int64_t last_push_us;
        uint32_t c = nocsif_wifi_deauth_count() + nocsif_wifi_disassoc_count();
        if (!init) { last_cnt = c; init = true; }
        else if (c > last_cnt) {
            int64_t now = esp_timer_get_time();
            if (now - last_push_us > 30000000LL) {
                char b[64]; snprintf(b, sizeof b, "%u deauth/disassoc frames seen", (unsigned)c);
                alert_log_push(ALERT_KIND_RADIO, "Radio anomaly", b);
                last_push_us = now;
            }
            last_cnt = c;
        }
    }

    /* Weather, roughly every 30s: one alert when conditions first turn notable (rain/snow/storm, WMO code 61 or higher), re-arming once they clear. */
    if ((t % 60) == 12) {
        static int last_code = -1;
        nocsif_weather_t wx;
        if (nocsif_weather_snapshot(&wx) && wx.valid) {
            bool notable = (wx.code >= 61);
            if (notable && wx.code != last_code) {
                alert_log_push(ALERT_KIND_WEATHER, nocsif_weather_code_text(wx.code), "current conditions");
                last_code = wx.code;
            } else if (!notable) {
                last_code = -1;
            }
        }
    }
}

/* The one header live-data timer (P4.2 clock plus P4.3 battery plus
 * P4.5.4 HID-armed badge). The label push runs every tick, roughly every
 * 0.5s, so the badge tracks arm/disarm promptly; the I2C cache refreshes
 * are gated to run more slowly (RTC roughly every 20s, battery roughly
 * every 40s, since battery moves slowly per spec section 6). It then
 * updates every registered live label, but only on an actual change. One
 * timer serves the whole shell — the nav registry routes it to whichever
 * header/readout labels currently exist. Runs on the LVGL task; each I2C
 * read is short, just a few bytes, like the touch indev. Created once, in
 * nocsif_ui_init. */
static void header_tick_cb(lv_timer_t *t)
{
    (void)t;
    static uint32_t ticks;
    if ((ticks % UI_HEADER_RTC_EVERY) == 0) {   /* clock: refreshes the RTC cache roughly every 20s */
        nocsif_rtc_tick();
    }
    if ((ticks % UI_HEADER_BATT_EVERY) == 0) {  /* battery: refreshes the gauge cache roughly every 40s */
        nocsif_power_batt_tick();
    }
    ticks++;
    nocsif_nav_header_tick();   /* pushes the caches and the badge into the live labels, update-on-change */
    peek_info_tick();           /* (P8 v2.4) shows/hides the peek's BT, DND, and activity elements */
    ui_accent_tick();           /* (P8 v2.5) the hub and list-row connected-state accents */
    batt_saver_refresh();       /* (M11 power P4) auto-enters/leaves Battery Saver based on the battery percentage */
    tm_bg_tick();               /* (M11 C1.2) fires the countdown timer even when its screen is closed */
    alarm_bg_tick();            /* (M11 C1.4) fires a matching alarm even when its screen is closed */
    alert_tick();               /* (M11 C1) pumps the ring chime and snooze while an alert is active */
    alerts_ingest_tick();       /* the Alert Center: polls phone/battery/radio/weather into the log */
    movie_geofence_tick();      /* (section 4.1 Automations) auto-exits Movie mode once you leave the set location */
}

/* A USB mode-picker row: [icon] name ... [right status], chevron-less
 * like the power-menu action row but with a live status label and a
 * per-row poll timer. Tapping toggles the mode (usb_mode_row_click_cb).
 * The context struct is heap-allocated and freed together with the row
 * (usb_mode_row_deleted_cb). */
static void add_mode_row(lv_obj_t *list, const char *icon, const char *name,
                         const char *desc, nocsif_usb_mode_t mode)
{
    usb_mode_ctx_t *c = (usb_mode_ctx_t *)calloc(1, sizeof(*c));
    if (c == NULL) {
        return;
    }
    c->mode = mode;
    c->desc = desc;

    lv_obj_t *row = lv_obj_create(list);
    lv_obj_remove_style_all(row);
    lv_obj_add_style(row, &nocsif_style_row, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_scrollbar_mode(row, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *ic = lv_label_create(row);
    lv_label_set_text(ic, icon);
    lv_obj_add_style(ic, &nocsif_style_row_icon, 0);
    lv_obj_set_width(ic, 24);
    lv_obj_set_style_text_align(ic, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, name);
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_flex_grow(nm, 1);

    c->status = lv_label_create(row);
    lv_label_set_text(c->status, desc);                  /* seeded initially; the timer keeps it updated afterward */
    lv_obj_set_style_text_font(c->status, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(c->status, NOCSIF_ASH, 0);

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, usb_mode_row_click_cb, LV_EVENT_CLICKED, c);
    lv_obj_add_event_cb(row, usb_mode_row_deleted_cb, LV_EVENT_DELETE, c);
    c->timer = lv_timer_create(usb_mode_row_timer_cb, 300, c);
}

/* A chevron-less action row with a live right-status label (used for
 * Run Macro, Keymap). The status label is the timer's user_data, and the
 * timer is freed along with the row (control_timer_deleted_cb). status_cb
 * runs once here up front to seed the label, so it never flashes empty. */
static void add_status_row(lv_obj_t *list, const char *icon, const char *name,
                           lv_event_cb_t click_cb, lv_timer_cb_t status_cb)
{
    lv_obj_t *row = lv_obj_create(list);
    lv_obj_remove_style_all(row);
    lv_obj_add_style(row, &nocsif_style_row, 0);
    lv_obj_add_style(row, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_set_scrollbar_mode(row, LV_SCROLLBAR_MODE_OFF);
    lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(row, LV_OBJ_FLAG_GESTURE_BUBBLE);

    lv_obj_t *ic = lv_label_create(row);
    lv_label_set_text(ic, icon);
    lv_obj_add_style(ic, &nocsif_style_row_icon, 0);
    lv_obj_set_width(ic, 24);
    lv_obj_set_style_text_align(ic, LV_TEXT_ALIGN_CENTER, 0);

    lv_obj_t *nm = lv_label_create(row);
    lv_label_set_text(nm, name);
    lv_obj_add_style(nm, &nocsif_style_row_name, 0);
    lv_obj_set_flex_grow(nm, 1);

    lv_obj_t *status = lv_label_create(row);
    lv_label_set_text(status, "");
    lv_obj_set_style_text_font(status, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(status, NOCSIF_ASH, 0);

    lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_event_cb(row, click_cb, LV_EVENT_CLICKED, NULL);
    lv_timer_t *timer = lv_timer_create(status_cb, 300, status);
    lv_obj_add_event_cb(row, control_timer_deleted_cb, LV_EVENT_DELETE, timer);
    status_cb(timer);   /* seeds the status label from the current state */
}

/* ---- app registry and launch-by-id (the app layer) ---- *
 * The menu tree is built as an app registry: every screen or action gets
 * a stable string id (e.g. "wifi", "wifi.scan", "system.about"), and a menu
 * row resolves its target through the registry by id, never a hardcoded
 * pointer. nocsif_app_launch(id) is the single entry point that brings the
 * shell to a screen, so later bindings — the FN side-button, the
 * peek-screen planets, gestures — can target any app without touching the
 * nav mechanism itself, which stays purely root-based in ui_nav. Screens
 * build lazily and stay cached while alive, but a non-pinned screen is
 * freed when popped (nocsif_nav_back), with its cache pointer cleared on
 * delete, so cached widgets never accumulate in LVGL's fixed 48 KB object
 * pool — unbounded caching used to run it dry after just a few screens,
 * causing a render-time allocation to fail and LVGL to spin forever inside
 * lv_draw_label. Only Home is pinned and survives a pop. Actions not yet
 * built — everything past M4 and the hero screens — are present-but-
 * disabled stubs with a registered id, so a later milestone just needs to
 * flip the entry to enabled and give it a build function. */
typedef lv_obj_t *(*app_build_fn)(void);
typedef struct {
    const char  *id;         /* the stable target id */
    const char  *title;      /* the serif header title; NULL means Home */
    const char  *icon;       /* the canonical icon, informational — rows can pass their own instead */
    app_build_fn build;      /* builds and returns the screen root; NULL means a stub */
    lv_obj_t    *root;       /* cached while alive; cleared when the root is deleted */
    bool         enabled;    /* false means a present-but-disabled stub */
    bool         pin;        /* kept alive when popped, since it owns timers or state — see the nav docs */
} app_t;

