#define APP_MAX 128
static app_t s_apps[APP_MAX];
static int   s_app_n;

static void apps_init(void)
{
    if (s_app_n) return;
    for (size_t i = 0; i < sizeof(k_screens) / sizeof(k_screens[0]); i++) {
        s_apps[s_app_n++] = k_screens[i];
    }
}

static app_t *app_get(const char *id)
{
    for (int i = 0; i < s_app_n; i++) {
        if (strcmp(s_apps[i].id, id) == 0) return &s_apps[i];
    }
    return NULL;
}

/* Resolves an id, auto-registering an unknown one as a disabled stub — the id string must be a literal or static, since it's stored rather than copied. */
static app_t *app_get_or_stub(const char *id)
{
    app_t *a = app_get(id);
    if (a) return a;
    if (s_app_n < APP_MAX) {
        s_apps[s_app_n] = (app_t){ .id = id, .enabled = false };
        return &s_apps[s_app_n++];
    }
    ESP_LOGW(TAG, "app registry full (%d): '%s' unregistered", APP_MAX, id);
    return NULL;
}

/* Builds and caches a screen root, laying it out once so the first
 * slide to it doesn't stall on a layout pass mid-animation; returns NULL
 * for a stub or unknown id. Lazy: a submenu builds on its first launch, in
 * the row click callback on the LVGL task, not all at once at init —
 * building the whole tree up front, around 490 styled objects, starves the
 * idle task past the 5s task watchdog. Building one submenu's roughly 40
 * objects is a brief, safe operation by comparison. */
/* Clears the registry's cached pointer when the screen root is deleted — a non-pinned screen is freed on nav-back — so the next launch rebuilds it fresh. */
static void app_root_deleted_cb(lv_event_t *e)
{
    app_t *a = (app_t *)lv_event_get_user_data(e);
    if (a) a->root = NULL;
}

static lv_obj_t *app_ensure(const char *id)
{
    app_t *a = app_get(id);
    if (!a || !a->build) return NULL;
    if (!a->root) {
        int64_t t0 = esp_timer_get_time();   /* a jank probe: times the rebuild-on-open, i.e. the frozen gap */
        a->root = a->build();
        if (a->root) {
            lv_obj_update_layout(a->root);
            long build_ms = (long)((esp_timer_get_time() - t0) / 1000);
            /* self-heals the cache on delete, and pins screens that must survive a pop */
            lv_obj_add_event_cb(a->root, app_root_deleted_cb, LV_EVENT_DELETE, a);
            if (a->pin) nocsif_nav_pin(a->root);
            /* Watches the fixed LVGL object pool as screens stack up (P4.4b
             * added a config path 4-5 levels deep). max_used is the high-water
             * mark, and it must stay well under total_size, or a render-time
             * allocation fails and LVGL hangs (see LESSONS). */
            lv_mem_monitor_t mon;
            lv_mem_monitor(&mon);
            ESP_LOGI(TAG, "built '%s' in %ld ms — LVGL pool: %u%% used, max_used %u / %u B, frag %u%%",
                     id, build_ms,
                     (unsigned)mon.used_pct, (unsigned)mon.max_used,
                     (unsigned)mon.total_size, (unsigned)mon.frag_pct);
        }
    }
    return a->root;
}

void nocsif_app_launch(const char *id)
{
    if (id && strcmp(id, "flash") == 0) { cc_flashlight_open(); return; }   /* action: the torch overlay, via FN / peek / picker */
    if (id && strcmp(id, "dnd")   == 0) { dnd_toggle();                  return; }   /* action: toggle Do Not Disturb */
    if (id && strcmp(id, "movie") == 0) { movie_toggle(); return; }  /* action: toggle Movie mode */
    app_t *a = id ? app_get(id) : NULL;
    if (!a || !a->enabled) {
        ESP_LOGW(TAG, "launch '%s': %s", id ? id : "(null)", a ? "disabled stub" : "unregistered");
        return;
    }
    /* Already showing it (e.g. FN, or a peek planet re-launching the active app)? Skip the rebuild. */
    if (a->root && nocsif_nav_top() == a->root) {
        return;
    }
    /* Launch-by-id is a top-level destination (per the mockup: stack =
     * ['home', id]) — collapse any current drilldown to Home first, then
     * (re)build and push the target. This matches the mockup and avoids a
     * duplicate stack entry if the target is already open elsewhere on the
     * stack, which nav-back would otherwise double-free. pop_to_root frees
     * the old drilldown and clears its cache, so app_ensure must run after
     * it — never reuse a pre-pop root pointer. */
    nocsif_nav_pop_to_root();
    if (strcmp(id, "home") == 0) {
        return;                       /* Home is the root itself: nothing to push */
    }
    lv_obj_t *root = app_ensure(id);
    if (root) nocsif_nav_push(root);
}

/* Drills into a screen as a child of the current one — pushed on
 * top, with back returning here. Menu rows use this for normal
 * hierarchical navigation, distinct from nocsif_app_launch, the top-level
 * launch-by-id used by FN / peek planets / gestures (which collapses to
 * Home first). A menu row only ever targets a child not already on the
 * stack, so there's no duplicate-stack case to worry about. */
static void app_drill(const char *id)
{
    if (id && strcmp(id, "flash") == 0) { cc_flashlight_open(); return; }   /* action row: the torch overlay, not an actual screen */
    if (id && strcmp(id, "dnd")   == 0) { dnd_toggle();                  return; }   /* action row: toggle Do Not Disturb */
    if (id && strcmp(id, "movie") == 0) { movie_toggle(); return; }  /* action row: toggle Movie mode */
    app_t *a = id ? app_get(id) : NULL;
    if (!a || !a->enabled) {
        ESP_LOGW(TAG, "drill '%s': %s", id ? id : "(null)", a ? "disabled stub" : "unregistered");
        return;
    }
    if (a->root && nocsif_nav_top() == a->root) {
        return;                       /* already showing it */
    }
    lv_obj_t *root = app_ensure(id);
    if (root) nocsif_nav_push(root);
}

/* ---- app-layer menu rows: resolve the target by id, drill in on tap ---- */
static void app_row_click_cb(lv_event_t *e)
{
    app_drill((const char *)lv_event_get_user_data(e));
}

typedef struct {
    const char        *id;      /* the target app id, launched on tap; disabled if it's a stub */
    const char        *name;    /* the row label */
    const char        *icon;    /* a NOCSIF_ICON_* glyph */
    const char        *tag;     /* the status tag text; NULL means none */
    nocsif_tag_kind_t  kind;
    nocsif_live_getter_t tag_live; /* optionally binds the tag to a live getter (P4.3); NULL for a static tag */
} rowspec_t;

/* (P8 v2.5) the connected-state accent registry: a live service tints
 * its list-row icon violet. List rows are transient, so each one registers
 * with an LV_EVENT_DELETE callback that self-unregisters, mirroring the
 * nav's live-label registry. The per-entry `live` cache means an unchanged
 * tick never touches any style. app_id_live is the predicate;
 * ui_accent_tick, defined below near peek_info_tick, drives it from the
 * roughly 2x/s header tick. (The Home ring and peek planets get their
 * accent through planet_set_live in peek_info_tick instead.) */
typedef struct { lv_obj_t *obj; lv_obj_t *icon; const char *id; bool live; } accent_t;
static accent_t s_row_acc[16];      /* the transient list rows */

static void obj_set_accent(lv_obj_t *rim, lv_obj_t *icon, bool live)
{
    if (icon) lv_obj_set_style_text_color(icon, live ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);
    if (rim) {
        lv_obj_set_style_border_color(rim, live ? NOCSIF_VIOLET : lv_color_hex(0x2b2b31), 0);
        lv_obj_set_style_border_width(rim, live ? 2 : 1, 0);
        lv_obj_set_style_border_opa(rim, live ? LV_OPA_COVER : LV_OPA_70, 0);
    }
}

static void row_acc_deleted_cb(lv_event_t *e)
{
    lv_obj_t *o = lv_event_get_target(e);
    for (size_t i = 0; i < sizeof s_row_acc / sizeof s_row_acc[0]; i++)
        if (s_row_acc[i].obj == o) { s_row_acc[i] = (accent_t){0}; return; }
}
static void row_acc_register(lv_obj_t *row, lv_obj_t *icon, const char *id)
{
    for (size_t i = 0; i < sizeof s_row_acc / sizeof s_row_acc[0]; i++)
        if (s_row_acc[i].obj == NULL) {
            s_row_acc[i].obj = row; s_row_acc[i].icon = icon; s_row_acc[i].id = id; s_row_acc[i].live = false;
            lv_obj_add_event_cb(row, row_acc_deleted_cb, LV_EVENT_DELETE, NULL);
            return;
        }
    /* the registry is full: this row simply won't get an accent — harmless */
}

static void app_row(lv_obj_t *list, const rowspec_t *r)
{
    app_t *a = app_get_or_stub(r->id);
    bool enabled = a && a->enabled;
    lv_obj_t *row = nocsif_menu_add_row(list, r->icon, r->name, NULL, r->tag, r->kind,
                                        !enabled, r->tag_live);
    if (enabled) {
        lv_obj_add_flag(row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_event_cb(row, app_row_click_cb, LV_EVENT_CLICKED, (void *)r->id);
        if (r->icon) row_acc_register(row, lv_obj_get_child(row, 0), r->id);   /* the live accent; the icon is child 0 */
    }
}

static void add_rows(lv_obj_t *list, const rowspec_t *rows, size_t n)
{
    for (size_t i = 0; i < n; i++) app_row(list, &rows[i]);
}
#define ROWS(list, arr) add_rows((list), (arr), sizeof(arr) / sizeof((arr)[0]))

/* ---- screen builders, using transparent roots via the scaffold ---- *
 * Captions, tags, and rows follow docs/design/full-app-mockup.html. Any
 * actionable leaf not yet built past M4 is a disabled stub — dimmed and
 * non-navigating — while the category screens themselves do navigate.
 * Tags on stubs are static dimmed placeholders; real state binding lands
 * per phase (P4+). The one exception is the System>Power stub's tag, which
 * is the live battery percentage (P4.3) — dimmed, but genuinely real. */

/* ---- P8 v2.6 Home ring: a full-circle rotating carousel ---- *
 * The old three-sphere hub (a Life/Cyber/System triangle) is gone. Home is
 * now a single thin-line ring with the category planets orbiting it — the
 * ring module and the new build_home live just above build_peek, so they
 * can reuse the peek's planet and edit helpers, defined further down.
 * home_gesture_cb below is still the "back to the watchface" affordance the
 * ring shares with it. */

/* (P8 v2.6) a swipe right at Home returns to the watchface — the
 * app-wide back gesture, repurposed since at the Home root the scaffold's
 * own back is otherwise a no-op. Suppressed whenever the press actually
 * grabbed the ring, since a swipe there spins the wheel instead — so the
 * hollow ring center is the real "swipe-back" zone. */
static bool s_ring_grab;   /* whether the current Home press landed on the ring band, set by ring_pointer_cb */
static void home_gesture_cb(lv_event_t *e)
{
    (void)e;
    if (s_ring_grab) return;
    lv_indev_t *indev = lv_indev_active();
    if (indev != NULL && lv_indev_get_gesture_dir(indev) == LV_DIR_RIGHT) {
        lock_show();   /* a swipe right at Home goes to the watchface: back-from-Home */
    }
}

/* build_home is defined alongside the ring module, just above build_peek, since it needs car_make_planet and friends */

/* (P8 v2.2) the Life category — the old Home "WATCH" band, re-homed
 * under the Life circle. (Section 4.8a: the rowspecs are file-scope so the
 * companion menu mirror, nocsif_companion_menu_json, can serialize the
 * exact same rows the watch shows — one source of truth, not a hardcoded
 * phone-side grid.) */
