/* ---- PCAP Capture screen: records captured frames to microSD,
 * filling wifi.pcap (M5-P3.3) ---- * A few static labels updated in place
 * — status, file, counters — with no pooled list, so the churn lessons
 * don't apply here, but the tick still only writes through wifi_set_label
 * (update-on-change). Recording itself runs on the dedicated writer task;
 * this screen only starts/stops it and shows the counters. */
static lv_obj_t *s_pcap_status, *s_pcap_file, *s_pcap_stats, *s_pcap_start_lbl, *s_pcap_stream_lbl;

static void wifi_pcap_start_cb(lv_event_t *e)
{
    (void)e;
    /* records to SD; a no-op at the worker while a live stream is already armed, since there's only one sink at a time */
    if (nocsif_wifi_pcap_stream_active()) {
        return;
    }
    nocsif_wifi_request_pcap(!nocsif_wifi_pcap_active());
}

static void wifi_pcap_stream_cb(lv_event_t *e)
{
    (void)e;
    /* streams live over USB-CDC; a no-op while an SD recording is already running, one sink at a time */
    bool sd_rec = nocsif_wifi_pcap_active() && !nocsif_wifi_pcap_stream_active();
    if (sd_rec) {
        return;
    }
    nocsif_wifi_request_pcap_stream(!nocsif_wifi_pcap_stream_active());
}

static void wifi_pcap_tick(lv_timer_t *t)
{
    (void)t;
    if (s_pcap_status == NULL) {
        return;
    }
    bool stream = nocsif_wifi_pcap_stream_active();          /* armed as the CDC sink */
    bool active = nocsif_wifi_pcap_active();                 /* actively draining, either SD or CDC */
    bool sd_rec = active && !stream;                         /* recording to the card */
    const char *st = nocsif_wifi_pcap_status_str();

    char buf[112];
    if (stream) {
        if (strcmp(st, "stream") == 0) {
            snprintf(buf, sizeof buf, "streaming to USB " NOCSIF_DOT " %s",
                     nocsif_wifi_monitor_hopping() ? "hopping 1-13" : "locked");
        } else if (strcmp(st, "err") == 0) {
            snprintf(buf, sizeof buf, "error " NOCSIF_DOT " see the log");
        } else {
            snprintf(buf, sizeof buf, "waiting for host " NOCSIF_DOT " open NocSif in Wireshark");
        }
    } else if (sd_rec) {
        snprintf(buf, sizeof buf, "recording " NOCSIF_DOT " %s",
                 nocsif_wifi_monitor_hopping() ? "hopping 1-13" : "locked");
    } else if (strcmp(st, "file share") == 0) {
        snprintf(buf, sizeof buf, "unavailable " NOCSIF_DOT " File Share owns the card");
    } else if (strcmp(st, "no card") == 0) {
        snprintf(buf, sizeof buf, "no microSD card inserted");
    } else if (strcmp(st, "err") == 0) {
        snprintf(buf, sizeof buf, "error opening the file " NOCSIF_DOT " see the log");
    } else {
        snprintf(buf, sizeof buf, "stopped " NOCSIF_DOT " tap Record or Stream (suspends the link)");
    }
    wifi_set_label(s_pcap_status, buf);
    lv_obj_set_style_text_color(s_pcap_status,
                                stream ? NOCSIF_GOLD : (sd_rec ? NOCSIF_VIOLET : NOCSIF_STEEL), 0);

    if (stream) {
        wifi_set_label(s_pcap_file, "USB-CDC live " NOCSIF_DOT " radiotap " NOCSIF_DOT " Wireshark");
    } else {
        const char *path = nocsif_wifi_pcap_path();
        wifi_set_label(s_pcap_file, path[0] ? path : "/sd/nocsif/wifi/cap-NNN.pcap");
    }

    uint32_t bytes = nocsif_wifi_pcap_bytes();
    char kb[24];
    if (bytes >= 1024) {
        snprintf(kb, sizeof kb, "%u.%u KB",
                 (unsigned)(bytes / 1024), (unsigned)((bytes % 1024) * 10 / 1024));
    } else {
        snprintf(kb, sizeof kb, "%u B", (unsigned)bytes);
    }
    snprintf(buf, sizeof buf, "%u frames " NOCSIF_DOT " %s " NOCSIF_DOT " %u dropped",
             (unsigned)nocsif_wifi_pcap_frames(), kb, (unsigned)nocsif_wifi_pcap_dropped());
    wifi_set_label(s_pcap_stats, buf);

    /* Each button reflects its own sink; the incompatible one greys out while the other is running. */
    if (s_pcap_start_lbl) {
        wifi_set_label(s_pcap_start_lbl, sd_rec ? "Stop recording" : "Record to SD");
        lv_obj_set_style_text_color(s_pcap_start_lbl,
                                    stream ? NOCSIF_ASH : (sd_rec ? NOCSIF_VIOLET : NOCSIF_BONE), 0);
    }
    if (s_pcap_stream_lbl) {
        wifi_set_label(s_pcap_stream_lbl, stream ? "Stop streaming" : "Stream to USB (live)");
        lv_obj_set_style_text_color(s_pcap_stream_lbl,
                                    sd_rec ? NOCSIF_ASH : (stream ? NOCSIF_GOLD : NOCSIF_BONE), 0);
    }
}

static void wifi_pcap_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    /* Capture keeps running in the background, like Monitor; only the screen's own widgets get nulled. */
    s_pcap_status = s_pcap_file = s_pcap_stats = s_pcap_start_lbl = s_pcap_stream_lbl = NULL;
}

static lv_obj_t *build_wifi_pcap(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Record All Traffic", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_pcap_status = lv_label_create(content);
    lv_label_set_long_mode(s_pcap_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_pcap_status, lv_pct(100));
    lv_obj_add_style(s_pcap_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_pcap_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_pcap_status, "records every frame to SD (.pcap)");
    lv_obj_set_style_pad_bottom(s_pcap_status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Record to SD", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_pcap_start_cb, NULL);
    s_pcap_start_lbl = lv_obj_get_child(srow, 0);

    lv_obj_t *strow = wifi_menu_row(content, "Stream to USB (live)", NOCSIF_GOLD,
                                    NULL, NULL, wifi_pcap_stream_cb, NULL);
    s_pcap_stream_lbl = lv_obj_get_child(strow, 0);

    s_pcap_file = lv_label_create(content);
    lv_label_set_long_mode(s_pcap_file, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_pcap_file, lv_pct(100));
    lv_obj_add_style(s_pcap_file, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_pcap_file, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_top(s_pcap_file, 12, 0);
    lv_label_set_text(s_pcap_file, "/sd/nocsif/wifi/cap-NNN.pcap");

    s_pcap_stats = lv_label_create(content);
    lv_label_set_long_mode(s_pcap_stats, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_pcap_stats, lv_pct(100));
    lv_obj_add_style(s_pcap_stats, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_pcap_stats, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_top(s_pcap_stats, 6, 0);
    lv_label_set_text(s_pcap_stats, "0 frames");

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(hint, 16, 0);
    lv_label_set_text(hint, "radiotap " NOCSIF_DOT " opens in Wireshark. Record saves to the card "
                            "(retrieve over File Share); Stream sends live over USB-CDC "
                            "(host runs the NocSif extcap plugin).");

    lv_timer_t *timer = lv_timer_create(wifi_pcap_tick, 500, NULL);
    lv_obj_add_event_cb(scr, wifi_pcap_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_pcap_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Handshake / PMKID screen: passive WPA key-exchange
 * observation, filling wifi.handshake (M5-P4.1) ---- * The same
 * live-list discipline as Stations: fixed pooled rows, static text,
 * update-on-change, avoiding any LVGL-heap churn or render-watchdog trip.
 * Detection runs automatically through the parser; the extra "Record"
 * toggle arms the EAPOL-filtered writer (hs-NNN.pcap). Purely passive —
 * the watch observes an exchange, never solicits one. */
static live_row_t s_hs[LIVE_ROWS];
static lv_obj_t  *s_hs_status, *s_hs_start_lbl, *s_hs_rec_lbl, *s_hs_recinfo, *s_hs_more, *s_hs_more_lbl;
static lv_obj_t  *s_hs_hclbl;   /* the hc22000 export status */
static int        s_hs_page;

static void wifi_hs_row_fill(live_row_t *r, const nocsif_wifi_mon_hs_t *hs)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    char bssid[20];
    snprintf(bssid, sizeof bssid, "%02x:%02x:%02x:%02x:%02x:%02x",
             hs->bssid[0], hs->bssid[1], hs->bssid[2], hs->bssid[3], hs->bssid[4], hs->bssid[5]);
    bool have_ssid = hs->ssid[0] != 0;
    wifi_set_label(r->name, have_ssid ? hs->ssid : bssid);

    char slots[5];                                  /* which of the 4 messages have been seen, e.g. "12--" */
    for (int i = 0; i < 4; i++) slots[i] = (hs->msg_mask & (1 << i)) ? (char)('1' + i) : '-';
    slots[4] = '\0';

    char buf[96];
    snprintf(buf, sizeof buf, "%s " NOCSIF_DOT " hs %s%s%s",
             have_ssid ? bssid : (hs->vendor[0] ? hs->vendor : "unknown"),
             slots,
             hs->has_pmkid                 ? " " NOCSIF_DOT " PMKID" : "",
             nocsif_wifi_hs_crackable(hs)  ? " " NOCSIF_DOT " ready" : "");
    wifi_set_label(r->meta, buf);

    wifi_live_set_bars(r, hs->rssi);
}

static void wifi_hs_start_cb(lv_event_t *e) { (void)e; wifi_livelist_toggle(); }

static void wifi_hs_rec_cb(lv_event_t *e)
{
    (void)e;
    if (nocsif_wifi_pcap_active()) {
        nocsif_wifi_request_hs_capture(false);
    } else {
        if (!nocsif_wifi_parse_active()) {
            nocsif_wifi_request_parse(true);        /* recording implies discovery, so the list fills too */
        }
        nocsif_wifi_request_hs_capture(true);
    }
}

static void wifi_hs_tick(lv_timer_t *t)
{
    (void)t;
    if (s_hs_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_parse_active();
    int  n      = nocsif_wifi_mon_hs_count();

    int npmkid = 0, nready = 0;                      /* a small n, at most the table max, so a full pass is cheap */
    for (int i = 0; i < n; i++) {
        nocsif_wifi_mon_hs_t h;
        if (nocsif_wifi_mon_hs_get(i, &h)) {
            if (h.has_pmkid)                  npmkid++;
            if (nocsif_wifi_hs_crackable(&h)) nready++;
        }
    }

    char buf[96];
    const char *msg;
    if (!active) {
        msg = "stopped " NOCSIF_DOT " tap Start (suspends the WiFi link)";
    } else if (n <= 0) {
        snprintf(buf, sizeof buf, "listening " NOCSIF_DOT " %s " NOCSIF_DOT " no key exchange yet",
                 nocsif_wifi_monitor_hopping() ? "hopping 1-13" : "locked");
        msg = buf;
    } else {
        snprintf(buf, sizeof buf, "%d network%s " NOCSIF_DOT " %d PMKID " NOCSIF_DOT " %d ready",
                 n, n == 1 ? "" : "s", npmkid, nready);
        msg = buf;
    }
    if (s_hs_target.valid) {   /* targeted from Live Networks: stays locked, and names the target */
        if (active && nocsif_wifi_monitor_channel() != s_hs_target.channel)
            nocsif_wifi_request_monitor_channel(s_hs_target.channel);
        if (!active)
            snprintf(buf, sizeof buf, "target %s " NOCSIF_DOT " ch %d " NOCSIF_DOT " tap Start",
                     s_hs_target.name, s_hs_target.channel);
        else
            snprintf(buf, sizeof buf, "target %s " NOCSIF_DOT " ch %d locked " NOCSIF_DOT " %d hs " NOCSIF_DOT " %d ready",
                     s_hs_target.name, s_hs_target.channel, n, nready);
        msg = buf;
    }
    wifi_set_label(s_hs_status, msg);
    lv_obj_set_style_text_color(s_hs_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    bool rec = nocsif_wifi_pcap_active();            /* the record-to-SD state line */
    const char *pst = nocsif_wifi_pcap_status_str();
    if (rec) {
        const char *path = nocsif_wifi_pcap_path();
        snprintf(buf, sizeof buf, "rec " NOCSIF_DOT " %s " NOCSIF_DOT " %u frames",
                 path[0] ? path : "hs-NNN.pcap", (unsigned)nocsif_wifi_pcap_frames());
    } else if (strcmp(pst, "file share") == 0) {
        snprintf(buf, sizeof buf, "SD busy " NOCSIF_DOT " File Share owns the card");
    } else if (strcmp(pst, "no card") == 0) {
        snprintf(buf, sizeof buf, "no microSD card " NOCSIF_DOT " insert one to save");
    } else {
        snprintf(buf, sizeof buf, "saves EAPOL to /sd " NOCSIF_DOT " Wireshark / hcxtools");
    }
    wifi_set_label(s_hs_recinfo, buf);
    lv_obj_set_style_text_color(s_hs_recinfo, rec ? NOCSIF_VIOLET : NOCSIF_ASH, 0);

    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1)          pages = 1;
    if (s_hs_page >= pages) s_hs_page = 0;
    int base = s_hs_page * LIVE_ROWS;

    for (int i = 0; i < LIVE_ROWS; i++) {
        nocsif_wifi_mon_hs_t h;
        int idx = base + i;
        if (idx < n && nocsif_wifi_mon_hs_get(idx, &h)) {
            wifi_hs_row_fill(&s_hs[i], &h);
        } else if (s_hs[i].row) {
            lv_obj_add_flag(s_hs[i].row, LV_OBJ_FLAG_HIDDEN);
            s_hs[i].bars = -1;
        }
    }

    if (s_hs_more && s_hs_more_lbl) {
        if (n > LIVE_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_hs_page + 1, pages, LIVE_ROWS);
            wifi_set_label(s_hs_more_lbl, buf);
            lv_obj_clear_flag(s_hs_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_hs_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_hs_start_lbl) {
        wifi_set_label(s_hs_start_lbl, active ? "Stop" : "Start passive discovery");
    }
    if (s_hs_rec_lbl) {
        wifi_set_label(s_hs_rec_lbl, rec ? "Stop recording" : "Record .pcap to SD");
    }
    if (s_hs_hclbl) {
        const char *hc = nocsif_wifi_hc_status_str();
        wifi_set_label(s_hs_hclbl, hc[0] ? hc : "export to hashcat .hc22000 (PMKID + handshake)");
    }
}

static void wifi_hs_export_cb(lv_event_t *e) { (void)e; nocsif_wifi_request_export_hc22000(); }

static void wifi_hs_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_wifi_mon_hs_count();
    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1) pages = 1;
    s_hs_page = (s_hs_page + 1) % pages;
    wifi_hs_tick(NULL);
}

static void wifi_hs_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_hs_target.valid = false;   /* a fresh entry from the WiFi menu is untargeted, i.e. all networks */
    /* Recording keeps running in the background, like PCAP; only the screen's own widgets get nulled. */
    s_hs_status = s_hs_start_lbl = s_hs_rec_lbl = s_hs_recinfo = s_hs_more = s_hs_more_lbl = NULL;
    s_hs_hclbl = NULL;
    for (int i = 0; i < LIVE_ROWS; i++) {
        s_hs[i].row = s_hs[i].name = s_hs[i].meta = NULL;
    }
}

static lv_obj_t *build_wifi_handshake(void)
{
    nocsif_wifi_init();
    s_hs_page = 0;
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Handshake / PMKID", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_hs_status = lv_label_create(content);
    lv_label_set_long_mode(s_hs_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_hs_status, lv_pct(100));
    lv_obj_add_style(s_hs_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_hs_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_hs_status, "passive key-exchange observation");
    lv_obj_set_style_pad_bottom(s_hs_status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Start passive discovery", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_hs_start_cb, NULL);
    s_hs_start_lbl = lv_obj_get_child(srow, 0);

    lv_obj_t *rrow = wifi_menu_row(content, "Record .pcap to SD", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_hs_rec_cb, NULL);
    s_hs_rec_lbl = lv_obj_get_child(rrow, 0);

    s_hs_recinfo = lv_label_create(content);
    lv_label_set_long_mode(s_hs_recinfo, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_hs_recinfo, lv_pct(100));
    lv_obj_add_style(s_hs_recinfo, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_hs_recinfo, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(s_hs_recinfo, 8, 0);
    lv_label_set_text(s_hs_recinfo, "saves EAPOL to /sd " NOCSIF_DOT " Wireshark / hcxtools");

    wifi_menu_row(content, "Export .hc22000", NOCSIF_VIOLET, NULL, NULL, wifi_hs_export_cb, NULL);

    s_hs_hclbl = lv_label_create(content);
    lv_label_set_long_mode(s_hs_hclbl, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_hs_hclbl, lv_pct(100));
    lv_obj_add_style(s_hs_hclbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_hs_hclbl, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(s_hs_hclbl, 8, 0);
    lv_label_set_text(s_hs_hclbl, "export to hashcat .hc22000 (PMKID + handshake)");

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    for (int i = 0; i < LIVE_ROWS; i++) {           /* the pool is created once, then reused, never recreated */
        wifi_live_pool_row(list, &s_hs[i]);
    }

    s_hs_more = lv_obj_create(content);
    lv_obj_remove_style_all(s_hs_more);
    lv_obj_set_width(s_hs_more, lv_pct(100));
    lv_obj_set_height(s_hs_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_hs_more, 12, 0);
    lv_obj_clear_flag(s_hs_more, LV_OBJ_FLAG_SCROLLABLE);   /* first-tap select, not scroll-arbitration */
    lv_obj_add_flag(s_hs_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_hs_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_hs_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_hs_more, wifi_hs_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_hs_more, LV_OBJ_FLAG_HIDDEN);

    s_hs_more_lbl = lv_label_create(s_hs_more);
    lv_obj_add_style(s_hs_more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_hs_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_hs_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_hs_more_lbl, LV_TEXT_ALIGN_CENTER, 0);   /* ends stay clear of the corners */
    lv_label_set_text(s_hs_more_lbl, "");

    if (s_hs_target.valid) {
        nocsif_wifi_request_parse(true);            /* targeted from Live Networks: capture starts channel-locked */
        nocsif_wifi_request_monitor_channel(s_hs_target.channel);
    } else if (nocsif_wifi_monitor_active() && !nocsif_wifi_parse_active()) {
        nocsif_wifi_request_parse(true);            /* arriving from Monitor lights up the parser */
    }
    lv_timer_t *timer = lv_timer_create(wifi_hs_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, wifi_hs_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_hs_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Anomalies screen: passive detectors, filling
 * wifi.anomalies (M5-P4.2) ---- * Two passive signals share one screen: a
 * deauthentication/disassociation frame-rate meter (static labels,
 * update-on-change) and a duplicate-SSID/twin list (reusing the pooled
 * live-row, with its signal bars repurposed as a violet severity meter).
 * Both derive from the capture already running; nothing is transmitted.
 * The same fixed-pool/static-row discipline as the P3/P4.1 lists. */
#define DUP_ROWS 8
static live_row_t s_an[DUP_ROWS];
static lv_obj_t  *s_an_status, *s_an_start_lbl, *s_an_rate, *s_an_ratedet, *s_an_duphdr, *s_an_dupmore;

/* Repurposes the pooled row's signal bars as a 1-4 severity meter — violet means risk, not signal strength. */
static void anomaly_set_bars(live_row_t *r, int sev)
{
    if ((int8_t)sev != r->bars) {
        r->bars = (int8_t)sev;
        for (int i = 0; i < 4; i++) {
            lv_obj_set_style_bg_color(r->bar[i], i < sev ? NOCSIF_VIOLET : NOCSIF_ASH, 0);
        }
    }
}

static void wifi_an_dup_fill(live_row_t *r, const nocsif_wifi_mon_dup_t *d)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);
    wifi_set_label(r->name, d->ssid[0] ? d->ssid : "(hidden)");

    char buf[96];
    if (d->sec_lo != d->sec_hi) {                       /* mixed security across BSSIDs is the strong twin tell */
        snprintf(buf, sizeof buf, "%u APs " NOCSIF_DOT " %s-%s%s", d->bssids,
                 nocsif_wifi_sec_str(d->sec_lo), nocsif_wifi_sec_str(d->sec_hi),
                 d->has_open ? " " NOCSIF_DOT " open clone" : "");
    } else {                                            /* uniform security is more likely just a roaming mesh */
        snprintf(buf, sizeof buf, "%u APs " NOCSIF_DOT " %s " NOCSIF_DOT " same security",
                 d->bssids, nocsif_wifi_sec_str(d->sec_lo));
    }
    wifi_set_label(r->meta, buf);

    int sev = 1;
    if (d->bssids >= 3)  sev++;
    if (d->has_open)     sev++;
    if (d->sec_mismatch) sev++;
    if (sev > 4) sev = 4;
    anomaly_set_bars(r, sev);
}

static void wifi_an_start_cb(lv_event_t *e) { (void)e; wifi_livelist_toggle(); }

static void wifi_an_tick(lv_timer_t *t)
{
    (void)t;
    if (s_an_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_parse_active();
    bool mon    = nocsif_wifi_monitor_active();

    uint32_t rate = nocsif_wifi_deauth_rate();          /* the deauth/disassoc rate meter */
    char buf[96];
    snprintf(buf, sizeof buf, "%u/s", (unsigned)rate);
    wifi_set_label(s_an_rate, buf);
    lv_obj_set_style_text_color(s_an_rate, rate > 0 ? NOCSIF_VIOLET : NOCSIF_BONE, 0);
    snprintf(buf, sizeof buf, "deauth %u " NOCSIF_DOT " disassoc %u " NOCSIF_DOT " peak %u/s",
             (unsigned)nocsif_wifi_deauth_count(), (unsigned)nocsif_wifi_disassoc_count(),
             (unsigned)nocsif_wifi_deauth_peak_rate());
    wifi_set_label(s_an_ratedet, buf);

    nocsif_wifi_mon_dup_t dups[DUP_ROWS];               /* the duplicate-SSID / twin list */
    int total = nocsif_wifi_mon_dup_snapshot(dups, DUP_ROWS);
    int shown = total < DUP_ROWS ? total : DUP_ROWS;
    for (int i = 0; i < DUP_ROWS; i++) {
        if (i < shown) {
            wifi_an_dup_fill(&s_an[i], &dups[i]);
        } else if (s_an[i].row) {
            lv_obj_add_flag(s_an[i].row, LV_OBJ_FLAG_HIDDEN);
            s_an[i].bars = -1;
        }
    }
    if (total <= 0) {
        wifi_set_label(s_an_duphdr, active ? "duplicate SSIDs " NOCSIF_DOT " none"
                                           : "duplicate SSIDs " NOCSIF_DOT " start discovery");
    } else {
        snprintf(buf, sizeof buf, "duplicate SSIDs " NOCSIF_DOT " %d group%s",
                 total, total == 1 ? "" : "s");
        wifi_set_label(s_an_duphdr, buf);
    }
    if (s_an_dupmore) {
        if (total > DUP_ROWS) {
            snprintf(buf, sizeof buf, "+%d more", total - DUP_ROWS);
            wifi_set_label(s_an_dupmore, buf);
            lv_obj_clear_flag(s_an_dupmore, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_an_dupmore, LV_OBJ_FLAG_HIDDEN);
        }
    }

    const char *msg;
    if (!active && !mon) {
        msg = "stopped " NOCSIF_DOT " tap Start (suspends the WiFi link)";
    } else if (rate > 0) {
        snprintf(buf, sizeof buf, "elevated management-frame rate " NOCSIF_DOT " %u/s", (unsigned)rate);
        msg = buf;
    } else {
        msg = "listening " NOCSIF_DOT " no anomalies";
    }
    wifi_set_label(s_an_status, msg);
    lv_obj_set_style_text_color(s_an_status, rate > 0 ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    if (s_an_start_lbl) {
        wifi_set_label(s_an_start_lbl, active ? "Stop" : "Start passive discovery");
    }
}

static void wifi_an_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_an_status = s_an_start_lbl = s_an_rate = s_an_ratedet = s_an_duphdr = s_an_dupmore = NULL;
    for (int i = 0; i < DUP_ROWS; i++) {
        s_an[i].row = s_an[i].name = s_an[i].meta = NULL;
    }
}

static lv_obj_t *build_wifi_anomalies(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Anomalies", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_an_status = lv_label_create(content);
    lv_label_set_long_mode(s_an_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_an_status, lv_pct(100));
    lv_obj_add_style(s_an_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_an_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_an_status, "passive anomaly detectors");
    lv_obj_set_style_pad_bottom(s_an_status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Start passive discovery", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_an_start_cb, NULL);
    s_an_start_lbl = lv_obj_get_child(srow, 0);

    lv_obj_t *rhdr = lv_label_create(content);          /* the deauth/disassoc rate meter */
    lv_obj_add_style(rhdr, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(rhdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(rhdr, 14, 0);
    lv_label_set_text(rhdr, "deauth / disassoc rate");

    s_an_rate = lv_label_create(content);
    lv_obj_add_style(s_an_rate, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_an_rate, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_top(s_an_rate, 2, 0);
    lv_label_set_text(s_an_rate, "0/s");

    s_an_ratedet = lv_label_create(content);
    lv_label_set_long_mode(s_an_ratedet, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_an_ratedet, lv_pct(100));
    lv_obj_add_style(s_an_ratedet, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_an_ratedet, NOCSIF_ASH, 0);
    lv_label_set_text(s_an_ratedet, "deauth 0 " NOCSIF_DOT " disassoc 0 " NOCSIF_DOT " peak 0/s");

    s_an_duphdr = lv_label_create(content);             /* the duplicate-SSID / twin list */
    lv_label_set_long_mode(s_an_duphdr, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_an_duphdr, lv_pct(100));
    lv_obj_add_style(s_an_duphdr, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_an_duphdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(s_an_duphdr, 14, 0);
    lv_label_set_text(s_an_duphdr, "duplicate SSIDs");

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    for (int i = 0; i < DUP_ROWS; i++) {                /* the pool is created once, then reused, never recreated */
        wifi_live_pool_row(list, &s_an[i]);
    }

    s_an_dupmore = lv_label_create(content);
    lv_obj_add_style(s_an_dupmore, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_an_dupmore, NOCSIF_ASH, 0);
    lv_obj_set_width(s_an_dupmore, lv_pct(100));
    lv_obj_set_style_text_align(s_an_dupmore, LV_TEXT_ALIGN_CENTER, 0);   /* ends stay clear of the corners */
    lv_obj_set_style_pad_top(s_an_dupmore, 8, 0);
    lv_label_set_text(s_an_dupmore, "");
    lv_obj_add_flag(s_an_dupmore, LV_OBJ_FLAG_HIDDEN);

    if (nocsif_wifi_monitor_active() && !nocsif_wifi_parse_active()) {
        nocsif_wifi_request_parse(true);            /* arriving from Monitor lights up the parser */
    }
    lv_timer_t *timer = lv_timer_create(wifi_an_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, wifi_an_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_an_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Management-Frame TX screen: active, filling wifi.mgmt
 * (M5-P5.1, authorized testing) ---- * The first transmitting operation.
 * Discovery — the passive parser — populates a tappable AP list; tapping a
 * network selects it as the target; Transmit emits spoofed-source
 * deauth/disassoc frames to it at a bounded rate on its channel, soliciting
 * a reconnect that feeds the P4.1 handshake capture. The same fixed-pool/
 * static-row discipline; rows are made tappable via a container plus
 * CLICKABLE, per the tap-target rule. The selection shows as a "· target"
 * tag in the row text, avoiding any per-tick recolor. */
static live_row_t s_mg[LIVE_ROWS];
static lv_obj_t  *s_mg_status, *s_mg_disc_lbl, *s_mg_tx_lbl, *s_mg_kind_lbl, *s_mg_stats, *s_mg_more, *s_mg_more_lbl;
static int        s_mg_page;
static uint8_t    s_mg_sel_bssid[6];
static bool       s_mg_has_sel;

static void wifi_mgmt_tick(lv_timer_t *t);   /* forward declaration: the row tap refreshes immediately */

static void wifi_mgmt_ap_fill(live_row_t *r, const nocsif_wifi_mon_ap_t *ap, bool selected)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);
    wifi_set_label(r->name, ap->ssid[0] ? ap->ssid : "(hidden)");
    char buf[96];
    snprintf(buf, sizeof buf, "%02x:%02x:%02x:%02x:%02x:%02x " NOCSIF_DOT " ch %d " NOCSIF_DOT " %s%s",
             ap->bssid[0], ap->bssid[1], ap->bssid[2], ap->bssid[3], ap->bssid[4], ap->bssid[5],
             ap->channel, nocsif_wifi_sec_str(ap->security),
             selected ? " " NOCSIF_DOT " target" : "");
    wifi_set_label(r->meta, buf);
    wifi_live_set_bars(r, ap->rssi);
}

static void wifi_mgmt_row_cb(lv_event_t *e)   /* tapping a network selects it as the target */
{
    int rowidx = (int)(intptr_t)lv_event_get_user_data(e);
    int apidx  = s_mg_page * LIVE_ROWS + rowidx;
    nocsif_wifi_mon_ap_t ap;
    if (nocsif_wifi_mon_ap_get(apidx, &ap)) {
        memcpy(s_mg_sel_bssid, ap.bssid, 6);
        s_mg_has_sel = true;
        nocsif_wifi_set_mgmt_target(ap.bssid, ap.channel, ap.ssid);
        wifi_mgmt_tick(NULL);   /* reflects the selection immediately */
    }
}

static void wifi_mgmt_disc_cb(lv_event_t *e) { (void)e; wifi_livelist_toggle(); }

static void wifi_mgmt_tx_cb(lv_event_t *e)
{
    (void)e;
    if (nocsif_wifi_mgmt_tx_active()) {
        nocsif_wifi_request_mgmt_tx(false);
    } else if (nocsif_wifi_mgmt_has_target()) {
        nocsif_wifi_request_mgmt_tx(true);
    }
}

static void wifi_mgmt_kind_cb(lv_event_t *e)
{
    (void)e;
    nocsif_wifi_set_mgmt_disassoc(!nocsif_wifi_mgmt_disassoc());
}

static void wifi_mgmt_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_wifi_mon_ap_count();
    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1) pages = 1;
    s_mg_page = (s_mg_page + 1) % pages;
    wifi_mgmt_tick(NULL);
}

static void wifi_mgmt_tick(lv_timer_t *t)
{
    (void)t;
    if (s_mg_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_parse_active();
    bool tx     = nocsif_wifi_mgmt_tx_active();
    bool have   = nocsif_wifi_mgmt_has_target();
    bool disas  = nocsif_wifi_mgmt_disassoc();
    int  n      = nocsif_wifi_mon_ap_count();

    char buf[128];
    if (tx) {
        snprintf(buf, sizeof buf, "transmitting %s " NOCSIF_DOT " %s",
                 disas ? "disassoc" : "deauth", nocsif_wifi_mgmt_target_str());
    } else if (have) {
        snprintf(buf, sizeof buf, "target %s", nocsif_wifi_mgmt_target_str());
    } else if (active) {
        snprintf(buf, sizeof buf, "tap a network below to target it");
    } else {
        snprintf(buf, sizeof buf, "authorized testing " NOCSIF_DOT " Start discovery to find targets");
    }
    wifi_set_label(s_mg_status, buf);
    lv_obj_set_style_text_color(s_mg_status, tx ? NOCSIF_VIOLET : (have ? NOCSIF_BONE : NOCSIF_STEEL), 0);

    snprintf(buf, sizeof buf, "%u frames " NOCSIF_DOT " %u/s",
             (unsigned)nocsif_wifi_mgmt_tx_count(), (unsigned)nocsif_wifi_mgmt_tx_rate());
    wifi_set_label(s_mg_stats, buf);

    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1)          pages = 1;
    if (s_mg_page >= pages) s_mg_page = 0;
    int base = s_mg_page * LIVE_ROWS;
    for (int i = 0; i < LIVE_ROWS; i++) {
        nocsif_wifi_mon_ap_t ap;
        int idx = base + i;
        if (idx < n && nocsif_wifi_mon_ap_get(idx, &ap)) {
            bool sel = s_mg_has_sel && memcmp(ap.bssid, s_mg_sel_bssid, 6) == 0;
            wifi_mgmt_ap_fill(&s_mg[i], &ap, sel);
        } else if (s_mg[i].row) {
            lv_obj_add_flag(s_mg[i].row, LV_OBJ_FLAG_HIDDEN);
            s_mg[i].bars = -1;
        }
    }

    if (s_mg_more && s_mg_more_lbl) {
        if (n > LIVE_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_mg_page + 1, pages, LIVE_ROWS);
            wifi_set_label(s_mg_more_lbl, buf);
            lv_obj_clear_flag(s_mg_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_mg_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_mg_disc_lbl) wifi_set_label(s_mg_disc_lbl, active ? "Stop" : "Start discovery");
    if (s_mg_tx_lbl)   wifi_set_label(s_mg_tx_lbl, tx ? "Stop transmit"
                                                      : (disas ? "Transmit disassoc" : "Transmit deauth"));
    if (s_mg_kind_lbl) wifi_set_label(s_mg_kind_lbl, disas ? "Frame: disassoc" : "Frame: deauth");
}

static void wifi_mgmt_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    /* TX keeps running in the background if armed, like the other monitor screens; the widgets just get nulled */
    s_mg_status = s_mg_disc_lbl = s_mg_tx_lbl = s_mg_kind_lbl = s_mg_stats = s_mg_more = s_mg_more_lbl = NULL;
    for (int i = 0; i < LIVE_ROWS; i++) {
        s_mg[i].row = s_mg[i].name = s_mg[i].meta = NULL;
    }
}

static lv_obj_t *build_wifi_mgmt(void)
{
    nocsif_wifi_init();
    s_mg_page = 0;
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Management-Frame TX", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_label_set_text(note, "active \xC2\xB7 transmits management frames \xC2\xB7 authorized testing only");
    lv_obj_set_style_pad_bottom(note, 6, 0);

    s_mg_status = lv_label_create(content);
    lv_label_set_long_mode(s_mg_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_mg_status, lv_pct(100));
    lv_obj_add_style(s_mg_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mg_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_mg_status, "Start discovery to find targets");
    lv_obj_set_style_pad_bottom(s_mg_status, 8, 0);

    lv_obj_t *drow = wifi_menu_row(content, "Start discovery", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_mgmt_disc_cb, NULL);
    s_mg_disc_lbl = lv_obj_get_child(drow, 0);

    lv_obj_t *xrow = wifi_menu_row(content, "Transmit deauth", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_mgmt_tx_cb, NULL);
    s_mg_tx_lbl = lv_obj_get_child(xrow, 0);

    lv_obj_t *krow = wifi_menu_row(content, "Frame: deauth", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_mgmt_kind_cb, NULL);
    s_mg_kind_lbl = lv_obj_get_child(krow, 0);

    s_mg_stats = lv_label_create(content);
    lv_obj_set_width(s_mg_stats, lv_pct(100));
    lv_obj_add_style(s_mg_stats, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mg_stats, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(s_mg_stats, 6, 0);
    lv_label_set_text(s_mg_stats, "0 frames " NOCSIF_DOT " 0/s");

    lv_obj_t *lhdr = lv_label_create(content);
    lv_obj_add_style(lhdr, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(lhdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(lhdr, 14, 0);
    lv_label_set_text(lhdr, "tap a network to target");

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    for (int i = 0; i < LIVE_ROWS; i++) {           /* the pool is created once; the target rows are tappable */
        wifi_live_pool_row(list, &s_mg[i]);
        lv_obj_add_flag(s_mg[i].row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_style(s_mg[i].row, &nocsif_style_row_press, LV_STATE_PRESSED);
        lv_obj_add_event_cb(s_mg[i].row, wifi_mgmt_row_cb, LV_EVENT_CLICKED, (void *)(intptr_t)i);
    }

    s_mg_more = lv_obj_create(content);
    lv_obj_remove_style_all(s_mg_more);
    lv_obj_set_width(s_mg_more, lv_pct(100));
    lv_obj_set_height(s_mg_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_mg_more, 12, 0);
    lv_obj_clear_flag(s_mg_more, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_mg_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_mg_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_mg_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_mg_more, wifi_mgmt_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_mg_more, LV_OBJ_FLAG_HIDDEN);

    s_mg_more_lbl = lv_label_create(s_mg_more);
    lv_obj_add_style(s_mg_more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_mg_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_mg_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_mg_more_lbl, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_text(s_mg_more_lbl, "");

    if (nocsif_wifi_monitor_active() && !nocsif_wifi_parse_active()) {
        nocsif_wifi_request_parse(true);            /* arriving from Monitor lights up the target list */
    }
    lv_timer_t *timer = lv_timer_create(wifi_mgmt_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, wifi_mgmt_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_mgmt_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Beacon TX screen: active, a user-managed SSID list, filling
 * wifi.beacon (M5-P5.2) ---- * A managed list of SSIDs — added via
 * keyboard, renamed, enabled/disabled, deleted, persisted to NVS. The main
 * screen is a live pooled list, where tapping a row opens per-SSID
 * actions; a "+ Add SSID" row opens the keyboard. Only enabled entries
 * transmit. The same fixed-pool / static-row / container-tap discipline. */
#define BC_ROWS 8
static live_row_t s_bc[BC_ROWS];
static lv_obj_t  *s_bc_status, *s_bc_tx_lbl, *s_bc_stats, *s_bc_more, *s_bc_more_lbl;
static int        s_bc_page;
static int        s_bc_sel_idx;      /* the entry a per-SSID action screen operates on */
static int        s_bc_edit_idx;     /* -1 means the add-keyboard adds a new entry; otherwise it renames this index */

static lv_obj_t *build_wifi_beacon_add(void);
static lv_obj_t *build_wifi_beacon_item(void);

static void wifi_beacon_row_fill(live_row_t *r, const char *ssid, bool en)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);
    wifi_set_label(r->name, ssid[0] ? ssid : "(empty)");
    wifi_set_label(r->meta, en ? "emitting" : "disabled " NOCSIF_DOT " tap to enable");
    anomaly_set_bars(r, en ? 4 : 0);      /* bars repurposed as an on/off indicator */
}

static void wifi_beacon_row_cb(lv_event_t *e)   /* tapping an SSID opens its actions screen */
{
    int rowidx = (int)(intptr_t)lv_event_get_user_data(e);
    int idx    = s_bc_page * BC_ROWS + rowidx;
    if (idx < nocsif_wifi_beacon_count()) {
        s_bc_sel_idx = idx;
        lv_obj_t *root = build_wifi_beacon_item();
        if (root) nocsif_nav_push(root);
    }
}

static void wifi_beacon_add_cb(lv_event_t *e)
{
    (void)e;
    s_bc_edit_idx = -1;                    /* add mode */
    lv_obj_t *root = build_wifi_beacon_add();
    if (root) nocsif_nav_push(root);
}

static void wifi_beacon_decoys_cb(lv_event_t *e) { (void)e; nocsif_wifi_beacon_add_decoys(8); }
static void wifi_beacon_tx_cb(lv_event_t *e)     { (void)e; nocsif_wifi_request_beacon(!nocsif_wifi_beacon_active()); }

static void wifi_beacon_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_wifi_beacon_count();
    int pages = (n + BC_ROWS - 1) / BC_ROWS;
    if (pages < 1) pages = 1;
    s_bc_page = (s_bc_page + 1) % pages;
}

static void wifi_beacon_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bc_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_beacon_active();
    int  n      = nocsif_wifi_beacon_count();

    char buf[96];
    if (active) {
        snprintf(buf, sizeof buf, "transmitting " NOCSIF_DOT " ch %d", nocsif_wifi_monitor_channel());
    } else if (n <= 0) {
        snprintf(buf, sizeof buf, "tap + Add SSID to build the list");
    } else {
        snprintf(buf, sizeof buf, "%d SSID%s " NOCSIF_DOT " tap Transmit (suspends the WiFi link)",
                 n, n == 1 ? "" : "s");
    }
    wifi_set_label(s_bc_status, buf);
    lv_obj_set_style_text_color(s_bc_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    snprintf(buf, sizeof buf, "%u frames " NOCSIF_DOT " %u/s",
             (unsigned)nocsif_wifi_beacon_frames(), (unsigned)nocsif_wifi_beacon_rate());
    wifi_set_label(s_bc_stats, buf);

    int pages = (n + BC_ROWS - 1) / BC_ROWS;
    if (pages < 1)          pages = 1;
    if (s_bc_page >= pages) s_bc_page = 0;
    int base = s_bc_page * BC_ROWS;
    for (int i = 0; i < BC_ROWS; i++) {
        char ssid[33]; bool en = false;
        int idx = base + i;
        if (idx < n && nocsif_wifi_beacon_get(idx, ssid, sizeof ssid, &en)) {
            wifi_beacon_row_fill(&s_bc[i], ssid, en);
        } else if (s_bc[i].row) {
            lv_obj_add_flag(s_bc[i].row, LV_OBJ_FLAG_HIDDEN);
            s_bc[i].bars = -1;
        }
    }

    if (s_bc_more && s_bc_more_lbl) {
        if (n > BC_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_bc_page + 1, pages, BC_ROWS);
            wifi_set_label(s_bc_more_lbl, buf);
            lv_obj_clear_flag(s_bc_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_bc_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_bc_tx_lbl) {
        wifi_set_label(s_bc_tx_lbl, active ? "Stop transmit" : "Transmit beacons");
    }
}

static void wifi_beacon_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_bc_status = s_bc_tx_lbl = s_bc_stats = s_bc_more = s_bc_more_lbl = NULL;
    for (int i = 0; i < BC_ROWS; i++) {
        s_bc[i].row = s_bc[i].name = s_bc[i].meta = NULL;
    }
}

static lv_obj_t *build_wifi_beacon(void)
{
    nocsif_wifi_init();
    s_bc_page = 0;
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Beacon TX", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_label_set_text(note, "active \xC2\xB7 advertises your SSID list \xC2\xB7 authorized testing");
    lv_obj_set_style_pad_bottom(note, 6, 0);

    s_bc_status = lv_label_create(content);
    lv_label_set_long_mode(s_bc_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bc_status, lv_pct(100));
    lv_obj_add_style(s_bc_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bc_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_bc_status, "beacon advertisement");
    lv_obj_set_style_pad_bottom(s_bc_status, 8, 0);

    lv_obj_t *xrow = wifi_menu_row(content, "Transmit beacons", NOCSIF_VIOLET,
                                   NULL, NULL, wifi_beacon_tx_cb, NULL);
    s_bc_tx_lbl = lv_obj_get_child(xrow, 0);

    wifi_menu_row(content, "+ Add SSID", NOCSIF_VIOLET, NULL, NULL, wifi_beacon_add_cb, NULL);
    wifi_menu_row(content, "+ Add decoys (8)", NOCSIF_VIOLET, NULL, NULL, wifi_beacon_decoys_cb, NULL);

    s_bc_stats = lv_label_create(content);
    lv_obj_set_width(s_bc_stats, lv_pct(100));
    lv_obj_add_style(s_bc_stats, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bc_stats, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(s_bc_stats, 6, 0);
    lv_label_set_text(s_bc_stats, "0 frames " NOCSIF_DOT " 0/s");

    lv_obj_t *lhdr = lv_label_create(content);
    lv_obj_add_style(lhdr, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(lhdr, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_top(lhdr, 14, 0);
    lv_label_set_text(lhdr, "SSIDs \xC2\xB7 tap to manage");

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    for (int i = 0; i < BC_ROWS; i++) {
        wifi_live_pool_row(list, &s_bc[i]);
        lv_obj_add_flag(s_bc[i].row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_style(s_bc[i].row, &nocsif_style_row_press, LV_STATE_PRESSED);
        lv_obj_add_event_cb(s_bc[i].row, wifi_beacon_row_cb, LV_EVENT_CLICKED, (void *)(intptr_t)i);
    }

    s_bc_more = lv_obj_create(content);
    lv_obj_remove_style_all(s_bc_more);
    lv_obj_set_width(s_bc_more, lv_pct(100));
    lv_obj_set_height(s_bc_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_bc_more, 12, 0);
    lv_obj_clear_flag(s_bc_more, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_bc_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_bc_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_bc_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_bc_more, wifi_beacon_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_bc_more, LV_OBJ_FLAG_HIDDEN);
    s_bc_more_lbl = lv_label_create(s_bc_more);
    lv_obj_add_style(s_bc_more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bc_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_bc_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_bc_more_lbl, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_text(s_bc_more_lbl, "");

    lv_timer_t *timer = lv_timer_create(wifi_beacon_tick, 500, NULL);
    lv_obj_add_event_cb(scr, wifi_beacon_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_beacon_tick(timer);   /* seeded immediately */
    return scr;
}

/* Add or rename an SSID via the on-screen keyboard, mirroring the Set-MAC entry screen. */
static void wifi_beacon_add_apply(lv_obj_t *ta)
{
    const char *txt = ta ? lv_textarea_get_text(ta) : NULL;
    if (txt && txt[0]) {
        if (s_bc_edit_idx < 0) nocsif_wifi_beacon_add(txt);
        else                   nocsif_wifi_beacon_rename(s_bc_edit_idx, txt);
    }
    nocsif_nav_back();
}
static void wifi_beacon_add_ready_cb(lv_event_t *e)  { wifi_beacon_add_apply(lv_keyboard_get_textarea(lv_event_get_target(e))); }
static void wifi_beacon_add_btn_cb(lv_event_t *e)    { wifi_beacon_add_apply((lv_obj_t *)lv_event_get_user_data(e)); }
static void wifi_beacon_add_cancel_cb(lv_event_t *e) { (void)e; nocsif_nav_back(); }

static lv_obj_t *build_wifi_beacon_add(void)
{
    bool rename = (s_bc_edit_idx >= 0);
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold(rename ? "Rename SSID" : "Add SSID", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_text(hint, "type a network name (up to 32 chars)");
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(hint, 8, 0);

    char cur[33] = "";
    if (rename) nocsif_wifi_beacon_get(s_bc_edit_idx, cur, sizeof cur, NULL);

    lv_obj_t *ta = lv_textarea_create(content);
    lv_textarea_set_one_line(ta, true);
    lv_textarea_set_max_length(ta, 32);
    lv_textarea_set_text(ta, cur);
    lv_obj_set_width(ta, lv_pct(100));
    lv_obj_set_style_bg_color(ta, NOCSIF_PIT, 0);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(ta, NOCSIF_BONE, 0);
    lv_obj_add_style(ta, &nocsif_style_row_name, 0);
    lv_obj_set_style_border_color(ta, NOCSIF_EDGE2, 0);
    lv_obj_set_style_border_width(ta, 1, 0);
    lv_obj_set_style_radius(ta, 6, 0);
    lv_obj_set_style_bg_color(ta, NOCSIF_VIOLET, LV_PART_CURSOR);
    lv_obj_set_style_bg_opa(ta, LV_OPA_COVER, LV_PART_CURSOR);

    lv_obj_t *apply = lv_obj_create(content);
    lv_obj_remove_style_all(apply);
    lv_obj_set_width(apply, lv_pct(100));
    lv_obj_set_height(apply, LV_SIZE_CONTENT);
    lv_obj_set_style_margin_top(apply, 8, 0);
    lv_obj_set_style_bg_color(apply, NOCSIF_VIOLET_DK, 0);
    lv_obj_set_style_bg_opa(apply, LV_OPA_COVER, 0);
    lv_obj_set_style_border_color(apply, NOCSIF_VIOLET, 0);
    lv_obj_set_style_border_width(apply, 1, 0);
    lv_obj_set_style_radius(apply, 8, 0);
    lv_obj_set_style_pad_ver(apply, 11, 0);
    lv_obj_clear_flag(apply, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(apply, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(apply, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(apply, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_t *al = lv_label_create(apply);
    lv_label_set_text(al, rename ? "Rename" : "Add");
    lv_obj_center(al);
    lv_obj_add_style(al, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(al, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(apply, wifi_beacon_add_btn_cb, LV_EVENT_CLICKED, ta);

    lv_obj_t *kb = lv_keyboard_create(scr);
    lv_obj_add_flag(kb, LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_keyboard_set_textarea(kb, ta);
    nocsif_companion_track_ta(ta);   /* (section 4.8a P2) the remote /api/type endpoint targets this field */
    lv_keyboard_set_mode(kb, LV_KEYBOARD_MODE_TEXT_LOWER);
    lv_obj_set_size(kb, lv_pct(100), 196);
    lv_obj_align(kb, LV_ALIGN_BOTTOM_MID, 0, -58);
    lv_obj_set_style_bg_color(kb, NOCSIF_VOID, 0);
    lv_obj_set_style_bg_opa(kb, LV_OPA_COVER, 0);
    lv_obj_set_style_text_color(kb, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_all(kb, 3, 0);
    lv_obj_add_event_cb(kb, wifi_beacon_add_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(kb, wifi_beacon_add_cancel_cb, LV_EVENT_CANCEL, NULL);
    return scr;
}

/* Per-SSID actions: enable/disable, rename, delete — operating on s_bc_sel_idx. */
static lv_obj_t *s_bi_ssid_lbl, *s_bi_state_lbl, *s_bi_toggle_lbl;

static void wifi_beacon_item_toggle_cb(lv_event_t *e) { (void)e; nocsif_wifi_beacon_toggle(s_bc_sel_idx); }
static void wifi_beacon_item_rename_cb(lv_event_t *e)
{
    (void)e;
    s_bc_edit_idx = s_bc_sel_idx;
    lv_obj_t *root = build_wifi_beacon_add();
    if (root) nocsif_nav_push(root);
}
static void wifi_beacon_item_delete_cb(lv_event_t *e)
{
    (void)e;
    nocsif_wifi_beacon_remove(s_bc_sel_idx);
    nocsif_nav_back();               /* the entry is gone: return to the list */
}

static void wifi_beacon_item_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bi_ssid_lbl == NULL) {
        return;
    }
    char ssid[33]; bool en = false;
    if (!nocsif_wifi_beacon_get(s_bc_sel_idx, ssid, sizeof ssid, &en)) {
        return;
    }
    wifi_set_label(s_bi_ssid_lbl, ssid[0] ? ssid : "(empty)");
    wifi_set_label(s_bi_state_lbl, en ? "enabled " NOCSIF_DOT " transmitting when active"
                                      : "disabled " NOCSIF_DOT " not transmitted");
    lv_obj_set_style_text_color(s_bi_state_lbl, en ? NOCSIF_VIOLET : NOCSIF_ASH, 0);
    if (s_bi_toggle_lbl) wifi_set_label(s_bi_toggle_lbl, en ? "Disable" : "Enable");
}

static void wifi_beacon_item_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) lv_timer_delete(timer);
    s_bi_ssid_lbl = s_bi_state_lbl = s_bi_toggle_lbl = NULL;
}

static lv_obj_t *build_wifi_beacon_item(void)
{
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("SSID", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_bi_ssid_lbl = lv_label_create(content);
    lv_label_set_long_mode(s_bi_ssid_lbl, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bi_ssid_lbl, lv_pct(100));
    lv_obj_add_style(s_bi_ssid_lbl, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_bi_ssid_lbl, NOCSIF_BONE, 0);
    lv_label_set_text(s_bi_ssid_lbl, "");

    s_bi_state_lbl = lv_label_create(content);
    lv_label_set_long_mode(s_bi_state_lbl, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bi_state_lbl, lv_pct(100));
    lv_obj_add_style(s_bi_state_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bi_state_lbl, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_bottom(s_bi_state_lbl, 10, 0);
    lv_label_set_text(s_bi_state_lbl, "");

    lv_obj_t *trow = wifi_menu_row(content, "Enable", NOCSIF_VIOLET, NULL, NULL, wifi_beacon_item_toggle_cb, NULL);
    s_bi_toggle_lbl = lv_obj_get_child(trow, 0);
    wifi_menu_row(content, "Rename", NOCSIF_VIOLET, NULL, NULL, wifi_beacon_item_rename_cb, NULL);
    wifi_menu_row(content, "Delete", NOCSIF_GOLD, NULL, NULL, wifi_beacon_item_delete_cb, NULL);

    lv_timer_t *timer = lv_timer_create(wifi_beacon_item_tick, 300, NULL);
    lv_obj_add_event_cb(scr, wifi_beacon_item_deleted_cb, LV_EVENT_DELETE, timer);
    wifi_beacon_item_tick(timer);
    return scr;
}

/* ============ M5-P5.3: Software Access Point, active ============ *
 * Brings the radio up as an open software AP and lists the client devices
 * that join it: MAC, plus an IP once the built-in DHCP server hands one
 * out, plus signal. Config — SSID, channel, hidden — is edited here and
 * persisted; with only one radio, this is mutually exclusive with
 * monitor/STA, so Start suspends the WiFi link. The client list reuses the
 * fixed-row-pool / static-row discipline from the P3-P5 render-watchdog
 * lessons: rows are created once and updated in place, through
 * wifi_set_label / wifi_live_set_bars. */
#define SAP_ROWS 8   /* the pooled client rows; the driver caps associations at max_connection, which is at most AP_CLI_MAX */
static lv_obj_t *s_sap_status, *s_sap_ssid_acc, *s_sap_chan_acc, *s_sap_hidden_acc;
static lv_obj_t *s_sap_start_lbl, *s_sap_addr, *s_sap_clihdr;
static live_row_t s_sap[SAP_ROWS];

static lv_obj_t *build_wifi_ap_ssid(void);   /* the SSID entry, via the keyboard */

static void wifi_ap_ssid_cb(lv_event_t *e)   { (void)e; lv_obj_t *r = build_wifi_ap_ssid(); if (r) nocsif_nav_push(r); }
static void wifi_ap_chan_cb(lv_event_t *e)   { (void)e; int ch = nocsif_wifi_ap_channel(); nocsif_wifi_ap_set_channel(ch >= 13 ? 1 : ch + 1); }
static void wifi_ap_hidden_cb(lv_event_t *e) { (void)e; nocsif_wifi_ap_set_hidden(!nocsif_wifi_ap_hidden()); }
static void wifi_ap_start_cb(lv_event_t *e)  { (void)e; nocsif_wifi_request_ap(!nocsif_wifi_ap_active()); }

static void wifi_ap_client_fill(live_row_t *r, const uint8_t mac[6], const char *ip, int8_t rssi)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);
    char buf[40];
    snprintf(buf, sizeof buf, "%02x:%02x:%02x:%02x:%02x:%02x",
             mac[0], mac[1], mac[2], mac[3], mac[4], mac[5]);
    wifi_set_label(r->name, buf);
    if (ip && ip[0]) {
        snprintf(buf, sizeof buf, "%s " NOCSIF_DOT " %d dBm", ip, rssi);
    } else {
        snprintf(buf, sizeof buf, "awaiting lease " NOCSIF_DOT " %d dBm", rssi);
    }
    wifi_set_label(r->meta, buf);
    wifi_live_set_bars(r, rssi);
}

static void wifi_ap_tick(lv_timer_t *t)
{
    (void)t;
    if (s_sap_status == NULL) {
        return;
    }
    bool active = nocsif_wifi_ap_active();
    int  n      = nocsif_wifi_ap_client_count();

    char buf[96];
    if (active) {
        snprintf(buf, sizeof buf, "AP up " NOCSIF_DOT " %s " NOCSIF_DOT " %d client%s",
                 nocsif_wifi_ap_ssid(), n, n == 1 ? "" : "s");
    } else {
        snprintf(buf, sizeof buf, "stopped " NOCSIF_DOT " tap Start (suspends the WiFi link)");
    }
    wifi_set_label(s_sap_status, buf);
    lv_obj_set_style_text_color(s_sap_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    /* the config accessories reflect the cached config, which is persisted and applied on Start */
    wifi_set_label(s_sap_ssid_acc, nocsif_wifi_ap_ssid());
    snprintf(buf, sizeof buf, "%d", nocsif_wifi_ap_channel());
    wifi_set_label(s_sap_chan_acc, buf);
    wifi_set_label(s_sap_hidden_acc, nocsif_wifi_ap_hidden() ? "yes" : "no");
    wifi_set_label(s_sap_start_lbl, active ? "Stop" : "Start");

    if (active) {
        const char *ip = nocsif_wifi_ap_ip_str();
        snprintf(buf, sizeof buf, "open " NOCSIF_DOT " ch %d " NOCSIF_DOT " %s",
                 nocsif_wifi_ap_channel(), ip[0] ? ip : "192.168.4.1");
    } else {
        snprintf(buf, sizeof buf, "open AP " NOCSIF_DOT " config applied on Start");
    }
    wifi_set_label(s_sap_addr, buf);

    if (n <= 0) {
        wifi_set_label(s_sap_clihdr, active ? "clients " NOCSIF_DOT " none yet"
                                            : "clients " NOCSIF_DOT " start the AP to see joins");
    } else {
        snprintf(buf, sizeof buf, "clients " NOCSIF_DOT " %d", n);
        wifi_set_label(s_sap_clihdr, buf);
    }

    for (int i = 0; i < SAP_ROWS; i++) {
        uint8_t mac[6]; char ip[16]; int8_t rssi = 0;
        if (i < n && nocsif_wifi_ap_client_get(i, mac, ip, sizeof ip, &rssi)) {
            wifi_ap_client_fill(&s_sap[i], mac, ip, rssi);
        } else if (s_sap[i].row) {
            lv_obj_add_flag(s_sap[i].row, LV_OBJ_FLAG_HIDDEN);
            s_sap[i].bars = -1;
        }
    }
}

static void wifi_ap_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_sap_status = s_sap_ssid_acc = s_sap_chan_acc = s_sap_hidden_acc = NULL;
    s_sap_start_lbl = s_sap_addr = s_sap_clihdr = NULL;
    for (int i = 0; i < SAP_ROWS; i++) {
        s_sap[i].row = s_sap[i].name = s_sap[i].meta = NULL;
    }
}

/* ---- Access Point hub: the software AP plus the two things
 * layered on it ---- * "Access Point" on the WiFi menu opens here rather
 * than going straight into the AP control screen. Captive Portal rides on
 * top of the open AP, and Beacon TX shares the AP's raw-TX path — the user
 * asked for both to live under Access Point instead of as loose top-level
 * WiFi-menu rows. Each row keeps its own live tag, so the AP/portal/beacon
 * state still shows without needing to open the screen. */
static const rowspec_t k_wifi_aphub_rows[] = {
        { "wifi.ap",     "Software AP",    NOCSIF_ICON_AP, "off", NOCSIF_TAG_RUN, nocsif_wifi_ap_tag_str },
        { "wifi.portal", "Captive Portal", NOCSIF_ICON_AP, "off", NOCSIF_TAG_RUN, nocsif_wifi_portal_tag_str },
        { "wifi.beacon", "Beacon TX",      NOCSIF_ICON_AP, "off", NOCSIF_TAG_RUN, nocsif_wifi_beacon_tag_str },
};
static lv_obj_t *build_wifi_aphub(void)
{
    nocsif_wifi_init();
    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Access Point", NULL, &content);
    lv_obj_t *list = nocsif_menu_list(content);
    ROWS(list, k_wifi_aphub_rows);
    return scr;
}

