/* ---- Nearby Trackers screen, filling ble.trackers (M7-P4.1)
 * ---- * Scans, reusing the P1 observer, and shows only devices classified
 * as item trackers — the "is something following me?" view. The same
 * crash-safe live-list discipline as Scan Devices: a fixed row pool,
 * static rows, a paging footer. Purely receive-side; own airspace only. */
static live_row_t s_btr[LIVE_ROWS];
static lv_obj_t  *s_bt_status, *s_bt_start_lbl, *s_bt_more, *s_bt_more_lbl;
static int        s_bt_page;

static void ble_tracker_row_fill(live_row_t *r, const nocsif_ble_dev_t *d)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    /* the hero: the tracker class, in gold, as an attention cue */
    wifi_set_label(r->name, nocsif_ble_tracker_str(d->tracker));
    lv_obj_set_style_text_color(r->name, NOCSIF_GOLD, 0);

    char addr[20];
    snprintf(addr, sizeof addr, "%02x:%02x:%02x:%02x:%02x:%02x",
             d->addr[5], d->addr[4], d->addr[3], d->addr[2], d->addr[1], d->addr[0]);
    char buf[80];
    int off = 0;
    if (d->name[0]) off += snprintf(buf + off, sizeof buf - off, "%s " NOCSIF_DOT " ", d->name);
    off += snprintf(buf + off, sizeof buf - off, "%s", addr);
    if (d->age_ms >= 1000) off += snprintf(buf + off, sizeof buf - off, " " NOCSIF_DOT " %us ago",
                                           (unsigned)(d->age_ms / 1000));
    wifi_set_label(r->meta, buf);

    wifi_live_set_bars(r, d->rssi);
}

static void ble_tracker_toggle_cb(lv_event_t *e)
{
    (void)e;
    nocsif_ble_request_scan(!nocsif_ble_scan_active());
}

static void ble_tracker_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bt_status == NULL) {
        return;
    }
    bool active = nocsif_ble_scan_active();
    int  n      = nocsif_ble_tracker_count();
    int  total  = nocsif_ble_dev_count();

    char buf[80];
    const char *msg;
    if (nocsif_reliability_safe_mode()) {
        msg = "BLE disabled (safe mode)";
    } else if (nocsif_ble_starting()) {
        msg = "starting " NOCSIF_DOT " releasing WiFi for the radio\xE2\x80\xA6";
    } else if (!active) {
        msg = n > 0 ? "stopped " NOCSIF_DOT " tap Start to resume"
                    : "stopped " NOCSIF_DOT " tap Start to scan";
    } else if (n <= 0) {
        snprintf(buf, sizeof buf, "scanning " NOCSIF_DOT " no trackers (%d device%s seen)",
                 total, total == 1 ? "" : "s");
        msg = buf;
    } else {
        snprintf(buf, sizeof buf, "%d tracker%s in range " NOCSIF_DOT " of %d device%s",
                 n, n == 1 ? "" : "s", total, total == 1 ? "" : "s");
        msg = buf;
    }
    wifi_set_label(s_bt_status, msg);
    lv_obj_set_style_text_color(s_bt_status, n > 0 ? NOCSIF_GOLD
                                                   : (active ? NOCSIF_VIOLET : NOCSIF_STEEL), 0);

    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1)          pages = 1;
    if (s_bt_page >= pages) s_bt_page = 0;
    int base = s_bt_page * LIVE_ROWS;

    for (int i = 0; i < LIVE_ROWS; i++) {
        nocsif_ble_dev_t d;
        int idx = base + i;
        if (idx < n && nocsif_ble_tracker_get(idx, &d)) {
            ble_tracker_row_fill(&s_btr[i], &d);
        } else if (s_btr[i].row) {
            lv_obj_add_flag(s_btr[i].row, LV_OBJ_FLAG_HIDDEN);
            s_btr[i].bars = -1;
        }
    }

    if (s_bt_more && s_bt_more_lbl) {
        if (n > LIVE_ROWS) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_bt_page + 1, pages, LIVE_ROWS);
            wifi_set_label(s_bt_more_lbl, buf);
            lv_obj_clear_flag(s_bt_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_bt_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
    if (s_bt_start_lbl) {
        wifi_set_label(s_bt_start_lbl, active ? "Stop" : "Start tracker scan");
    }
}

static void ble_tracker_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_ble_tracker_count();
    int pages = (n + LIVE_ROWS - 1) / LIVE_ROWS;
    if (pages < 1) pages = 1;
    s_bt_page = (s_bt_page + 1) % pages;
    ble_tracker_tick(NULL);
}

static void ble_tracker_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_bt_status = s_bt_start_lbl = s_bt_more = s_bt_more_lbl = NULL;
    for (int i = 0; i < LIVE_ROWS; i++) {
        s_btr[i].row = s_btr[i].name = s_btr[i].meta = NULL;
    }
    nocsif_ble_request_release();   /* hands the radio back to WiFi (only one radio) */
}

static lv_obj_t *build_ble_trackers(void)
{
    nocsif_ble_init();
    s_bt_page = 0;

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Nearby Trackers", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_bt_status = lv_label_create(content);
    lv_label_set_long_mode(s_bt_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bt_status, lv_pct(100));
    lv_obj_add_style(s_bt_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bt_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_bt_status, "AirTag / Find My " NOCSIF_DOT " Tile " NOCSIF_DOT " SmartTag");
    lv_obj_set_style_pad_bottom(s_bt_status, 8, 0);

    lv_obj_t *srow = wifi_menu_row(content, "Start tracker scan", NOCSIF_VIOLET,
                                   NULL, NULL, ble_tracker_toggle_cb, NULL);
    s_bt_start_lbl = lv_obj_get_child(srow, 0);

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_top(list, 6, 0);
    for (int i = 0; i < LIVE_ROWS; i++) {       /* the pool is created once, then reused, never recreated */
        wifi_live_pool_row(list, &s_btr[i]);
    }

    s_bt_more = lv_obj_create(content);
    lv_obj_remove_style_all(s_bt_more);
    lv_obj_set_width(s_bt_more, lv_pct(100));
    lv_obj_set_height(s_bt_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_bt_more, 12, 0);
    lv_obj_clear_flag(s_bt_more, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_bt_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_bt_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_bt_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_bt_more, ble_tracker_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_bt_more, LV_OBJ_FLAG_HIDDEN);

    s_bt_more_lbl = lv_label_create(s_bt_more);
    lv_obj_add_style(s_bt_more_lbl, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bt_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_bt_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_bt_more_lbl, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_text(s_bt_more_lbl, "");

    lv_obj_t *note = lv_label_create(content);
    lv_label_set_long_mode(note, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(note, lv_pct(100));
    lv_obj_add_style(note, &nocsif_style_font_tag_small, 0);
    lv_obj_set_style_text_color(note, NOCSIF_ASH, 0);
    lv_obj_set_style_text_align(note, LV_TEXT_ALIGN_CENTER, 0);
    lv_obj_set_style_pad_top(note, 10, 0);
    lv_label_set_text(note, "signal bars = proximity " NOCSIF_DOT " a tracker that follows you across "
                            "places is the tell");

    nocsif_ble_request_scan(true);
    lv_timer_t *timer = lv_timer_create(ble_tracker_tick, 1000, NULL);
    lv_obj_add_event_cb(scr, ble_tracker_deleted_cb, LV_EVENT_DELETE, timer);
    ble_tracker_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Advert Capture screen, filling ble.pcap (M7-P4.3) ---- *
 * Scans, reusing the P1 observer, and records every received advertisement
 * to a PCAP file on microSD. The same static-label discipline as the WiFi
 * PCAP screen: a few labels updated in place, no pooled list. Recording
 * itself drains on the BLE worker task; this screen only starts/stops it
 * and shows the counters. Purely receive-side; own airspace only. */
static lv_obj_t *s_bpc_status, *s_bpc_file, *s_bpc_stats, *s_bpc_rec_lbl;

static void ble_pcap_rec_cb(lv_event_t *e)
{
    (void)e;
    nocsif_ble_request_pcap(!nocsif_ble_pcap_active());
}

static void ble_pcap_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bpc_status == NULL) {
        return;
    }
    bool rec = nocsif_ble_pcap_active();
    const char *st = nocsif_ble_pcap_status_str();
    int devs = nocsif_ble_dev_count();

    char buf[112];
    if (nocsif_reliability_safe_mode()) {
        snprintf(buf, sizeof buf, "BLE disabled (safe mode)");
    } else if (nocsif_ble_starting()) {
        snprintf(buf, sizeof buf, "starting " NOCSIF_DOT " releasing WiFi for the radio\xE2\x80\xA6");
    } else if (rec) {
        snprintf(buf, sizeof buf, "recording adverts " NOCSIF_DOT " %d device%s in range",
                 devs, devs == 1 ? "" : "s");
    } else if (strcmp(st, "file share") == 0) {
        snprintf(buf, sizeof buf, "unavailable " NOCSIF_DOT " File Share owns the card");
    } else if (strcmp(st, "no card") == 0) {
        snprintf(buf, sizeof buf, "no microSD card inserted");
    } else if (strcmp(st, "err") == 0) {
        snprintf(buf, sizeof buf, "error opening the file " NOCSIF_DOT " see the log");
    } else {
        snprintf(buf, sizeof buf, "scanning " NOCSIF_DOT " tap Record to save adverts");
    }
    wifi_set_label(s_bpc_status, buf);
    lv_obj_set_style_text_color(s_bpc_status, rec ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    const char *path = nocsif_ble_pcap_path();
    wifi_set_label(s_bpc_file, path[0] ? path : "/sd/nocsif/ble/adv-NNN.pcap");

    uint32_t bytes = nocsif_ble_pcap_bytes();
    char kb[24];
    if (bytes >= 1024) {
        snprintf(kb, sizeof kb, "%u.%u KB",
                 (unsigned)(bytes / 1024), (unsigned)((bytes % 1024) * 10 / 1024));
    } else {
        snprintf(kb, sizeof kb, "%u B", (unsigned)bytes);
    }
    snprintf(buf, sizeof buf, "%u adverts " NOCSIF_DOT " %s " NOCSIF_DOT " %u dropped",
             (unsigned)nocsif_ble_pcap_frames(), kb, (unsigned)nocsif_ble_pcap_dropped());
    wifi_set_label(s_bpc_stats, buf);

    if (s_bpc_rec_lbl) {
        wifi_set_label(s_bpc_rec_lbl, rec ? "Stop recording" : "Record to SD");
        lv_obj_set_style_text_color(s_bpc_rec_lbl, rec ? NOCSIF_VIOLET : NOCSIF_BONE, 0);
    }
}

static void ble_pcap_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_bpc_status = s_bpc_file = s_bpc_stats = s_bpc_rec_lbl = NULL;
    nocsif_ble_request_release();   /* closes any recording and hands the radio back to WiFi */
}

static lv_obj_t *build_ble_pcap(void)
{
    nocsif_ble_init();

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Advert Capture", NULL, &content);
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);

    s_bpc_status = lv_label_create(content);
    lv_label_set_long_mode(s_bpc_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bpc_status, lv_pct(100));
    lv_obj_add_style(s_bpc_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bpc_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_bpc_status, "BLE advert capture");
    lv_obj_set_style_pad_bottom(s_bpc_status, 8, 0);

    lv_obj_t *rrow = wifi_menu_row(content, "Record to SD", NOCSIF_VIOLET,
                                   NULL, NULL, ble_pcap_rec_cb, NULL);
    s_bpc_rec_lbl = lv_obj_get_child(rrow, 0);

    s_bpc_file = lv_label_create(content);
    lv_label_set_long_mode(s_bpc_file, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_bpc_file, lv_pct(100));
    lv_obj_add_style(s_bpc_file, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_bpc_file, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_top(s_bpc_file, 12, 0);
    lv_label_set_text(s_bpc_file, "/sd/nocsif/ble/adv-NNN.pcap");

    s_bpc_stats = lv_label_create(content);
    lv_label_set_long_mode(s_bpc_stats, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bpc_stats, lv_pct(100));
    lv_obj_add_style(s_bpc_stats, &nocsif_style_row_name, 0);
    lv_obj_set_style_text_color(s_bpc_stats, NOCSIF_BONE, 0);
    lv_obj_set_style_pad_top(s_bpc_stats, 6, 0);
    lv_label_set_text(s_bpc_stats, "0 adverts");

    lv_obj_t *hint = lv_label_create(content);
    lv_label_set_long_mode(hint, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(hint, lv_pct(100));
    lv_obj_add_style(hint, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(hint, NOCSIF_ASH, 0);
    lv_obj_set_style_pad_top(hint, 16, 0);
    lv_label_set_text(hint, "each advertisement is saved as a BLE link-layer frame with RSSI "
                            "(LINKTYPE 256) " NOCSIF_DOT " opens in Wireshark. Retrieve the card over "
                            "File Share. Own space only.");

    nocsif_ble_request_scan(true);
    lv_timer_t *timer = lv_timer_create(ble_pcap_tick, 500, NULL);
    lv_obj_add_event_cb(scr, ble_pcap_deleted_cb, LV_EVENT_DELETE, timer);
    ble_pcap_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Signal Hunt screen, filling hunt (M7-P4.2) ---- *
 * Pins one scanned device and hunts it by live RSSI gradient — the
 * proximity score rises as you close in ("closer / farther"). Two views
 * share one screen: a device-pick list (tap to pin) and the hunt meter.
 * Reuses the P1 scan, since the pinned target's adverts drive ble.c's own
 * EMA. The eyes-free haptic channel and the IMU rotation-sweep bearing
 * land with M11; this handles the visual gradient. Own airspace only. */
#define HUNT_RSSI_MIN (-100)   /* maps to 0% proximity */
#define HUNT_RSSI_MAX (-40)    /* maps to 100% proximity */
#define HUNT_PICK     6        /* pick-list rows, kept small since the meter coexists in the LVGL pool, which a full 10-row list would already fill by itself */
#define HUNT_BINS     12       /* the bearing dial: one 30-degree heading bin per clock hour, max-hold RSSI */

/* ---- v2 compass (redesign) geometry, head-up: you always face up,
 * with the caret at 12 o'clock ---- * A ticked bezel (a static frame) plus
 * an 8-point accent rose that counter-rotates with your heading, so it
 * stays world-fixed ("relative north"); 12 calibration dots that fill grey
 * as you sweep each 30-degree sector, with the accent color over the
 * emitter; and a single needle that points at the strongest bearing and
 * brightens as the signal climbs. There's no magnetometer, so this is only
 * a relative rose — never true north. */
#define HUNT_DIAL_SZ  236      /* the compass box, in px — the hero, sized to fit the screen without scrolling */
#define HUNT_DIAL_C   118      /* center, HUNT_DIAL_SZ/2 */
#define HUNT_DOT_R    90       /* the calibration-dot ring radius, in px */
#define HUNT_NEEDLE_R 82       /* the needle tip's radius from center */
#define HUNT_NDL_SZ   176      /* the needle canvas box, in px, centered on the dial; radius 88 is bigger than tip 82 */
#define HUNT_CALIB_BINS 8      /* bins swept before the sweep counts as "trustworthy", clearing the spin hint */

static live_row_t s_bh[HUNT_PICK];
static lv_obj_t  *s_bh_pick, *s_bh_status, *s_bh_more, *s_bh_more_lbl;      /* the pick view */
static lv_obj_t  *s_bh_meter, *s_bh_target, *s_bh_pct, *s_bh_dbm, *s_bh_trend, *s_bh_seen;
static lv_obj_t  *s_bh_note;       /* the bottom line: the live relative-heading readout (F2) */
static lv_obj_t  *s_bh_dial, *s_bh_you, *s_bh_bearing;   /* the compass box, the you-caret, and the spin-hint text */
static lv_obj_t  *s_bh_dot[HUNT_BINS];                   /* the per-heading-bin calibration dots */
static lv_obj_t  *s_bh_needle, *s_bh_spin;               /* the filled-needle canvas (the redesign) and the spin-hint overlay */
static uint8_t   *s_bh_needle_buf;                       /* the needle canvas's ARGB8888 PSRAM buffer, freed on delete */
static bool       s_bh_meter_vis;                        /* whether the meter is currently shown, so scroll can reset to top on the pick-to-meter transition */
static int16_t    s_bh_bin[HUNT_BINS];                   /* the max-hold, smoothed RSSI per bin; HUNT_RSSI_MIN means empty */
static bool       s_bh_bin_seen[HUNT_BINS];
static int        s_bh_page;
static int        s_bh_ref_x10;   /* a lagging reference, smoothed times 10, used for the warmer/colder trend */

/* (F2) converts a relative heading into a clock-face position (1..12), for the eyes-free "~N o'clock" readout; 0 degrees is 12 */
static int hunt_clock_of(float deg)
{
    int c = (int)lroundf(deg / 30.0f) % 12;
    return c == 0 ? 12 : c;
}

/* Clears the bearing histogram, for a fresh sweep or a new location. */
static void hunt_bins_reset(void)
{
    for (int i = 0; i < HUNT_BINS; i++) { s_bh_bin[i] = HUNT_RSSI_MIN; s_bh_bin_seen[i] = false; }
}

static int hunt_pct(int sm);   /* forward declaration: defined below, used by the dial paint */

/* A smoothed heading for the dial. The raw GAMERV yaw is fine on its own, but sampling it only every 500ms made the dial step; a roughly 90ms repaint over a light circular EMA of it glides instead. */
static float s_bh_hd_smooth;
static bool  s_bh_hd_have;
static lv_timer_t *s_bh_fast;   /* the roughly 90ms dial-repaint timer */

/* (F2, slice 3) an eyes-free audio cue: proximity-driven beeps
 * whose rate and pitch rise as you close in. The raw tone channel isn't
 * gated by the system mute, so the on-screen toggle is its own separate
 * control. */
static lv_obj_t *s_bh_audio_lbl;   /* the "Audio cue" toggle's accessory label */
static bool      s_bh_audio_on;    /* whether the cue is enabled, persisted as "hunt_audio" */
static float     s_bh_beep_phase;  /* the beep-rate phase accumulator */
static float     s_bh_cue_lvl;     /* (section 4.13, fix #4) a low-passed proximity level (0..100)
                                    * driving both the beep rate and pitch, so they glide with the trend
                                    * instead of jumping around with the raw, noisy percentage sampled at
                                    * each fire */

/* (F2) radio mode plus the WiFi (AP) hunt target. WiFi RSSI comes
 * from the monitor's live AP table (the parser), smoothed UI-side here —
 * BLE does its own smoothing in ble.c. Only one radio at a time: the mode
 * toggle hands the 2.4GHz radio between the BLE observer and the WiFi
 * monitor. */
static bool      s_bh_wifi;        /* false means BLE devices, true means WiFi APs; see also s_bh_lora */
static lv_obj_t *s_bh_mode_lbl;    /* the mode toggle's accessory ("BLE" / "WiFi" / "LoRa") */

/* (M9) LoRa energy-hunt mode: a third radio for Signal Hunt,
 * direction-finding a frequency — a signal detected by Band Survey — by
 * its RSSI. When s_bh_lora is set it overrides s_bh_wifi. The target is a
 * frequency rather than a device list; entering from Band Survey presets
 * it via s_hunt_lora_pending_mhz. */
static bool      s_bh_lora;        /* true means LoRa hunt mode, overriding s_bh_wifi */
static bool      s_bh_lora_targeted;  /* whether a frequency has been chosen (meter) versus still picking (survey list) */
static float     s_bh_lora_mhz;    /* the chosen frequency, in MHz */
static float     s_hunt_lora_pending_mhz;  /* the Band Survey to Signal Hunt hand-off; 0 means none */
static bool      s_wh_active;      /* whether a WiFi AP is currently pinned */
static uint8_t   s_wh_bssid[6];
static char      s_wh_name[33];
static uint8_t   s_wh_ch;
static float     s_wh_ema;         /* the UI-smoothed AP RSSI, in dBm */
static int       s_wh_peak;
static bool      s_wh_have;        /* whether at least one fresh reading has been captured */

/* (section 4.14) the pick-list order (strongest first), the
 * radio-aware RSSI scale, and the "signal present" gate. s_bh_order maps a
 * list slot (page*HUNT_PICK + row) to a module table index; it's rebuilt
 * on every 500ms pick tick alongside the rows, and the row tap reads the
 * same map, so a tap always lands on the device it's showing. The
 * proximity scale (hunt_pct) runs from s_bh_rssi_min to HUNT_RSSI_MAX:
 * -100 dBm for BLE/WiFi, but the SX1262's noise floor sits around
 * -110 to -120 dBm, so on the fixed scale every LoRa reading read as "0%"
 * — equal weight in every heading bin, and therefore no bearing at all no
 * matter how much you spun. In LoRa mode the floor instead comes from the
 * band survey's noise-floor estimate (then the lowest envelope seen this
 * session), and a reading only counts as a real signal (s_bh_sig_ok — bins
 * get logged, the spin prompt shows) once it sits HUNT_LORA_SIG_DB above
 * that floor. */
#define HUNT_ORDER_MAX       48    /* at least BLE_DEV_MAX (48) / MON_AP_MAX (32) / NOCSIF_LORA_SURVEY_SIGS (8) */
#define HUNT_LORA_FLOOR_DFLT (-120)
#define HUNT_LORA_SIG_DB     6     /* the envelope must clear the floor by this much to count as energy */
static uint8_t   s_bh_order[HUNT_ORDER_MAX];
static int       s_bh_order_n;
static int       s_bh_rssi_min = HUNT_RSSI_MIN;   /* the bottom of the proximity scale for the active radio */
static int       s_bh_lora_floor = HUNT_LORA_FLOOR_DFLT;
static bool      s_bh_sig_ok;      /* whether a real signal is present — above the floor for LoRa, or simply heard for BLE/WiFi */

static void hunt_scale_reset(void)
{
    s_bh_rssi_min = s_bh_lora ? s_bh_lora_floor : HUNT_RSSI_MIN;
    s_bh_sig_ok   = false;
}
/* Seeds the LoRa floor from a band-survey snapshot, falling back to the default if NULL or implausible, then re-scales. */
static void hunt_lora_floor_init(const nocsif_lora_survey_t *sv)
{
    s_bh_lora_floor = (sv && sv->sweeps > 0 && sv->floor < -60 && sv->floor > -140) ? sv->floor : HUNT_LORA_FLOOR_DFLT;
    hunt_scale_reset();
}

static float ang_norm360(float a) { while (a < 0.0f) a += 360.0f; while (a >= 360.0f) a -= 360.0f; return a; }
static float ang_shortest(float target, float cur)   /* the signed smallest difference (target minus current), in the range -180..180 */
{
    float d = target - cur;
    while (d > 180.0f)  d -= 360.0f;
    while (d < -180.0f) d += 360.0f;
    return d;
}

/* The continuous peak bearing: a circular mean of the seen bins,
 * weighted by strength squared to emphasize the lobe, so the needle points
 * at a smoothly moving angle instead of snapping to the nearest 30-degree
 * bin. Returns false until at least one bin has been mapped. */
static bool hunt_peak_bearing(float *out)
{
    float sx = 0.0f, sy = 0.0f; bool any = false;
    for (int i = 0; i < HUNT_BINS; i++) {
        if (!s_bh_bin_seen[i]) continue;
        int pct = hunt_pct(s_bh_bin[i]);
        float w = (float)pct * (float)pct + 1.0f;    /* +1 so even a 0% bin still nudges the mean */
        float ang = (float)(i * 30) * (float)M_PI / 180.0f;
        sx += w * cosf(ang); sy += w * sinf(ang); any = true;
    }
    if (!any || (sx == 0.0f && sy == 0.0f)) return false;
    *out = ang_norm360(atan2f(sy, sx) * 180.0f / (float)M_PI);
    return true;
}

/* Brightens the accent color by proximity t (0..1): from a dim
 * accent to a bright one. Strength lives in the same element you're
 * already reading for direction — the needle's color and glow ramp up as
 * the signal climbs. */
static lv_color_t hunt_accent_bright(float t)
{
    uint32_t a = nocsif_accent_rgb();
    int r = (a >> 16) & 0xFF, g = (a >> 8) & 0xFF, b = a & 0xFF;
    if (t < 0.0f) t = 0.0f; if (t > 1.0f) t = 1.0f;
    r += (int)((238 - r) * t * 0.92f);
    g += (int)((238 - g) * t * 0.92f);
    b += (int)((238 - b) * t * 0.92f);
    return lv_color_hex(((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)b);
}

/* ---- the filled compass needle (redesign) ---- *
 * The v1 needle was a stroke-only lv_line kite — thin, hollow, and it
 * photographed with RGB fringing. This instead draws a filled, tapered
 * needle straight into an ARGB8888 PSRAM canvas, using the orrery's proven
 * direct-buffer technique: no lv_draw_sw_* calls per frame, and, unlike
 * v1's earlier attempt, no bitmap-rotate resample that would starve the
 * audio task. It has a fine point at the hub (so no center square), a
 * bulge in the first third, tapering to a fine tip. Redrawn head-up on
 * every fast tick; color and opacity ramp with proximity. */
#define HUNT_NDL_HALF 6.4f      /* the needle body's maximum half-width, in px */

/* Sets one needle pixel into the ARGB8888 buffer (stored as B,G,R,A in memory), keeping the strongest coverage value so oversampled spans anti-alias the edges without dark seams where they overlap. */
static inline void hunt_ndl_px(uint8_t *buf, int dim, size_t stride, int x, int y,
                               uint8_t r, uint8_t g, uint8_t b, uint8_t a)
{
    if ((unsigned)x >= (unsigned)dim || (unsigned)y >= (unsigned)dim) return;
    uint8_t *p = buf + (size_t)y * stride + (size_t)x * 4;
    if (a > p[3]) { p[0] = b; p[1] = g; p[2] = r; p[3] = a; }
}

/* Rasterizes the needle at `ang_deg` (0 means up) from the canvas center outward to `len` px. Walks the spine, laying down an anti-aliased perpendicular span whose half-width tapers per the profile — cheap and gap-free. */
static void hunt_needle_draw(uint8_t *buf, int dim, size_t stride, float ang_deg, float len,
                             lv_color_t col, uint8_t max_a)
{
    memset(buf, 0, stride * (size_t)dim);                 /* clears to transparent */
    float th = ang_deg * (float)M_PI / 180.0f;
    float dx = sinf(th), dy = -cosf(th);                  /* the unit vector along the needle, 0 degrees pointing up */
    float px = -dy, py = dx;                              /* the unit vector perpendicular to it */
    float c  = (float)dim * 0.5f;
    uint8_t r = col.red, g = col.green, b = col.blue;
    for (float s = 0.0f; s <= len; s += 0.5f) {
        float t = s / len;                                /* 0 at the hub, 1 at the tip */
        float hw = (t < 0.28f) ? 1.1f + (HUNT_NDL_HALF - 1.1f) * (t / 0.28f)
                               : HUNT_NDL_HALF * powf((1.0f - t) / 0.72f, 0.85f);
        float ox = c + dx * s, oy = c + dy * s;
        for (float u = -hw; u <= hw; u += 0.5f) {
            float cov = hw - fabsf(u);                    /* a roughly 1px anti-aliased edge */
            if (cov > 1.0f) cov = 1.0f; else if (cov < 0.0f) cov = 0.0f;
            hunt_ndl_px(buf, dim, stride, (int)lroundf(ox + px * u), (int)lroundf(oy + py * u),
                        r, g, b, (uint8_t)(cov * (float)max_a));
        }
    }
}

/* Repaints the v2 compass, head-up so you always face up. Fills
 * each calibration dot grey as its 30-degree sector is swept, with the
 * accent color over the emitter; points the filled needle at the strongest
 * bearing and brightens it with proximity. Called on the roughly 90ms
 * tick with the live proximity (0..100) and whether the target is
 * currently heard. Cheap: it just repositions the dots and redraws the
 * small needle canvas. */
static void hunt_dial_paint(int prox, bool heard)
{
    if (s_bh_dial == NULL) return;
    bool  have_hd = s_bh_hd_have;
    float hd      = s_bh_hd_smooth;
    lv_color_t accent = nocsif_accent();

    int seen_cnt = 0;
    for (int i = 0; i < HUNT_BINS; i++) if (s_bh_bin_seen[i]) seen_cnt++;
    float pk; bool have_pk = hunt_peak_bearing(&pk);
    bool calibrated = have_hd && have_pk && seen_cnt >= HUNT_CALIB_BINS;

    /* the emitter's dot is the bin nearest the resolved peak bearing */
    int dev_bin = -1;
    if (have_pk) { dev_bin = ((int)lroundf(pk / 30.0f)) % HUNT_BINS; if (dev_bin < 0) dev_bin += HUNT_BINS; }

    /* the 12 calibration dots, head-up: hollow until swept, grey once swept, accent-colored over the emitter */
    for (int i = 0; i < HUNT_BINS; i++) {
        float a = (float)(i * 30);
        if (have_hd) a -= hd;
        float ar = a * (float)M_PI / 180.0f;
        int dx = (int)lroundf((float)HUNT_DOT_R * sinf(ar));
        int dy = (int)lroundf(-(float)HUNT_DOT_R * cosf(ar));
        lv_obj_align(s_bh_dot[i], LV_ALIGN_CENTER, dx, dy);
        bool is_dev = (i == dev_bin) && s_bh_bin_seen[i] && have_pk;
        if (is_dev) {
            lv_obj_set_size(s_bh_dot[i], 10, 10);
            lv_obj_set_style_radius(s_bh_dot[i], 5, 0);
            lv_obj_set_style_border_width(s_bh_dot[i], 0, 0);
            lv_obj_set_style_bg_opa(s_bh_dot[i], LV_OPA_COVER, 0);
            lv_obj_set_style_bg_color(s_bh_dot[i], accent, 0);
        } else if (s_bh_bin_seen[i]) {
            lv_obj_set_size(s_bh_dot[i], 7, 7);
            lv_obj_set_style_radius(s_bh_dot[i], 4, 0);
            lv_obj_set_style_border_width(s_bh_dot[i], 0, 0);
            lv_obj_set_style_bg_opa(s_bh_dot[i], LV_OPA_COVER, 0);
            lv_obj_set_style_bg_color(s_bh_dot[i], NOCSIF_STEEL, 0);
        } else {
            lv_obj_set_size(s_bh_dot[i], 7, 7);
            lv_obj_set_style_radius(s_bh_dot[i], 4, 0);
            lv_obj_set_style_bg_opa(s_bh_dot[i], LV_OPA_TRANSP, 0);
            lv_obj_set_style_border_width(s_bh_dot[i], 1, 0);
            lv_obj_set_style_border_color(s_bh_dot[i], NOCSIF_EDGE2, 0);
            lv_obj_set_style_border_opa(s_bh_dot[i], LV_OPA_COVER, 0);
        }
    }

    /* the needle: filled and tapered, head-up, visible (dimly) from the start pointing up, swinging to the peak bearing and brightening as the signal climbs. Drawn into the ARGB8888 canvas, with no center hub. */
    float na = have_pk ? (pk - hd) : 0.0f;              /* pointing up until a peak resolves */
    float t  = (heard && have_pk) ? (float)prox / 100.0f : 0.0f;
    lv_color_t ncol = hunt_accent_bright(t);
    uint8_t max_a = (uint8_t)(96 + (int)(159.0f * t));  /* dim-but-visible, ramping to full brightness as proximity climbs */
    if (s_bh_needle && s_bh_needle_buf) {
        size_t stride = lv_draw_buf_width_to_stride(HUNT_NDL_SZ, LV_COLOR_FORMAT_ARGB8888);
        hunt_needle_draw(s_bh_needle_buf, HUNT_NDL_SZ, stride, na, (float)HUNT_NEEDLE_R, ncol, max_a);
        lv_obj_invalidate(s_bh_needle);
    }

    /* the spin prompt, a center overlay instruction shown until the sweep is trustworthy. (Section 4.14: in LoRa mode it's honest — no engine or no energy on the channel says so, rather than just telling you to spin.) */
    if (s_bh_spin) {
        if (calibrated) lv_obj_add_flag(s_bh_spin, LV_OBJ_FLAG_HIDDEN);
        else            lv_obj_clear_flag(s_bh_spin, LV_OBJ_FLAG_HIDDEN);
    }
    if (s_bh_bearing) {
        nocsif_imu_state_t ist = nocsif_imu_state();
        const char *bt = (ist == NOCSIF_IMU_BOOTING) ? "motion sensor starting\xE2\x80\xA6"
                       : (ist != NOCSIF_IMU_ONLINE)   ? "motion sensor offline"
                       : (s_bh_lora && !s_bh_sig_ok)  ? (nocsif_lora_hunting()
                                                          ? "no energy on the channel " NOCSIF_DOT " nothing to bin"
                                                          : "LoRa engine unavailable " NOCSIF_DOT " retrying")
                       : !have_hd                     ? "heading settling\xE2\x80\xA6"
                       :                                 "spin to set the bearing";
        wifi_set_label(s_bh_bearing, bt);
    }
}

static int hunt_pct(int sm)
{
    int p = (sm - s_bh_rssi_min) * 100 / (HUNT_RSSI_MAX - s_bh_rssi_min);   /* (section 4.14) the radio-aware floor */
    if (p < 0)   p = 0;
    if (p > 100) p = 100;
    return p;
}

static void hunt_set_radio(void);   /* forward declaration: defined alongside the radio-agnostic helpers below, which read the mode globals */

/* Tapping a pick-list row pins that device, AP, or frequency as the hunt target. */
static void ble_hunt_row_cb(lv_event_t *e)
{
    int pool_i = (int)(intptr_t)lv_event_get_user_data(e);
    int slot = s_bh_page * HUNT_PICK + pool_i;
    if (slot >= s_bh_order_n) return;                  /* the row isn't backed by anything this tick */
    int idx = s_bh_order[slot];                        /* (section 4.14) rows are strongest-first, via hunt_order_build */

    if (s_bh_lora) {
        /* (section 4.14) only survey-detected signals are listed now; the pre-seeded 915 "home" row is gone */
        nocsif_lora_survey_t s;
        float mhz = 0.0f;
        if (nocsif_lora_survey_snapshot(&s) && idx < s.nsig) {
            mhz = nocsif_lora_survey_freq_mhz(s.sig[idx].bin);
            hunt_lora_floor_init(&s);                  /* the survey's noise floor anchors the scale */
        }
        if (mhz > 0.0f) {
            s_bh_lora_mhz = mhz;
            s_bh_lora_targeted = true;
            s_bh_ref_x10 = 0;
            hunt_bins_reset();
            hunt_scale_reset();
            hunt_set_radio();   /* stops the survey, parks on and hunts this frequency */
        }
        return;
    }

    if (s_bh_wifi) {
        nocsif_wifi_mon_ap_t ap;
        if (idx < nocsif_wifi_mon_ap_count() && nocsif_wifi_mon_ap_get(idx, &ap)) {
            memcpy(s_wh_bssid, ap.bssid, 6);
            snprintf(s_wh_name, sizeof s_wh_name, "%s", ap.ssid[0] ? ap.ssid : "(hidden)");
            s_wh_ch = ap.channel;
            s_wh_have = false; s_wh_ema = 0.0f; s_wh_peak = HUNT_RSSI_MIN;
            s_wh_active = true;
            s_bh_ref_x10 = 0;
            hunt_bins_reset();
            nocsif_wifi_request_monitor_channel(ap.channel);   /* locks to hear its beacons */
        }
        return;
    }

    nocsif_ble_dev_t d;
    if (idx < nocsif_ble_dev_count() && nocsif_ble_dev_get(idx, &d)) {
        char addr[20];
        const char *label = d.name;
        if (!label[0]) {
            snprintf(addr, sizeof addr, "%02x:%02x:%02x:%02x:%02x:%02x",
                     d.addr[5], d.addr[4], d.addr[3], d.addr[2], d.addr[1], d.addr[0]);
            label = addr;
        }
        s_bh_ref_x10 = 0;
        hunt_bins_reset();
        nocsif_ble_hunt_set_target(d.addr, d.addr_type, label);
    }
}

static void ble_hunt_unpin_cb(lv_event_t *e)
{
    (void)e;
    if (s_bh_lora) {
        s_bh_lora_targeted = false;
        s_bh_ref_x10 = 0;
        hunt_bins_reset();
        hunt_scale_reset();
        hunt_set_radio();   /* stops the hunt, resumes the survey, returning to the LoRa signal pick list */
        return;
    }
    if (s_bh_wifi) { s_wh_active = false; nocsif_wifi_request_monitor_hop(true); }   /* resumes discovery */
    else           { nocsif_ble_hunt_clear(); }
    hunt_scale_reset();
}

static void ble_hunt_sweep_reset_cb(lv_event_t *e) { (void)e; hunt_bins_reset(); }

/* Cycles BLE to WiFi to LoRa hunt mode: drops the current target, hands the radio over, resets the sweep. (BLE and WiFi share the one 2.4GHz radio; LoRa is the separate SX1262, direction-finding a frequency.) */
static void ble_hunt_mode_cb(lv_event_t *e)
{
    (void)e;
    if (s_bh_lora)      { nocsif_lora_hunt_stop(); nocsif_lora_set_survey(false); }
    else if (s_bh_wifi) s_wh_active = false;
    else                nocsif_ble_hunt_clear();

    if (!s_bh_wifi && !s_bh_lora) { s_bh_wifi = true;  s_bh_lora = false; }   /* BLE to WiFi */
    else if (s_bh_wifi)           { s_bh_wifi = false; s_bh_lora = true;  }   /* WiFi to LoRa */
    else                          { s_bh_wifi = false; s_bh_lora = false; }   /* LoRa to BLE */
    s_bh_lora_targeted = false;   /* enters LoRa on the signal pick list, not straight into a hunt */

    s_bh_page = 0;
    s_bh_ref_x10 = 0;
    s_bh_order_n = 0;             /* (section 4.14) the order gets rebuilt with the rows on the next pick tick */
    hunt_bins_reset();
    hunt_scale_reset();
    for (int i = 0; i < HUNT_PICK; i++) if (s_bh[i].row) { lv_obj_add_flag(s_bh[i].row, LV_OBJ_FLAG_HIDDEN); s_bh[i].bars = -1; }
    if (s_bh_mode_lbl) lv_label_set_text(s_bh_mode_lbl, s_bh_lora ? "LoRa" : s_bh_wifi ? "WiFi" : "BLE");
    hunt_set_radio();
}

static void ble_hunt_audio_cb(lv_event_t *e)
{
    (void)e;
    if (!nocsif_audio_tx_ready()) {
        return;   /* I2S TX never claimed its DMA — the reserve failed, or safe mode — so the cue is n/a and the tap becomes a no-op */
    }
    s_bh_audio_on = !s_bh_audio_on;
    nocsif_settings_set_i32("hunt_audio", s_bh_audio_on ? 1 : 0);
    if (s_bh_audio_lbl) {
        lv_label_set_text(s_bh_audio_lbl, s_bh_audio_on ? "audio on" : "audio off");
        lv_obj_set_style_text_color(s_bh_audio_lbl, s_bh_audio_on ? nocsif_accent() : NOCSIF_STEEL, 0);
    }
    s_bh_beep_phase = 0.0f;
    s_bh_cue_lvl    = 0.0f;   /* (section 4.13, fix #4) starts the cue ramp from silence on each toggle */
    if (s_bh_audio_on) nocsif_audio_tone(880, 45, 70);   /* a confirm blip */
}

static void ble_hunt_page_cb(lv_event_t *e)
{
    (void)e;
    int n = s_bh_order_n;                     /* (section 4.14) whichever radio's list is currently showing; used to be BLE-only */
    int pages = (n + HUNT_PICK - 1) / HUNT_PICK;
    if (pages < 1) pages = 1;
    s_bh_page = (s_bh_page + 1) % pages;
}

/* ---- the radio-agnostic hunt view: a BLE device or a WiFi AP ---- */
static bool hunt_target_active(void)
{
    if (s_bh_lora) return s_bh_lora_targeted;
    return s_bh_wifi ? s_wh_active : nocsif_ble_hunt_active();
}

/* (section 4.14) a user back — swipe-right or the header arrow — while hunting drops the pinned target and returns to the pick list, the same thing the Unpin button does; a second back from the pick list pops the screen. */
static bool hunt_back_hook(void)
{
    if (!hunt_target_active()) return false;
    ble_hunt_unpin_cb(NULL);
    return true;
}

/* (section 4.14) the strongest-first order for the pick list: an
 * index array over the active radio's table, sorted by RSSI (BLE
 * last-seen / WiFi AP last-seen / LoRa survey peak), stable so ties keep
 * discovery order. Runs on the 500ms pick tick, right before the rows are
 * filled, and the row tap reads the same map. */
static void hunt_order_build(int n, const nocsif_lora_survey_t *sv)
{
    if (n > HUNT_ORDER_MAX) n = HUNT_ORDER_MAX;
    int8_t rs[HUNT_ORDER_MAX];
    for (int i = 0; i < n; i++) {
        int r = HUNT_RSSI_MIN - 1;                    /* unreadable entries sink to the bottom */
        if (s_bh_lora)      { if (sv && i < sv->nsig) r = sv->sig[i].peak_rssi; }
        else if (s_bh_wifi) { nocsif_wifi_mon_ap_t ap; if (nocsif_wifi_mon_ap_get(i, &ap)) r = ap.rssi; }
        else                { nocsif_ble_dev_t d;      if (nocsif_ble_dev_get(i, &d))      r = d.rssi;  }
        if (r < -127) r = -127;
        if (r > 127)  r = 127;
        rs[i] = (int8_t)r;
        s_bh_order[i] = (uint8_t)i;
    }
    for (int i = 1; i < n; i++) {                     /* an insertion sort (n is at most 48), descending, stable */
        uint8_t o = s_bh_order[i];
        int8_t  r = rs[o];
        int j = i - 1;
        while (j >= 0 && rs[s_bh_order[j]] < r) { s_bh_order[j + 1] = s_bh_order[j]; j--; }
        s_bh_order[j + 1] = o;
    }
    s_bh_order_n = n;
}

static const char *hunt_target_str(void)
{
    if (s_bh_lora) {
        static char b[24];
        snprintf(b, sizeof b, "%.2f MHz", (double)s_bh_lora_mhz);
        return b;
    }
    if (s_bh_wifi) return s_wh_active ? s_wh_name : "no target";
    return nocsif_ble_hunt_target_str();
}

/* Fills a LoRa pick-list row: "NNN.NN MHz" plus a parameter subtitle and strength bars. */
static void hunt_lora_row_fill(live_row_t *r, float mhz, const char *sub, int rssi)
{
    if (!r->row) return;
    char nm[24];
    snprintf(nm, sizeof nm, "%.2f MHz", (double)mhz);
    lv_label_set_text(r->name, nm);
    lv_label_set_text(r->meta, sub);
    wifi_live_set_bars(r, (int8_t)rssi);
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);
}

/* Folds the pinned WiFi AP's live RSSI, from the monitor's AP table, into the UI's EMA. Called once per fast tick in WiFi mode. */
static void wifi_hunt_ema_update(void)
{
    if (!s_wh_active) return;
    int n = nocsif_wifi_mon_ap_count();
    for (int i = 0; i < n; i++) {
        nocsif_wifi_mon_ap_t ap;
        if (nocsif_wifi_mon_ap_get(i, &ap) && memcmp(ap.bssid, s_wh_bssid, 6) == 0) {
            if (ap.age_ms < 4000) {
                if (!s_wh_have) { s_wh_ema = ap.rssi; s_wh_peak = ap.rssi; s_wh_have = true; }
                else { s_wh_ema += ((float)ap.rssi - s_wh_ema) * 0.30f;
                       if (ap.rssi > s_wh_peak) s_wh_peak = ap.rssi; }
            }
            return;
        }
    }
}

/* a unified snapshot for whichever radio is currently active */
typedef struct { bool heard; int smoothed; int peak; uint32_t age_ms; unsigned frames; } huntview_t;
static void huntview_get(huntview_t *v)
{
    v->heard = false; v->smoothed = HUNT_RSSI_MIN; v->peak = HUNT_RSSI_MIN;
    v->age_ms = 0xFFFFFFFFu; v->frames = 0;
    if (s_bh_lora) {
        nocsif_lora_hunt_t h;
        if (!nocsif_lora_hunt_snapshot(&h)) return;
        v->smoothed = h.smoothed; v->peak = h.peak; v->age_ms = h.age_ms; v->frames = h.frames;
        v->heard = h.heard;
        return;
    }
    if (s_bh_wifi) {
        if (!s_wh_active) return;
        int n = nocsif_wifi_mon_ap_count();
        for (int i = 0; i < n; i++) {
            nocsif_wifi_mon_ap_t ap;
            if (nocsif_wifi_mon_ap_get(i, &ap) && memcmp(ap.bssid, s_wh_bssid, 6) == 0) {
                v->age_ms = ap.age_ms; v->frames = ap.frames;
                if (s_wh_have) { v->smoothed = (int)lroundf(s_wh_ema); v->peak = s_wh_peak;
                                 v->heard = (ap.age_ms < 4000); }
                return;
            }
        }
    } else {
        nocsif_ble_hunt_t h;
        if (!nocsif_ble_hunt_snapshot(&h)) return;
        v->smoothed = h.smoothed; v->peak = h.peak; v->age_ms = h.age_ms; v->frames = h.frames;
        v->heard = (h.age_ms != 0xFFFFFFFFu);
    }
}

/* Brings the LoRa worker up and arms survey/hunt. Its 8 KB stack
 * now lives in PSRAM (nocsif_lora_init, RAM-BUDGET.md remake #8), so there's
 * no more internal-DMA gate: it spawns whether WiFi is up or a phone
 * transfer is in flight, with no more "turn Bluetooth off to hunt LoRa"
 * wall and no self-heal-until-the-hole-forms retry loop. LoRa is the
 * SX1262, a separate radio, running alongside the resident BLE controller
 * and WiFi. */
static void hunt_lora_bringup(void)
{
    if (nocsif_reliability_safe_mode()) return;
    if (nocsif_lora_init() != ESP_OK) return;  /* the worker create failed, which is rare: retry next tick */
    if (!nocsif_lora_surveying() && !nocsif_lora_hunting()) {
        if (s_bh_lora_targeted) nocsif_lora_set_hunt(s_bh_lora_mhz);
        else                    nocsif_lora_set_survey(true);
    }
}

/* Signal Hunt's "clean switch": makes the selected radio the one
 * doing reconnaissance, and stops the others' activity.
 *
 * Critical invariants — three things are never re-initialized or
 * power-cycled at runtime, all proven the hard way on-device across three
 * failed attempts:
 *   1. The BLE controller is never torn down. Its roughly 31.7 KB
 *      contiguous block is reserved once at boot and can't be reclaimed at
 *      runtime — teardown/rebuild crashed the NimBLE host task, and even a
 *      full WiFi deinit only recovers about 21 KB. BLE is only ever
 *      scanned on or off; the resident controller and phone link stay put,
 *      which is what guarantees Bluetooth never needs a reboot to come
 *      back.
 *   2. WiFi's driver is never de-initialized — once the controller is
 *      resident there's only about 13 KB of free internal DMA left, far
 *      too little to re-run esp_wifi_init without an out-of-memory retry
 *      loop.
 *   3. WiFi's radio is also never stopped/started — esp_wifi_stop/start
 *      churned the STA into a disconnect-reconnect loop (reason codes
 *      4/205) under coexistence and drained internal DMA. Since the lean
 *      WiFi driver mostly lives in PSRAM anyway, powering it down would
 *      free almost nothing.
 *
 * So the only thing that actually toggles is the promiscuous monitor
 * (request_parse/monitor) — flipping sniffer mode on the already-running,
 * still-associated STA, with no re-init or re-association. WiFi stays
 * connected the whole time; in BLE/LoRa modes it simply isn't sniffing.
 * LoRa's worker keeps a PSRAM stack, so it spawns reliably (no
 * internal-DMA gate) and stays warm across switches — entering another
 * radio's mode only stops LoRa's survey/hunt activity, it never churns the
 * worker itself. */
static void hunt_set_radio(void)
{
    ESP_LOGI(TAG, "hunt radio -> %s; int-dma free=%u largest=%u",
             s_bh_lora ? "LoRa" : s_bh_wifi ? "WiFi" : "BLE",
             (unsigned)nocsif_int_dma_free(),
             (unsigned)nocsif_int_dma_largest());
    if (s_bh_lora) {
        /* LoRa (SX1262): stops the BLE scan, controller stays resident, plus the WiFi sniffer, STA stays associated */
        nocsif_ble_request_scan(false);
        nocsif_wifi_request_parse(false);
        nocsif_wifi_request_monitor(false);
        hunt_lora_bringup();                       /* a PSRAM stack, so this always spawns, with no gate and no wall */
    } else if (s_bh_wifi) {
        /* WiFi monitor: stops the BLE scan, controller stays resident, stops LoRa's activity but keeps its
         * worker warm (a PSRAM stack, no churn per switch), turns the sniffer on with no re-association */
        nocsif_ble_request_scan(false);
        nocsif_lora_set_survey(false);
        nocsif_lora_hunt_stop();
        nocsif_wifi_request_parse(true);          /* the promiscuous monitor plus the AP parser, i.e. the live RSSI table */
        nocsif_wifi_request_monitor_hop(true);    /* discovers across channels until a target is pinned */
    } else {
        /* BLE observer: stops LoRa's activity, worker stays warm, plus the WiFi sniffer, STA stays
         * associated, scanning on the resident controller */
        nocsif_lora_set_survey(false);
        nocsif_lora_hunt_stop();
        nocsif_wifi_request_parse(false);
        nocsif_wifi_request_monitor(false);
        nocsif_ble_request_scan(true);
    }
}

/* A fast, roughly 90ms repaint: smooths the heading and redraws the dial, so rotation glides instead of stepping. The heavier work — labels, the pick list, bin logging — stays on the 500ms tick below. */
static void ble_hunt_fast_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bh_meter == NULL) return;

    float raw;
    if (nocsif_imu_heading_deg(&raw)) {
        if (!s_bh_hd_have) { s_bh_hd_smooth = raw; s_bh_hd_have = true; }
        else s_bh_hd_smooth = ang_norm360(s_bh_hd_smooth + ang_shortest(raw, s_bh_hd_smooth) * 0.35f);
    }

    if (s_bh_note) {
        if (s_bh_hd_have) {
            char nb[56];
            snprintf(nb, sizeof nb, "heading %d\xC2\xB0 " NOCSIF_DOT " relative, no compass",
                     (int)lroundf(s_bh_hd_smooth));
            wifi_set_label(s_bh_note, nb);
        } else if (nocsif_imu_online()) {
            wifi_set_label(s_bh_note, "heading " NOCSIF_DOT " settling\xE2\x80\xA6 (rotate to test)");
        } else {
            wifi_set_label(s_bh_note, "heading " NOCSIF_DOT " motion sensor offline");
        }
    }

    if (s_bh_wifi) wifi_hunt_ema_update();

    if (hunt_target_active()) {
        huntview_t v; huntview_get(&v);
        int pct = v.heard ? hunt_pct(v.smoothed) : 0;
        hunt_dial_paint(pct, v.heard);            /* needle brightness reflects proximity */

        /* an eyes-free proximity cue: beep rate and pitch rise as the
         * signal strengthens. A phase accumulator over the roughly 90ms tick
         * fires nocsif_audio_tone (the raw channel, so the on-screen toggle is
         * its own mute). (Section 4.13, fix #4: both outputs are driven from a
         * low-passed cue level, s_bh_cue_lvl, instead of the raw percentage, so
         * a noisy RSSI no longer makes both timing and pitch jitter together —
         * the cue glides instead.) */
        if (s_bh_audio_on && nocsif_audio_tx_ready()) {
            if (v.heard) {
                /* alpha 0.15, slower than the 0.30 dial EMA, so the cue follows
                 * the overall trend rather than the ripple (don't re-tune the dial
                 * EMA to match — that's a separate, deliberately faster smoother). */
                s_bh_cue_lvl += ((float)pct - s_bh_cue_lvl) * 0.15f;
                float rate = 1.5f + s_bh_cue_lvl / 100.0f * 3.5f;  /* 1.5 to 5 Hz */
                s_bh_beep_phase += rate * 0.090f;
                if (s_bh_beep_phase >= 1.0f) {
                    s_bh_beep_phase -= 1.0f;
                    uint32_t freq = (uint32_t)(500.0f + s_bh_cue_lvl * 6.5f);   /* roughly 500 to 1150 Hz */
                    nocsif_audio_tone(freq, 40, 70);
                }
            } else {
                s_bh_cue_lvl += (0.0f - s_bh_cue_lvl) * 0.15f;    /* decays toward silence once the target is lost */
                s_bh_beep_phase = 0.0f;                           /* silent while still acquiring */
            }
        }
    }
}

static void ble_hunt_tick(lv_timer_t *t)
{
    (void)t;
    if (s_bh_meter == NULL) {
        return;
    }

    if (hunt_target_active()) {
        /* ---- the HUNT view ---- */
        lv_obj_add_flag(s_bh_pick, LV_OBJ_FLAG_HIDDEN);
        lv_obj_clear_flag(s_bh_meter, LV_OBJ_FLAG_HIDDEN);
        if (!s_bh_meter_vis) {   /* pick-to-meter: the meter is fixed-height and fits the viewport,
                                  * so it lands at the top with scroll clamped off — the tall pick list
                                  * left `content` scrollable, and a scrolled `content` would ride the top
                                  * percentage up under the transparent header, clipping it. */
            lv_obj_t *cont = lv_obj_get_parent(s_bh_meter);
            if (cont) {
                lv_obj_update_layout(cont);
                lv_obj_scroll_to_y(cont, 0, LV_ANIM_OFF);
                if (lv_obj_get_scroll_bottom(cont) <= 0)   /* the meter fits, so scroll is clamped so the percentage can't ride
                                                            * up under the header; if it ever overflowed, scroll is kept so the
                                                            * controls stay reachable */
                    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
            }
            s_bh_meter_vis = true;
        }

        /* Keeps WiFi capture up and locked to the pinned AP's channel. A
         * parse request can land before the radio is ready if the screen was
         * entered straight from a Live-Networks tap, so it's re-asserted here
         * too. */
        if (s_bh_wifi && s_wh_active && !nocsif_reliability_safe_mode()) {
            if (!nocsif_wifi_parse_active())                   nocsif_wifi_request_parse(true);  /* (re)arms the sniffer */
            else if (nocsif_wifi_monitor_channel() != s_wh_ch) nocsif_wifi_request_monitor_channel(s_wh_ch);
        }
        /* The same for a targeted LoRa hunt entered from a Band-Survey
         * tap: ensures the 8 KB worker exists — freeing WiFi's RAM if it's
         * tight — and is parked on the frequency, self-healing across the
         * async yield. */
        if (s_bh_lora && s_bh_lora_targeted && !nocsif_reliability_safe_mode()) {
            hunt_lora_bringup();
        }

        huntview_t v;
        huntview_get(&v);
        wifi_set_label(s_bh_target, hunt_target_str());

        /* (section 4.14) "signal present": LoRa's envelope must clear
         * the session floor, since a parked frequency with no transmitter
         * would otherwise read the floor forever, and floor readings carry no
         * real bearing information (see s_bh_sig_ok); for BLE/WiFi it's
         * simply "heard". This gates the bin logging below and the spin
         * prompt on the dial. */
        if (s_bh_lora) {
            if (v.heard && v.smoothed < s_bh_lora_floor) { s_bh_lora_floor = v.smoothed; s_bh_rssi_min = v.smoothed; }
            s_bh_sig_ok = nocsif_lora_hunting() && v.heard && v.smoothed >= s_bh_lora_floor + HUNT_LORA_SIG_DB;
        } else {
            s_bh_sig_ok = v.heard;
        }

        char buf[64];
        if (s_bh_lora && !nocsif_lora_hunting()) {         /* (section 4.14) honest: the engine simply isn't running */
            wifi_set_label(s_bh_pct, "\xE2\x80\x94");
            wifi_set_label(s_bh_dbm, "LoRa engine unavailable");
            wifi_set_label(s_bh_seen, "retrying the radio worker\xE2\x80\xA6");
        } else if (!v.heard) {
            wifi_set_label(s_bh_pct, "\xE2\x80\x94");   /* an em dash */
            wifi_set_label(s_bh_dbm, s_bh_wifi ? "acquiring beacons\xE2\x80\xA6" : "acquiring\xE2\x80\xA6");
            wifi_set_label(s_bh_seen, s_bh_lora ? "reading the channel " NOCSIF_DOT " keep still"
                                    : s_bh_wifi  ? "no beacons yet " NOCSIF_DOT " hold on its channel"
                                                 : "no adverts yet " NOCSIF_DOT " keep still");
        } else {
            int pct = hunt_pct(v.smoothed);
            snprintf(buf, sizeof buf, "%d", pct);
            wifi_set_label(s_bh_pct, buf);
            if (s_bh_lora) snprintf(buf, sizeof buf, "%d dBm " NOCSIF_DOT " peak %d " NOCSIF_DOT " floor %d",
                                    v.smoothed, v.peak, s_bh_lora_floor);
            else           snprintf(buf, sizeof buf, "%d dBm " NOCSIF_DOT " peak %d", v.smoothed, v.peak);
            wifi_set_label(s_bh_dbm, buf);

            /* (F2) logs this reading into the heading bin currently being
             * faced (max-hold — the strongest RSSI seen while pointed that way is
             * roughly that direction's signal, body-shadow lobe and all).
             * (Section 4.14: only a real signal gets binned — floor readings
             * would just fill every dot grey.) */
            if (s_bh_hd_have && s_bh_sig_ok) {
                int bin = (int)(s_bh_hd_smooth / 30.0f) % HUNT_BINS;
                if (bin < 0) bin += HUNT_BINS;
                if (!s_bh_bin_seen[bin] || v.smoothed > s_bh_bin[bin]) s_bh_bin[bin] = v.smoothed;
                s_bh_bin_seen[bin] = true;
            }

            /* the meta line under the name: live/stale plus a frame count.
             * Direction and closer/farther now live in the compass itself — the
             * needle plus its brightness — so the older warmer/colder text has
             * been retired. */
            if (s_bh_lora && !s_bh_sig_ok)
                                 snprintf(buf, sizeof buf, "no energy on the channel " NOCSIF_DOT " needs a transmitter");
            else if (v.age_ms < 1500) snprintf(buf, sizeof buf, "live " NOCSIF_DOT " %u frames", v.frames);
            else                 snprintf(buf, sizeof buf, "stale %us " NOCSIF_DOT " move or target quiet",
                                          (unsigned)(v.age_ms / 1000));
            wifi_set_label(s_bh_seen, buf);
        }
        return;
    }

    /* ---- the PICK view ---- */
    lv_obj_clear_flag(s_bh_pick, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(s_bh_meter, LV_OBJ_FLAG_HIDDEN);
    { lv_obj_t *cont = lv_obj_get_parent(s_bh_pick);   /* the device list can overflow, so scroll is restored — the meter
                                                        * view had clamped it off so the percentage couldn't ride up under
                                                        * the header */
      if (cont) lv_obj_add_flag(cont, LV_OBJ_FLAG_SCROLLABLE); }
    s_bh_meter_vis = false;

    /* Radio-mode self-heal, since requests are async. Nothing is
     * re-initialized or power-cycled here — WiFi's sniffer just toggles on
     * the already-running STA, BLE scans on the resident controller, and
     * LoRa is best-effort. A request that lands one tick early simply gets
     * re-asserted on the next tick. */
    if (s_bh_lora) {
        /* Keeps trying to spawn the 8 KB LoRa worker — it only fits when the phone link is idle, so this is best-effort — then keeps the band survey running so the signal list fills in. */
        hunt_lora_bringup();
    } else if (s_bh_wifi && !nocsif_reliability_safe_mode()) {
        if (!nocsif_wifi_parse_active())                        nocsif_wifi_request_parse(true);  /* (re)arms the sniffer */
        else if (!s_wh_active && !nocsif_wifi_monitor_hopping()) nocsif_wifi_request_monitor_hop(true);
    } else if (!s_bh_wifi && !nocsif_reliability_safe_mode()) {
        /* A BLE observer scan for the pick list. With
         * CONFIG_BT_CTRL_BLE_MAX_ACT=3, the scan runs alongside the resident
         * controller's phone advert and with WiFi up too — it just needs a
         * controller activity slot, not a big contiguous heap block (proven
         * on-device: the scan starts fine even with largest ~960 bytes free).
         * So it's just kept scanning, exactly like the Scan Devices screen.
         * The old gate — !ble_available plus largest>=24KB, else yield WiFi —
         * never actually fired once the controller became resident at boot
         * (available was already true) and the heap never reached 24 KB —
         * which is why Signal Hunt used to show no BLE scan at all. */
        if (!nocsif_ble_scan_active() && !nocsif_ble_starting())
            nocsif_ble_request_scan(true);
    }

    char buf[72];
    const char *msg;
    bool active;
    int  n;
    if (s_bh_lora) {
        nocsif_lora_survey_t sv;
        int nsig = nocsif_lora_survey_snapshot(&sv) ? sv.nsig : 0;
        active = nocsif_lora_surveying();
        n = nsig;                           /* (section 4.14) only survey-detected signals, since the 915 preset row is gone */
        if (n > HUNT_PICK) n = HUNT_PICK;
        if (nsig <= 0) {
            msg = "scanning 902\xE2\x80\x93""928 MHz " NOCSIF_DOT " waiting for signals";
        } else {
            snprintf(buf, sizeof buf, "%d signal%s " NOCSIF_DOT " tap one to hunt it", nsig, nsig == 1 ? "" : "s");
            msg = buf;
        }
    } else if (s_bh_wifi) {
        active = nocsif_wifi_parse_active();
        n      = nocsif_wifi_mon_ap_count();
        if (nocsif_reliability_safe_mode())    msg = "WiFi disabled (safe mode)";
        else if (!active)                      msg = "starting monitor\xE2\x80\xA6";
        else if (n <= 0)                       msg = "scanning " NOCSIF_DOT " tap an AP to hunt it";
        else { snprintf(buf, sizeof buf, "%d network%s " NOCSIF_DOT " tap one to hunt", n, n == 1 ? "" : "s");
               msg = buf; }
    } else {
        active = nocsif_ble_scan_active();
        n      = nocsif_ble_dev_count();
        if (nocsif_reliability_safe_mode())    msg = "BLE disabled (safe mode)";
        else if (!nocsif_ble_available() && !nocsif_ble_starting())
                                               msg = "switching to BLE\xE2\x80\xA6";
        else if (nocsif_ble_starting())        msg = "starting " NOCSIF_DOT " releasing WiFi\xE2\x80\xA6";
        else if (!active)                      msg = "stopped " NOCSIF_DOT " tap a device to pin & hunt";
        else if (n <= 0)                       msg = "scanning " NOCSIF_DOT " tap a device to hunt it";
        else { snprintf(buf, sizeof buf, "%d device%s " NOCSIF_DOT " tap one to hunt", n, n == 1 ? "" : "s");
               msg = buf; }
    }
    wifi_set_label(s_bh_status, msg);
    lv_obj_set_style_text_color(s_bh_status, active ? NOCSIF_VIOLET : NOCSIF_STEEL, 0);

    int pages = (n + HUNT_PICK - 1) / HUNT_PICK;
    if (pages < 1)          pages = 1;
    if (s_bh_page >= pages) s_bh_page = 0;
    int base = s_bh_page * HUNT_PICK;
    nocsif_lora_survey_t lsv;
    bool lsv_have = s_bh_lora && nocsif_lora_survey_snapshot(&lsv);
    hunt_order_build(n, lsv_have ? &lsv : NULL);        /* (section 4.14) strongest first; the tap reads the same map */
    for (int i = 0; i < HUNT_PICK; i++) {
        int slot = base + i;
        bool filled = false;
        if (slot < s_bh_order_n) {
            int idx = s_bh_order[slot];
            if (s_bh_lora) {
                if (lsv_have && idx < lsv.nsig) {
                    const nocsif_lora_signal_t *sg = &lsv.sig[idx];
                    char sub[56];
                    snprintf(sub, sizeof sub, "%d dBm " NOCSIF_DOT " %.1f MHz " NOCSIF_DOT " %lu hits",
                             sg->peak_rssi, sg->span_bins * 0.5, (unsigned long)sg->hits);
                    hunt_lora_row_fill(&s_bh[i], nocsif_lora_survey_freq_mhz(sg->bin), sub, sg->peak_rssi);
                    filled = true;
                }
            } else if (s_bh_wifi) {
                nocsif_wifi_mon_ap_t ap;
                if (nocsif_wifi_mon_ap_get(idx, &ap)) { wifi_mgmt_ap_fill(&s_bh[i], &ap, false); filled = true; }
            } else {
                nocsif_ble_dev_t d;
                if (nocsif_ble_dev_get(idx, &d)) { ble_dev_row_fill(&s_bh[i], &d); filled = true; }
            }
        }
        if (!filled && s_bh[i].row) {
            lv_obj_add_flag(s_bh[i].row, LV_OBJ_FLAG_HIDDEN);
            s_bh[i].bars = -1;
        }
    }
    if (s_bh_more && s_bh_more_lbl) {
        if (n > HUNT_PICK) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_bh_page + 1, pages, HUNT_PICK);
            wifi_set_label(s_bh_more_lbl, buf);
            lv_obj_clear_flag(s_bh_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_bh_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void ble_hunt_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    if (s_bh_fast) { lv_timer_delete(s_bh_fast); s_bh_fast = NULL; }
    s_bh_pick = s_bh_status = s_bh_more = s_bh_more_lbl = NULL;
    s_bh_meter = s_bh_target = s_bh_pct = s_bh_dbm = s_bh_trend = s_bh_seen = NULL;
    s_bh_note = NULL;
    s_bh_dial = s_bh_you = s_bh_bearing = s_bh_audio_lbl = s_bh_mode_lbl = NULL;
    if (s_bh_needle_buf) { heap_caps_free(s_bh_needle_buf); s_bh_needle_buf = NULL; }   /* the canvas doesn't own its own buffer */
    s_bh_needle = s_bh_spin = NULL;
    for (int i = 0; i < HUNT_PICK; i++) s_bh[i].row = s_bh[i].name = s_bh[i].meta = NULL;
    for (int i = 0; i < HUNT_BINS; i++) s_bh_dot[i] = NULL;
    nocsif_imu_set_heading(false);  /* (F2) drops the gyro-backed heading sensor, returning idle draw to the accelerometer */
    nocsif_ble_hunt_clear();
    s_wh_active = false;
    /* Stops whichever radio this screen was driving and restores the
     * coexistence baseline. The BLE controller is only quiesced
     * (nocsif_ble_request_release — resident with the phone advert re-armed,
     * never actually torn down), so Bluetooth comes back instantly with no
     * reboot needed. WiFi, which Signal Hunt yields off in BLE/LoRa modes,
     * is restored to its lean profile. */
    nocsif_lora_deinit();           /* LoRa: sleeps the radio, cuts its rail, frees the 8 KB worker; a no-op if it was never up */
    s_bh_lora = false;
    s_bh_lora_targeted = false;
    nocsif_wifi_request_parse(false);   /* stops the sniffer; the STA link itself was never touched, so it stays up */
    nocsif_wifi_request_monitor(false);
    nocsif_ble_request_release();   /* quiesced: the controller stays resident, with no teardown and no reboot */
}

/* a compact bottom-row control button for the v2 compass, label-only, equal width */
static lv_obj_t *hunt_ctrl_btn(lv_obj_t *parent, const char *txt, lv_event_cb_t cb, lv_obj_t **lbl_out)
{
    lv_obj_t *b = lv_button_create(parent);
    lv_obj_remove_style_all(b);
    lv_obj_set_flex_grow(b, 1);
    lv_obj_set_height(b, 44);
    lv_obj_set_style_radius(b, 14, 0);
    lv_obj_set_style_border_width(b, 1, 0);
    lv_obj_set_style_border_color(b, NOCSIF_EDGE, 0);
    lv_obj_set_style_border_opa(b, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(b, NOCSIF_PIT_ON, 0);
    lv_obj_set_style_bg_opa(b, LV_OPA_50, 0);
    lv_obj_set_style_bg_color(b, NOCSIF_EDGE2, LV_STATE_PRESSED);
    lv_obj_set_style_bg_opa(b, LV_OPA_COVER, LV_STATE_PRESSED);
    lv_obj_t *l = lv_label_create(b);
    lv_obj_set_style_text_font(l, &nocsif_mono_12, 0);
    lv_obj_set_style_text_color(l, NOCSIF_STEEL, 0);
    lv_label_set_text(l, txt);
    lv_obj_center(l);
    lv_obj_add_event_cb(b, cb, LV_EVENT_CLICKED, NULL);
    if (lbl_out) *lbl_out = l;
    return b;
}

/* A stars-only backdrop for Signal Hunt: a few faint star dots
 * scattered around the periphery, kept clear of the central compass,
 * sitting behind the header and content on the flat dark ground. This
 * gives the clean "just stars" field the operator wanted — the busy
 * orrery rings and engraved stars are hidden behind the screen's opaque
 * background — without touching the global wallpaper. Static, drawn once;
 * cheap, since it's only a handful of tiny objects. */
static void hunt_build_starfield(lv_obj_t *scr)
{
    static const struct { int16_t x, y; uint8_t d, opa; } stars[] = {
        {  34, 120, 2, 120 }, {  72, 188, 2,  70 }, {  26, 300, 2,  84 }, {  54, 250, 1,  60 },
        {  22, 402, 2,  92 }, {  66, 452, 2,  62 }, { 118, 150, 1,  72 }, { 356, 120, 2, 112 },
        { 330, 200, 2,  72 }, { 384, 300, 2,  86 }, { 356, 250, 1,  60 }, { 386, 410, 2,  96 },
        { 340, 452, 2,  62 }, { 300, 150, 1,  70 }, { 150, 470, 2,  76 }, { 262, 470, 2,  60 },
        { 206, 432, 1,  55 },
    };
    for (unsigned i = 0; i < sizeof(stars) / sizeof(stars[0]); i++) {
        lv_obj_t *s = lv_obj_create(scr);
        lv_obj_remove_style_all(s);
        lv_obj_set_size(s, stars[i].d, stars[i].d);
        lv_obj_set_style_radius(s, LV_RADIUS_CIRCLE, 0);
        lv_obj_set_style_bg_color(s, NOCSIF_BONE, 0);
        lv_obj_set_style_bg_opa(s, stars[i].opa, 0);
        lv_obj_set_pos(s, stars[i].x, stars[i].y);
        lv_obj_add_flag(s, LV_OBJ_FLAG_IGNORE_LAYOUT);
        lv_obj_clear_flag(s, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_move_background(s);   /* behind the header and content */
    }
}

static lv_obj_t *build_ble_hunt(void)
{
    nocsif_ble_init();
    /* The LoRa worker is created on demand by hunt_lora_bringup() when the Radio toggle enters LoRa mode — eager creation here used to fail ("failed to create lora worker task") whenever WiFi held the RAM. */
    s_bh_page = 0;
    s_bh_ref_x10 = 0;
    s_bh_hd_have = false;
    s_bh_meter_vis = false;
    s_bh_order_n = 0;
    hunt_bins_reset();
    /* An honest audio gate (RAM Phase 2 #12/C7): the cue can only
 * play if the I2S TX actually claimed its DMA at boot
 * (nocsif_audio_tx_ready). If the reserve failed, or safe mode skipped it,
 * the cue is forced off so the toggle reads "audio n/a" instead of a dead
 * "audio on" that never actually plays anything. */
    s_bh_audio_on = nocsif_audio_tx_ready() && nocsif_settings_get_i32("hunt_audio", 1) != 0;
    s_bh_beep_phase = 0.0f;
    s_bh_cue_lvl    = 0.0f;   /* (section 4.13, fix #4) resets the cue ramp on screen build */
    s_wh_active = false;

    /* Did Live Networks hand us a WiFi AP to hunt? Enter straight onto the WiFi meter, channel-locked to it (mirroring the LoRa hand-off below). */
    if (s_hunt_wifi_pending.valid) {
        s_bh_wifi = true; s_bh_lora = false; s_bh_lora_targeted = false;
        memcpy(s_wh_bssid, s_hunt_wifi_pending.bssid, 6);
        snprintf(s_wh_name, sizeof s_wh_name, "%s", s_hunt_wifi_pending.name);
        s_wh_ch = s_hunt_wifi_pending.channel;
        s_wh_have = false; s_wh_ema = 0.0f; s_wh_peak = HUNT_RSSI_MIN;
        s_wh_active = true;
        s_hunt_wifi_pending.valid = false;
        nocsif_lora_hunt_stop();
        nocsif_ble_request_release();
        nocsif_wifi_request_parse(true);                /* the AP parser feeds the live RSSI table */
        nocsif_wifi_request_monitor_channel(s_wh_ch);   /* locks to hear its beacons */
    }
    /* Enters in LoRa mode if a Band-Survey signal handed us a frequency; otherwise defaults to BLE. */
    else if (s_hunt_lora_pending_mhz > 0.0f) {
        s_bh_lora = true;
        s_bh_lora_targeted = true;   /* the survey already chose the frequency, so it goes straight to the meter */
        s_bh_wifi = false;
        s_bh_lora_mhz = s_hunt_lora_pending_mhz;
        s_hunt_lora_pending_mhz = 0.0f;
        nocsif_lora_survey_t sv;     /* (section 4.14) the survey's noise floor anchors the LoRa proximity scale */
        hunt_lora_floor_init(nocsif_lora_survey_snapshot(&sv) ? &sv : NULL);
        hunt_set_radio();   /* RAM-managed LoRa bring-up, freeing WiFi's RAM if it's tight, plus parking on the frequency;
                             * the hunt-view tick self-heals until the worker actually spawns */
    } else {
        s_bh_lora = false;
        s_bh_lora_targeted = false;
        s_bh_wifi = false;      /* always enters in BLE mode */
        hunt_set_radio();       /* a clean switch: WiFi off, scanning on the resident controller */
    }
    hunt_scale_reset();

    lv_obj_t *content;
    lv_obj_t *scr = nocsif_screen_scaffold("Signal Hunt", NULL, &content);
    nocsif_nav_set_back_hook(scr, hunt_back_hook);   /* (section 4.14) back while hunting returns to the pick list first */
    lv_obj_set_style_pad_hor(content, 26, 0);   /* a corner-safe inset */
    lv_obj_set_style_pad_bottom(content, 4, 0); /* reclaims the scaffold's 22px tail, so the fixed-height hunt
                                                 * meter — the name/% row, the 236px hero compass, and controls — fits
                                                 * the viewport with no scroll range at all; otherwise `content` would
                                                 * scroll and the top percentage would ride up under the transparent
                                                 * header, which was the clipping's root cause. */
    lv_obj_clear_flag(content, LV_OBJ_FLAG_SCROLL_ELASTIC | LV_OBJ_FLAG_SCROLL_MOMENTUM);
    /* A stars-only backdrop on just this screen: an opaque dark
     * ground — hiding the busy orrery rings and engraved stars — scattered
     * with a few faint star dots, so the compass reads cleanly without the
     * wallpaper competing for attention. Self-contained; the global
     * wallpaper is untouched. */
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x050506), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    hunt_build_starfield(scr);

    /* ===== the PICK view: the device list ===== */
    s_bh_pick = lv_obj_create(content);
    lv_obj_remove_style_all(s_bh_pick);
    lv_obj_set_width(s_bh_pick, lv_pct(100));
    lv_obj_set_height(s_bh_pick, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_bh_pick, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(s_bh_pick, LV_OBJ_FLAG_SCROLLABLE);

    /* the radio mode toggle, BLE devices versus WiFi APs, at the top of the pick list */
    lv_obj_t *moderow = wifi_menu_row(s_bh_pick, "Radio", NOCSIF_VIOLET,
                                      s_bh_lora ? "LoRa" : s_bh_wifi ? "WiFi" : "BLE",
                                      &s_bh_mode_lbl, ble_hunt_mode_cb, NULL);
    lv_obj_set_width(moderow, lv_pct(100));

    s_bh_status = lv_label_create(s_bh_pick);
    lv_label_set_long_mode(s_bh_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_bh_status, lv_pct(100));
    lv_obj_set_style_text_font(s_bh_status, &nocsif_mono_12, 0);
    lv_obj_set_style_text_color(s_bh_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_bh_status, "pick a device to hunt");
    lv_obj_set_style_pad_bottom(s_bh_status, 8, 0);

    lv_obj_t *list = lv_obj_create(s_bh_pick);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
    for (int i = 0; i < HUNT_PICK; i++) {
        wifi_live_pool_row(list, &s_bh[i]);
        lv_obj_add_flag(s_bh[i].row, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_add_style(s_bh[i].row, &nocsif_style_row_press, LV_STATE_PRESSED);
        lv_obj_add_event_cb(s_bh[i].row, ble_hunt_row_cb, LV_EVENT_CLICKED, (void *)(intptr_t)i);
    }

    s_bh_more = lv_obj_create(s_bh_pick);
    lv_obj_remove_style_all(s_bh_more);
    lv_obj_set_width(s_bh_more, lv_pct(100));
    lv_obj_set_height(s_bh_more, LV_SIZE_CONTENT);
    lv_obj_set_style_pad_ver(s_bh_more, 12, 0);
    lv_obj_clear_flag(s_bh_more, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_bh_more, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_add_flag(s_bh_more, LV_OBJ_FLAG_GESTURE_BUBBLE);
    lv_obj_add_style(s_bh_more, &nocsif_style_row_press, LV_STATE_PRESSED);
    lv_obj_add_event_cb(s_bh_more, ble_hunt_page_cb, LV_EVENT_CLICKED, NULL);
    lv_obj_add_flag(s_bh_more, LV_OBJ_FLAG_HIDDEN);
    s_bh_more_lbl = lv_label_create(s_bh_more);
    lv_obj_set_style_text_font(s_bh_more_lbl, &nocsif_mono_12, 0);
    lv_obj_set_style_text_color(s_bh_more_lbl, NOCSIF_VIOLET, 0);
    lv_obj_set_width(s_bh_more_lbl, lv_pct(100));
    lv_obj_set_style_text_align(s_bh_more_lbl, LV_TEXT_ALIGN_CENTER, 0);
    lv_label_set_text(s_bh_more_lbl, "");

    /* ===== the HUNT view: the v2 compass — device name plus percentage on top, the big relative-bearing compass, and controls ===== */
    s_bh_meter = lv_obj_create(content);
    lv_obj_remove_style_all(s_bh_meter);
    lv_obj_set_width(s_bh_meter, lv_pct(100));
    lv_obj_set_height(s_bh_meter, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_bh_meter, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(s_bh_meter, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(s_bh_meter, 6, 0);
    lv_obj_set_style_pad_top(s_bh_meter, 6, 0);    /* a small amount of breathing room; the percentage no longer
                                                    * rides the header, since the meter now fits with no scroll range
                                                    * (see the scroll clamp and the reclaimed content pad_bottom above) */
    lv_obj_set_style_pad_hor(s_bh_meter, 22, 0);   /* insets the name/% row and controls into the corner-safe band
                                                    * (x in [48,362]); the compass is centered, so its size is
                                                    * unaffected */
    lv_obj_clear_flag(s_bh_meter, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_add_flag(s_bh_meter, LV_OBJ_FLAG_HIDDEN);

    /* --- the target row: device name on the left, proximity % plus dBm on the top-right --- */
    lv_obj_t *tgtrow = lv_obj_create(s_bh_meter);
    lv_obj_remove_style_all(tgtrow);
    lv_obj_set_width(tgtrow, lv_pct(100));
    lv_obj_set_height(tgtrow, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(tgtrow, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(tgtrow, LV_FLEX_ALIGN_SPACE_BETWEEN, LV_FLEX_ALIGN_START, LV_FLEX_ALIGN_START);
    lv_obj_clear_flag(tgtrow, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *who = lv_obj_create(tgtrow);              /* left: name plus meta */
    lv_obj_remove_style_all(who);
    lv_obj_set_flex_grow(who, 1);
    lv_obj_set_height(who, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(who, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_style_pad_row(who, 2, 0);
    lv_obj_set_style_pad_top(who, 6, 0);
    lv_obj_clear_flag(who, LV_OBJ_FLAG_SCROLLABLE);
    s_bh_target = lv_label_create(who);
    lv_label_set_long_mode(s_bh_target, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_bh_target, lv_pct(100));
    lv_obj_add_style(s_bh_target, &nocsif_style_title, 0);
    lv_obj_set_style_text_color(s_bh_target, NOCSIF_WHITE, 0);
    lv_label_set_text(s_bh_target, "target");
    s_bh_seen = lv_label_create(who);                  /* the meta/status line under the name */
    lv_label_set_long_mode(s_bh_seen, LV_LABEL_LONG_DOT);
    lv_obj_set_width(s_bh_seen, lv_pct(100));
    lv_obj_set_style_text_font(s_bh_seen, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(s_bh_seen, NOCSIF_STEEL, 0);
    lv_label_set_text(s_bh_seen, "");

    lv_obj_t *pcol = lv_obj_create(tgtrow);            /* right: a big percentage plus dBm */
    lv_obj_remove_style_all(pcol);
    lv_obj_set_size(pcol, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(pcol, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(pcol, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_top(pcol, 14, 0);             /* drops the percentage a touch below the device-name line, per
                                                        * operator preference for easier reading: 8px top-aligns the ink
                                                        * with the name, +6 more sits it just underneath. */
    lv_obj_clear_flag(pcol, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_t *pctrow = lv_obj_create(pcol);
    lv_obj_remove_style_all(pctrow);
    lv_obj_set_size(pctrow, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(pctrow, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(pctrow, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_END, LV_FLEX_ALIGN_END);
    lv_obj_set_style_pad_column(pctrow, 3, 0);
    lv_obj_clear_flag(pctrow, LV_OBJ_FLAG_SCROLLABLE);
    s_bh_pct = lv_label_create(pctrow);
    lv_obj_set_style_text_font(s_bh_pct, &nocsif_num_48, 0);
    lv_obj_set_style_text_color(s_bh_pct, NOCSIF_WHITE, 0);
    lv_label_set_text(s_bh_pct, "\xE2\x80\x94");       /* an em dash until it's heard */
    lv_obj_t *unit = lv_label_create(pctrow);
    lv_obj_set_style_text_font(unit, &nocsif_mono_15, 0);
    lv_obj_set_style_text_color(unit, NOCSIF_STEEL, 0);
    lv_obj_set_style_pad_bottom(unit, 8, 0);
    lv_label_set_text(unit, "%");
    s_bh_dbm = lv_label_create(pcol);
    lv_obj_set_style_text_font(s_bh_dbm, &nocsif_mono_11, 0);
    lv_obj_set_style_text_color(s_bh_dbm, NOCSIF_ASH, 0);
    lv_label_set_text(s_bh_dbm, "acquiring\xE2\x80\xA6");
    s_bh_trend = NULL;                                  /* retired: brightness now replaces the warmer/colder text */

    /* --- the compass, the hero — transparent, floating on the screen's flat dark background --- */
    s_bh_dial = lv_obj_create(s_bh_meter);
    lv_obj_remove_style_all(s_bh_dial);
    lv_obj_set_size(s_bh_dial, HUNT_DIAL_SZ, HUNT_DIAL_SZ);
    lv_obj_clear_flag(s_bh_dial, LV_OBJ_FLAG_SCROLLABLE);

    /* the ticked bezel, a static frame */
    lv_obj_t *scale = lv_scale_create(s_bh_dial);
    lv_obj_set_size(scale, HUNT_DIAL_SZ, HUNT_DIAL_SZ);
    lv_obj_center(scale);
    lv_scale_set_mode(scale, LV_SCALE_MODE_ROUND_INNER);
    lv_scale_set_total_tick_count(scale, 61);
    lv_scale_set_major_tick_every(scale, 5);
    lv_scale_set_range(scale, 0, 60);
    lv_scale_set_angle_range(scale, 360);
    lv_scale_set_rotation(scale, 270);
    lv_scale_set_label_show(scale, false);              /* no cardinal directions: a relative rose */
    lv_obj_set_style_bg_opa(scale, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_opa(scale, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_line_color(scale, NOCSIF_EDGE2, LV_PART_ITEMS);
    lv_obj_set_style_line_width(scale, 1, LV_PART_ITEMS);
    lv_obj_set_style_length(scale, 6, LV_PART_ITEMS);
    lv_obj_set_style_line_color(scale, NOCSIF_ASH, LV_PART_INDICATOR);
    lv_obj_set_style_line_width(scale, 2, LV_PART_INDICATOR);
    lv_obj_set_style_length(scale, 11, LV_PART_INDICATOR);
    lv_obj_clear_flag(scale, LV_OBJ_FLAG_CLICKABLE);

    /* the 12 calibration dots, hollow until swept */
    for (int i = 0; i < HUNT_BINS; i++) {
        s_bh_dot[i] = lv_obj_create(s_bh_dial);
        lv_obj_remove_style_all(s_bh_dot[i]);
        lv_obj_set_size(s_bh_dot[i], 7, 7);
        lv_obj_set_style_radius(s_bh_dot[i], 4, 0);
        lv_obj_set_style_bg_opa(s_bh_dot[i], LV_OPA_TRANSP, 0);
        lv_obj_set_style_border_width(s_bh_dot[i], 1, 0);
        lv_obj_set_style_border_color(s_bh_dot[i], NOCSIF_EDGE2, 0);
        lv_obj_set_style_border_opa(s_bh_dot[i], LV_OPA_COVER, 0);
        lv_obj_clear_flag(s_bh_dot[i], LV_OBJ_FLAG_SCROLLABLE);
        lv_obj_align(s_bh_dot[i], LV_ALIGN_CENTER, 0, -HUNT_DOT_R);
    }

    /* the needle: a filled, tapered accent needle drawn into an
     * ARGB8888 PSRAM canvas (the redesign). It sits above the ticks and
     * sweep dots, staying transparent elsewhere so they show through, and
     * comes to a fine point at the pivot, so there's no center hub or
     * square. Redrawn head-up on every fast tick. */
    s_bh_needle = NULL;
    s_bh_needle_buf = NULL;
    {
        size_t stride = lv_draw_buf_width_to_stride(HUNT_NDL_SZ, LV_COLOR_FORMAT_ARGB8888);
        s_bh_needle_buf = heap_caps_aligned_alloc(64, stride * (size_t)HUNT_NDL_SZ, MALLOC_CAP_SPIRAM);
        if (s_bh_needle_buf) {
            s_bh_needle = lv_canvas_create(s_bh_dial);
            lv_obj_remove_style_all(s_bh_needle);
            lv_canvas_set_buffer(s_bh_needle, s_bh_needle_buf, HUNT_NDL_SZ, HUNT_NDL_SZ, LV_COLOR_FORMAT_ARGB8888);
            lv_obj_center(s_bh_needle);
            lv_obj_clear_flag(s_bh_needle, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_SCROLLABLE);
            lv_canvas_fill_bg(s_bh_needle, NOCSIF_VOID, LV_OPA_TRANSP);
        }
    }

    /* a fixed you-caret at 12 o'clock, since you always face up, drawn above the needle */
    s_bh_you = lv_obj_create(s_bh_dial);
    lv_obj_remove_style_all(s_bh_you);
    lv_obj_set_size(s_bh_you, 4, 13);
    lv_obj_set_style_radius(s_bh_you, 2, 0);
    lv_obj_set_style_bg_opa(s_bh_you, LV_OPA_COVER, 0);
    lv_obj_set_style_bg_color(s_bh_you, NOCSIF_BONE, 0);
    lv_obj_align(s_bh_you, LV_ALIGN_TOP_MID, 0, 3);

    /* the spin prompt: the instruction, dead-center, until the sweep is trustworthy */
    s_bh_spin = lv_obj_create(s_bh_dial);
    lv_obj_remove_style_all(s_bh_spin);
    lv_obj_set_size(s_bh_spin, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(s_bh_spin, LV_FLEX_FLOW_COLUMN);
    lv_obj_set_flex_align(s_bh_spin, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_row(s_bh_spin, 6, 0);
    lv_obj_clear_flag(s_bh_spin, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_center(s_bh_spin);
    /* (No spin icon: the custom mono font subset has no LV_SYMBOL glyphs, so it rendered as a missing-glyph box — "the weird square in the middle". The text alone is the prompt now.) */
    s_bh_bearing = lv_label_create(s_bh_spin);
    lv_obj_set_style_text_font(s_bh_bearing, &nocsif_mono_13, 0);
    lv_obj_set_style_text_color(s_bh_bearing, NOCSIF_BONE, 0);
    lv_label_set_text(s_bh_bearing, "spin to set the bearing");

    /* --- the bottom controls: audio, reset sweep, pick target --- */
    lv_obj_t *ctrls = lv_obj_create(s_bh_meter);
    lv_obj_remove_style_all(ctrls);
    lv_obj_set_width(ctrls, lv_pct(100));
    lv_obj_set_height(ctrls, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(ctrls, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(ctrls, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(ctrls, 9, 0);
    lv_obj_set_style_margin_top(ctrls, 2, 0);
    lv_obj_clear_flag(ctrls, LV_OBJ_FLAG_SCROLLABLE);
    /* An honest audio toggle: reads "audio n/a" in steel, non-actionable, whenever the I2S TX never claimed its DMA. */
    bool audio_ok = nocsif_audio_tx_ready();
    hunt_ctrl_btn(ctrls, audio_ok ? (s_bh_audio_on ? "audio on" : "audio off") : "audio n/a",
                  ble_hunt_audio_cb, &s_bh_audio_lbl);
    if (audio_ok && s_bh_audio_on && s_bh_audio_lbl) lv_obj_set_style_text_color(s_bh_audio_lbl, nocsif_accent(), 0);
    hunt_ctrl_btn(ctrls, "reset sweep", ble_hunt_sweep_reset_cb, NULL);
    hunt_ctrl_btn(ctrls, "pick target", ble_hunt_unpin_cb, NULL);
    s_bh_note = NULL;                                   /* the heading readout is retired; the compass shows it now */

    nocsif_imu_set_heading(true);   /* (F2) brings the relative-heading (GAMERV) sensor up while hunting */
    /* The BLE scan is started by the tick's heap-gated self-heal
     * below — on a fresh, healthy heap that happens immediately; after heavy
     * WiFi use it instead waits for the internal-DMA heap to recover, so the
     * controller never inits into a failing allocation. */
    lv_timer_t *timer = lv_timer_create(ble_hunt_tick, 500, NULL);
    s_bh_fast = lv_timer_create(ble_hunt_fast_tick, 90, NULL);   /* a smooth dial repaint */
    lv_obj_add_event_cb(scr, ble_hunt_deleted_cb, LV_EVENT_DELETE, timer);
    ble_hunt_tick(timer);   /* seeded immediately */
    return scr;
}

/* ---- Drone Detection screen, filling ble.drone (M7-P4.4)
 * ---- * Surfaces the OpenDroneID / ASTM F3411 Remote ID that compliant
 * drones broadcast over Bluetooth, parsed in ble.c from the 0xFFFA service
 * data. Two views share one screen, the hunt pattern: a small pick list of
 * detected drones, opening into a detail panel with the drone's identity,
 * its own position, and the operator's (pilot's) position. Reuses the P1
 * observer; a small DRONE_PICK pool keeps both views inside the LVGL heap.
 * Pure airspace awareness — no transmit, own airspace only. */
#define DRONE_PICK 5

static live_row_t s_drn[DRONE_PICK];
static lv_obj_t  *s_dr_pick, *s_dr_status, *s_dr_more, *s_dr_more_lbl;      /* the pick view */
static lv_obj_t  *s_dr_detail, *s_dr_id, *s_dr_type, *s_dr_pos, *s_dr_motion,
                 *s_dr_pilot, *s_dr_opid, *s_dr_seen;                        /* the detail view */
static int        s_dr_page;
static uint8_t    s_dr_sel_addr[6];
static bool       s_dr_has_sel;

static void ble_drone_tick(lv_timer_t *t);   /* the row/page/back callbacks refresh immediately */

/* Formats a deg*1e7 coordinate as a signed decimal string with 5 fractional digits. */
static void ble_fmt_coord(char *out, size_t sz, int32_t e7)
{
    const char *sign = (e7 < 0) ? "-" : "";
    uint32_t a  = (e7 < 0) ? (uint32_t)(-(int64_t)e7) : (uint32_t)e7;
    uint32_t ip = a / 10000000u;
    uint32_t fp = (a % 10000000u) / 100u;    /* 5 decimal places */
    snprintf(out, sz, "%s%u.%05u", sign, (unsigned)ip, (unsigned)fp);
}

static void ble_drone_row_fill(live_row_t *r, const nocsif_ble_drone_t *d)
{
    lv_obj_clear_flag(r->row, LV_OBJ_FLAG_HIDDEN);

    if (d->has_basic && d->uas_id[0]) {
        wifi_set_label(r->name, d->uas_id);
    } else {
        char id[24];
        snprintf(id, sizeof id, "Drone %02X%02X", d->addr[1], d->addr[0]);
        wifi_set_label(r->name, id);
    }
    lv_obj_set_style_text_color(r->name, NOCSIF_GOLD, 0);

    char buf[80];
    int off = snprintf(buf, sizeof buf, "%s", nocsif_ble_ua_type_str(d->ua_type));
    if (d->has_loc)          off += snprintf(buf + off, sizeof buf - off, " " NOCSIF_DOT " located");
    if (d->has_operator_loc) off += snprintf(buf + off, sizeof buf - off, " " NOCSIF_DOT " pilot");
    if (d->age_ms >= 1000)   off += snprintf(buf + off, sizeof buf - off, " " NOCSIF_DOT " %us",
                                             (unsigned)(d->age_ms / 1000));
    wifi_set_label(r->meta, buf);

    wifi_live_set_bars(r, d->rssi);
}

static void ble_drone_row_cb(lv_event_t *e)
{
    int pool_i = (int)(intptr_t)lv_event_get_user_data(e);
    int idx = s_dr_page * DRONE_PICK + pool_i;
    nocsif_ble_drone_t d;
    if (idx < nocsif_ble_drone_count() && nocsif_ble_drone_get(idx, &d)) {
        memcpy(s_dr_sel_addr, d.addr, 6);
        s_dr_has_sel = true;
        ble_drone_tick(NULL);   /* an immediate swap to the detail view */
    }
}

static void ble_drone_back_cb(lv_event_t *e) { (void)e; s_dr_has_sel = false; ble_drone_tick(NULL); }

static void ble_drone_page_cb(lv_event_t *e)
{
    (void)e;
    int n = nocsif_ble_drone_count();
    int pages = (n + DRONE_PICK - 1) / DRONE_PICK;
    if (pages < 1) pages = 1;
    s_dr_page = (s_dr_page + 1) % pages;
    ble_drone_tick(NULL);
}

static void ble_drone_tick(lv_timer_t *t)
{
    (void)t;
    if (s_dr_status == NULL) {
        return;
    }

    if (s_dr_has_sel) {
        /* ---- the DETAIL view ---- */
        lv_obj_add_flag(s_dr_pick, LV_OBJ_FLAG_HIDDEN);
        lv_obj_clear_flag(s_dr_detail, LV_OBJ_FLAG_HIDDEN);

        nocsif_ble_drone_t sel;
        bool live = false;
        int n = nocsif_ble_drone_count();
        for (int i = 0; i < n; i++) {
            nocsif_ble_drone_t d;
            if (nocsif_ble_drone_get(i, &d) && memcmp(d.addr, s_dr_sel_addr, 6) == 0) {
                sel = d; live = true; break;
            }
        }

        char buf[96], c1[20], c2[20];
        if (live && sel.has_basic && sel.uas_id[0]) {
            const char *idt = sel.id_type == 1 ? "serial" : sel.id_type == 2 ? "CAA reg" :
                              sel.id_type == 3 ? "UTM"    : sel.id_type == 4 ? "session" : "id";
            snprintf(buf, sizeof buf, "%s (%s)", sel.uas_id, idt);
        } else {
            snprintf(buf, sizeof buf, "identity not yet broadcast");
        }
        wifi_set_label(s_dr_id, buf);
        wifi_set_label(s_dr_type, live ? nocsif_ble_ua_type_str(sel.ua_type) : "\xE2\x80\x94");

        if (live && sel.has_loc) {
            ble_fmt_coord(c1, sizeof c1, sel.lat_e7);
            ble_fmt_coord(c2, sizeof c2, sel.lon_e7);
            snprintf(buf, sizeof buf, "Drone: %s, %s " NOCSIF_DOT " %dm", c1, c2, sel.alt_m);
        } else {
            snprintf(buf, sizeof buf, "Drone: locating\xE2\x80\xA6");
        }
        wifi_set_label(s_dr_pos, buf);

        if (live && sel.has_loc) {
            snprintf(buf, sizeof buf, "Speed %u.%u m/s " NOCSIF_DOT " Track %u\xC2\xB0",
                     (unsigned)(sel.speed_x10 / 10), (unsigned)(sel.speed_x10 % 10),
                     (unsigned)sel.track_deg);
        } else {
            buf[0] = '\0';
        }
        wifi_set_label(s_dr_motion, buf);

        if (live && sel.has_operator_loc) {
            ble_fmt_coord(c1, sizeof c1, sel.op_lat_e7);
            ble_fmt_coord(c2, sizeof c2, sel.op_lon_e7);
            snprintf(buf, sizeof buf, "Pilot: %s, %s", c1, c2);
            wifi_set_label(s_dr_pilot, buf);
            lv_obj_set_style_text_color(s_dr_pilot, NOCSIF_GOLD, 0);
        } else {
            wifi_set_label(s_dr_pilot, "Pilot: not broadcast yet");
            lv_obj_set_style_text_color(s_dr_pilot, NOCSIF_STEEL, 0);
        }

        if (live && sel.has_operator_id && sel.operator_id[0]) {
            snprintf(buf, sizeof buf, "Operator: %s", sel.operator_id);
        } else {
            buf[0] = '\0';
        }
        wifi_set_label(s_dr_opid, buf);

        if (!live) {
            snprintf(buf, sizeof buf, "signal lost " NOCSIF_DOT " tap Back");
        } else if (sel.age_ms < 2000) {
            snprintf(buf, sizeof buf, "%d dBm " NOCSIF_DOT " %u msgs " NOCSIF_DOT " live",
                     sel.rssi, (unsigned)sel.msgs);
        } else {
            snprintf(buf, sizeof buf, "%d dBm " NOCSIF_DOT " %u msgs " NOCSIF_DOT " %us ago",
                     sel.rssi, (unsigned)sel.msgs, (unsigned)(sel.age_ms / 1000));
        }
        wifi_set_label(s_dr_seen, buf);
        return;
    }

    /* ---- the PICK view ---- */
    lv_obj_clear_flag(s_dr_pick, LV_OBJ_FLAG_HIDDEN);
    lv_obj_add_flag(s_dr_detail, LV_OBJ_FLAG_HIDDEN);

    bool active = nocsif_ble_scan_active();
    int  n      = nocsif_ble_drone_count();
    char buf[80];
    const char *msg;
    if (nocsif_reliability_safe_mode())  msg = "BLE disabled (safe mode)";
    else if (nocsif_ble_starting())      msg = "starting " NOCSIF_DOT " releasing WiFi\xE2\x80\xA6";
    else if (!active)                    msg = n > 0 ? "stopped " NOCSIF_DOT " tap a drone for details"
                                                     : "stopped " NOCSIF_DOT " tap Start to scan";
    else if (n <= 0)                     msg = "scanning " NOCSIF_DOT " no Remote ID broadcasts yet";
    else { snprintf(buf, sizeof buf, "%d drone%s broadcasting " NOCSIF_DOT " tap for details",
                    n, n == 1 ? "" : "s"); msg = buf; }
    wifi_set_label(s_dr_status, msg);
    lv_obj_set_style_text_color(s_dr_status, n > 0 ? NOCSIF_GOLD
                                                   : (active ? NOCSIF_VIOLET : NOCSIF_STEEL), 0);

    int pages = (n + DRONE_PICK - 1) / DRONE_PICK;
    if (pages < 1)          pages = 1;
    if (s_dr_page >= pages) s_dr_page = 0;
    int base = s_dr_page * DRONE_PICK;
    for (int i = 0; i < DRONE_PICK; i++) {
        nocsif_ble_drone_t d;
        int idx = base + i;
        if (idx < n && nocsif_ble_drone_get(idx, &d)) {
            ble_drone_row_fill(&s_drn[i], &d);
        } else if (s_drn[i].row) {
            lv_obj_add_flag(s_drn[i].row, LV_OBJ_FLAG_HIDDEN);
            s_drn[i].bars = -1;
        }
    }
    if (s_dr_more && s_dr_more_lbl) {
        if (n > DRONE_PICK) {
            snprintf(buf, sizeof buf, "page %d/%d " NOCSIF_DOT " tap for next %d",
                     s_dr_page + 1, pages, DRONE_PICK);
            wifi_set_label(s_dr_more_lbl, buf);
            lv_obj_clear_flag(s_dr_more, LV_OBJ_FLAG_HIDDEN);
        } else {
            lv_obj_add_flag(s_dr_more, LV_OBJ_FLAG_HIDDEN);
        }
    }
}

static void ble_drone_deleted_cb(lv_event_t *e)
{
    lv_timer_t *timer = (lv_timer_t *)lv_event_get_user_data(e);
    if (timer) {
        lv_timer_delete(timer);
    }
    s_dr_pick = s_dr_status = s_dr_more = s_dr_more_lbl = NULL;
    s_dr_detail = s_dr_id = s_dr_type = s_dr_pos = s_dr_motion = s_dr_pilot = s_dr_opid = s_dr_seen = NULL;
    for (int i = 0; i < DRONE_PICK; i++) s_drn[i].row = s_drn[i].name = s_drn[i].meta = NULL;
    nocsif_ble_request_release();   /* hands the radio back to WiFi (only one radio) */
}

/* One left-aligned detail label in the panel. */
static lv_obj_t *ble_drone_detail_label(lv_obj_t *parent, const lv_font_t *font, lv_color_t col, int pad_top)
{
    lv_obj_t *l = lv_label_create(parent);
    lv_label_set_long_mode(l, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(l, lv_pct(100));
    nocsif_label_font_scaled(l, font);                   /* (section 4.13) mono 11/12/13 follow the type scale */
    lv_obj_set_style_text_color(l, col, 0);
    lv_obj_set_style_pad_top(l, pad_top, 0);
    lv_label_set_text(l, "");
    return l;
}

