    s_lm_status = lv_label_create(content);
    lv_label_set_long_mode(s_lm_status, LV_LABEL_LONG_WRAP);
    lv_obj_set_width(s_lm_status, lv_pct(100));
    lv_obj_add_style(s_lm_status, &nocsif_style_font_caption, 0);
    lv_obj_set_style_text_color(s_lm_status, NOCSIF_STEEL, 0);
    lv_label_set_text(s_lm_status, "");
    lv_obj_set_style_pad_bottom(s_lm_status, 4, 0);

    lora_pill(content, "Compose", lora_compose_open_cb);
    s_lm_listen_lbl = lora_pill(content, "Listening " NOCSIF_DOT " tap to pause", lora_listen_toggle_cb);

    lv_obj_t *list = lv_obj_create(content);
    lv_obj_remove_style_all(list);
    lv_obj_set_width(list, lv_pct(100));
    lv_obj_set_height(list, LV_SIZE_CONTENT);
    lv_obj_set_flex_flow(list, LV_FLEX_FLOW_COLUMN);
    lv_obj_clear_flag(list, LV_OBJ_FLAG_SCROLLABLE);
