    lv_obj_set_style_text_color(sl, NOCSIF_WHITE, 0);
    lv_obj_add_event_cb(save, devname_btn_cb, LV_EVENT_CLICKED, ta);

    /* the keyboard: lifted above the rounded bottom corners, the same geometry as the join screen */
